QT_ISI(18,{"2674":["(Sesungguhnya) lafal Qad di sini menunjukkan makna Tahqiq, artinya sungguh telah pasti (beruntunglah) berbahagialah (orang-orang yang beriman).",[["قَدْ","Indeed"],["أَفْلَحَ","successful"],["ٱلْمُؤْمِنُونَ","(are) the believers"]]],"2675":["(Yaitu orang-orang yang khusyuk dalam salatnya) dengan merendahkan diri penuh perasaan kepada Allah.",[["ٱلَّذِينَ","Those who"],["هُمْ","[they]"],["فِى","during"],["صَلَاتِهِمْ","their prayers"],["خَـٰشِعُونَ","(are) humbly submissive"]]],"2676":["(Dan orang-orang yang menjauhkan diri dari hal yang tiada berguna) berupa perkataan dan hal-hal lainnya.",[["وَٱلَّذِينَ","Those who"],["هُمْ","[they]"],["عَنِ","from"],["ٱللَّغْوِ","the vain talk"],["مُعْرِضُونَ","turn away"]]],"2677":["(Dan orang-orang yang terhadap zakat mereka menunaikannya) membayarnya.",[["وَٱلَّذِينَ","Those who"],["هُمْ","[they]"],["لِلزَّكَوٰةِ","of purification works"],["فَـٰعِلُونَ","(are) doers"]]],"2678":["(Dan orang-orang yang terhadap kemaluannya mereka selalu memeliharanya) dari yang diharamkan.",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["لِفُرُوجِهِمْ","of their modesty"],["حَـٰفِظُونَ","(are) guardians"]]],"2679":["(Kecuali terhadap istri-istri mereka) (atau terhadap budak yang mereka miliki) yakni hamba sahaya wanita yang mereka tawan dari peperangan (maka sesungguhnya mereka dalam hal ini tiada tercela) bila mereka mendatanginya.",[["إِلَّا","Except"],["عَلَىٰٓ","from"],["أَزْوَٰجِهِمْ","their spouses"],["أَوْ","or"],["مَا","what"],["مَلَكَتْ","possess"],["أَيْمَـٰنُهُمْ","their right hands"],["فَإِنَّهُمْ","then indeed, they"],["غَيْرُ","(are) not"],["مَلُومِينَ","blameworthy"]]],"2680":["(Barang siapa menginginkan yang selain itu) selain istri-istri sendiri dan sahaya wanita tawanan mereka untuk pelampiasan hajat biologisnya, seumpamanya melakukan masturbasi (maka mereka itulah orang-orang yang melampaui batas) yakni melampaui batas halal dan melakukan hal-hal yang diharamkan bagi mereka.",[["فَمَنِ","Then whoever"],["ٱبْتَغَىٰ","seeks"],["وَرَآءَ","beyond"],["ذَٰلِكَ","that"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْعَادُونَ","(are) the transgressors"]]],"2681":["(Dan orang-orang yang terhadap amanat yang dipercayakan kepada mereka) dapat dibaca secara jamak dan mufrad, yakni Amaanaatihim dan Amaanatihim (dan janji mereka) yang mereka adakan di antara sesama mereka atau antara mereka dengan Allah, seperti salat dan lain-lainnya (mereka memeliharanya) benar-benar menjaganya.",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["لِأَمَـٰنَـٰتِهِمْ","of their trusts"],["وَعَهْدِهِمْ","and their promise(s)"],["رَٰعُونَ","(are) observers"]]],"2682":["(Dan orang-orang yang terhadap salat mereka) dapat dibaca dalam bentuk jamak dan mufrad, yakni Shalawaatihim dan shalaatihim (mereka memeliharanya) mereka mengerjakannya tepat pada waktu-waktunya.",[["وَٱلَّذِينَ","And those who"],["هُمْ","[they]"],["عَلَىٰ","over"],["صَلَوَٰتِهِمْ","their prayers"],["يُحَافِظُونَ","they guard"]]],"2683":["(Mereka itulah orang-orang yang akan mewarisi) bukan selain mereka.",[["أُو۟لَـٰٓئِكَ","Those"],["هُمُ","[they]"],["ٱلْوَٰرِثُونَ","(are) the inheritors"]]],"2684":["(Yakni yang akan mewarisi surga Firdaus) yaitu surga yang tempatnya paling tinggi. (Mereka kekal di dalamnya) di dalam ayat-ayat yang telah lalu terkandung isyarat yang menunjukkan tempat kembali di akhirat. Hal ini sangat relevan bila disebutkan hal-hal yang menyangkut masalah permulaan atau asal kejadian, sesudah pembahasan tadi.",[["ٱلَّذِينَ","Who"],["يَرِثُونَ","will inherit"],["ٱلْفِرْدَوْسَ","the Paradise"],["هُمْ","They"],["فِيهَا","therein"],["خَـٰلِدُونَ","(will) abide forever"]]],"2685":["(Dan) Allah telah berfirman, (Sesungguhnya Kami telah menciptakan manusia) yakni Adam (dari suatu sari pati) lafal Sulaalatin berasal dari perkataan Salaltusy Syai-a Minasy Syai-i, artinya aku telah memeras sesuatu daripadanya, yang dimaksud adalah inti sari dari sesuatu itu (berasal dari tanah) lafal Min Thiinin berta'alluq kepada lafal Sulaalatin.",[["وَلَقَدْ","And indeed"],["خَلَقْنَا","We created"],["ٱلْإِنسَـٰنَ","the humankind"],["مِن","from"],["سُلَـٰلَةٍۢ","an essence"],["مِّن","of"],["طِينٍۢ","clay"]]],"2686":["(Kemudian Kami jadikan ia) manusia atau keturunan Adam (dari nuthfah) yakni air mani (yang berada dalam tempat yang kokoh) yaitu rahim.",[["ثُمَّ","Then"],["جَعَلْنَـٰهُ","We placed him"],["نُطْفَةًۭ","(as) a semen-drop"],["فِى","in"],["قَرَارٍۢ","a resting place"],["مَّكِينٍۢ","firm"]]],"2687":["(Kemudian air mani itu Kami jadikan segumpal darah) darah kental (lalu segumpal darah itu Kami jadikan segumpal daging) daging yang besarnya sekepal tangan (dan segumpal daging itu Kami jadikan tulang-belulang, lalu tulang-belulang itu Kami bungkus dengan daging) menurut qiraat yang lain lafal 'Izhaaman dalam dua tempat tadi dibaca 'Azhman, yakni dalam bentuk tunggal. Dan lafal Khalaqnaa yang artinya menciptakan, pada tiga tempat tadi bermakna Shayyarnaa, artinya Kami jadikan (kemudian Kami jadikan dia sebagai makhluk yang lain) yaitu dengan ditiupkan roh ke dalam tubuhnya. (Maka Maha Sucilah Allah, Pencipta Yang Paling Baik) sebaik-baik Yang Menciptakan. Sedangkan Mumayyiz dari lafal Ahsan tidak disebutkan, karena sudah dapat diketahui dengan sendirinya, yaitu lafal Khalqan.",[["ثُمَّ","Then"],["خَلَقْنَا","We created"],["ٱلنُّطْفَةَ","the semen-drop"],["عَلَقَةًۭ","(into) a clinging substance"],["فَخَلَقْنَا","then We created"],["ٱلْعَلَقَةَ","the clinging substance"],["مُضْغَةًۭ","(into) an embryonic lump"],["فَخَلَقْنَا","then We created"],["ٱلْمُضْغَةَ","the embryonic lump"],["عِظَـٰمًۭا","(into) bones"],["فَكَسَوْنَا","then We clothed"],["ٱلْعِظَـٰمَ","the bones"],["لَحْمًۭا","(with) flesh"],["ثُمَّ","then"],["أَنشَأْنَـٰهُ","We produce it"],["خَلْقًا","(as) a creation"],["ءَاخَرَ ۚ","another"],["فَتَبَارَكَ","So blessed is"],["ٱللَّهُ","Allah"],["أَحْسَنُ","(the) Best"],["ٱلْخَـٰلِقِينَ","(of) the Creators"]]],"2688":["(Kemudian, sesudah itu sesungguhnya kamu sekalian benar-benar akan mati).",[["ثُمَّ","Then"],["إِنَّكُم","indeed, you"],["بَعْدَ","after"],["ذَٰلِكَ","that"],["لَمَيِّتُونَ","surely (will) die"]]],"2689":["(Kemudian, sesungguhnya kamu sekalian akan dibangkitkan di hari kiamat) untuk menjalani hisab dan pembalasan.",[["ثُمَّ","Then"],["إِنَّكُمْ","indeed, you"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["تُبْعَثُونَ","will be resurrected"]]],"2690":["(Dan sesungguhnya Kami telah menciptakan di atas kalian tujuh buah jalan) yakni tujuh langit; lafal Tharaaiq ini adalah bentuk jamak dari lafal Thariiqah, dikatakan demikian karena ia adalah jalan-jalan bagi para Malaikat (dan tidaklah Kami terhadap makhluk) yang berada di bawah tujuh langit itu (melupakannya) dengan membiarkan langit itu runtuh menimpa mereka, sehingga mereka binasa semuanya, akan tetapi Kami menahannya supaya jangan runtuh; sebagaimana yang telah disebutkan dalam firman-Nya yang lain, yaitu, \"Dan Dia menahan (benda-benda) langit jatuh ke bumi.\" (Q.S. Al-Hajj, 65).",[["وَلَقَدْ","And indeed"],["خَلَقْنَا","We (have) created"],["فَوْقَكُمْ","above you"],["سَبْعَ","seven"],["طَرَآئِقَ","paths"],["وَمَا","and not"],["كُنَّا","We are"],["عَنِ","of"],["ٱلْخَلْقِ","the creation"],["غَـٰفِلِينَ","unaware"]]],"2691":["(Dan Kami turunkan air dari langit menurut suatu ukuran) berdasarkan kecukupan mereka (lalu Kami jadikan air itu menetap di bumi, dan sesungguhnya Kami benar-benar berkuasa menghilangkannya) jika demikian mereka pasti akan mati bersama dengan hewan ternak mereka karena kehausan.",[["وَأَنزَلْنَا","And We send down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۢ","water"],["بِقَدَرٍۢ","in (due) measure"],["فَأَسْكَنَّـٰهُ","then We cause it to settle"],["فِى","in"],["ٱلْأَرْضِ ۖ","the earth"],["وَإِنَّا","And indeed, We"],["عَلَىٰ","on"],["ذَهَابٍۭ","taking it away"],["بِهِۦ","taking it away"],["لَقَـٰدِرُونَ","surely (are) Able"]]],"2692":["(Lalu dengan air itu, Kami tumbuhkan untuk kalian kebun-kebun kurma dan anggur) kedua jenis buah-buahan ini kebanyakan terdapat di negeri Arab (di dalam kebun-kebun itu kalian peroleh buah-buahan yang banyak dan sebagian dari buah-buahan itu kalian makan) di waktu musim panas dan musim dingin.",[["فَأَنشَأْنَا","Then We produced"],["لَكُم","for you"],["بِهِۦ","by it"],["جَنَّـٰتٍۢ","gardens"],["مِّن","of date-palms"],["نَّخِيلٍۢ","of date-palms"],["وَأَعْنَـٰبٍۢ","and grapevines"],["لَّكُمْ","for you"],["فِيهَا","in it"],["فَوَٰكِهُ","(are) fruits"],["كَثِيرَةٌۭ","abundant"],["وَمِنْهَا","and from them"],["تَأْكُلُونَ","you eat"]]],"2693":["(Dan) Kami tumbuhkan pula (pohon kayu yang asal tumbuhnya dari Thursina) dapat dibaca Sina dan Saina dengan tidak menerima Tanwin karena menjadi 'Alamiyah, artinya nama sebuah bukit. Jika tidak menerima tanwin karena Illat Ta'nits, maka berarti nama suatu lembah (yang menghasilkan) dapat dibaca Tunbitu dan Tanbutu (minyak) bila menurut bacaan Tunbitu maka huruf Ba dianggap huruf Zaidah, bila menurut bacaan yang kedua yaitu Tanbutu maka huruf Ba dianggap sebagai huruf Ta'diyah yang menggandengkan Fi'il dengan Maf'ul; pohon yang dimaksud adalah pohon Zaitun (dan sebagai penyedap bagi orang-orang yang makan) lafal ini di'athafkan kepada lafal Bid Duhni, sehingga dibaca Wa Shibghin Lil Aakiliina. Artinya, sebagai penyedap suapan yang dicelupkan kepadanya kemudian dimakan, yang dimaksud adalah minyak Zaitun tersebut.",[["وَشَجَرَةًۭ","And a tree"],["تَخْرُجُ","(that) springs forth"],["مِن","from"],["طُورِ","Mount Sinai"],["سَيْنَآءَ","Mount Sinai"],["تَنۢبُتُ","(which) produces"],["بِٱلدُّهْنِ","oil"],["وَصِبْغٍۢ","and a relish"],["لِّلْـَٔاكِلِينَ","for those who eat"]]],"2694":["(Dan sesungguhnya pada binatang-binatang ternak bagi kalian) yakni unta, sapi dan kambing (benar-benar terdapat pelajaran yang penting) bahan pelajaran yang kalian dapat mengambil manfaat besar daripadanya (Kami memberi minum kalian) dapat dibaca Nasqiikum dan Nusqiikum (dari apa yang ada di dalam perutnya) yakni air susu (dan juga pada hewan ternak itu terdapat faedah yang banyak bagi kalian) dari bulu domba, unta dan kambing serta manfaat-manfaat yang lainnya (dan sebagian daripadanya kalian makan).",[["وَإِنَّ","And indeed"],["لَكُمْ","for you"],["فِى","in"],["ٱلْأَنْعَـٰمِ","the cattle"],["لَعِبْرَةًۭ ۖ","surely, (is) a lesson"],["نُّسْقِيكُم","We give you drink"],["مِّمَّا","from what"],["فِى","(is) in"],["بُطُونِهَا","their bellies"],["وَلَكُمْ","and for you"],["فِيهَا","in them"],["مَنَـٰفِعُ","(are) benefits"],["كَثِيرَةٌۭ","many"],["وَمِنْهَا","and of them"],["تَأْكُلُونَ","you eat"]]],"2695":["(Dan di atas punggung-punggung ternak itu) khususnya unta (dan juga di atas bahtera) yaitu perahu-perahu dan kapal-kapal (kalian diangkut).",[["وَعَلَيْهَا","And on them"],["وَعَلَى","and on"],["ٱلْفُلْكِ","[the] ships"],["تُحْمَلُونَ","you are carried"]]],"2696":["(Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, lalu ia berkata, \"Hai kaumku! Sembahlah oleh kamu sekalian Allah) taatilah dan esakanlah Allah (karena sekali-kali tidak ada Tuhan bagi kalian selain Dia) lafal Ghairuhu merupakan Isim dari Maa, sedangkan lafal sebelumnya menjadi Khabar dari Maa dan huruf Min adalah huruf Zaidah. (Maka mengapa kalian tidak bertakwa kepada-Nya?\") tidak takut kepada azab-Nya, mengapa kalian menyembah selain-Nya?",[["وَلَقَدْ","And verily"],["أَرْسَلْنَا","We sent"],["نُوحًا","Nuh"],["إِلَىٰ","to"],["قَوْمِهِۦ","his people"],["فَقَالَ","and he said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","(is) any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥٓ ۖ","other than Him"],["أَفَلَا","Then will not"],["تَتَّقُونَ","you fear"]]],"2697":["(Maka pemuka-pemuka orang yang kafir di antara kaumnya berkata) kepada para pengikut mereka, (\"Orang ini tidak lain hanyalah manusia seperti kalian, yang bermaksud hendak menjadi seorang yang lebih tinggi) lebih mulia dan berpengaruh (dari kalian) maksudnya ia ingin menjadi orang yang banyak pengikutnya, dan para pengikutnya adalah kalian sendiri. (Dan kalau Allah menghendaki) supaya tidak disembah selain daripada-Nya (tentu Dia mengutus beberapa Malaikat) untuk menyampaikan hal tersebut, tidak mengutus manusia. (Belum pernah kami mendengar seruan yang seperti ini) yang diserukan oleh Nabi Nuh, maksudnya ajaran tauhid (pada masa nenek moyang kami yang dahulu) yakni umat-umat terdahulu.",[["فَقَالَ","But said"],["ٱلْمَلَؤُا۟","the chiefs"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["مِن","among"],["قَوْمِهِۦ","his people"],["مَا","This is not"],["هَـٰذَآ","This is not"],["إِلَّا","but"],["بَشَرٌۭ","a man"],["مِّثْلُكُمْ","like you"],["يُرِيدُ","he wishes"],["أَن","to"],["يَتَفَضَّلَ","assert (his) superiority"],["عَلَيْكُمْ","over you"],["وَلَوْ","and if"],["شَآءَ","Allah had willed"],["ٱللَّهُ","Allah had willed"],["لَأَنزَلَ","surely He (would have) sent down"],["مَلَـٰٓئِكَةًۭ","Angels"],["مَّا","Not"],["سَمِعْنَا","we heard"],["بِهَـٰذَا","of this"],["فِىٓ","from"],["ءَابَآئِنَا","our forefathers"],["ٱلْأَوَّلِينَ","our forefathers"]]],"2698":["(Ia tiada lain) maksudnya Nuh ini tidak lain (hanyalah seorang laki-laki yang berpenyakit gila) dalam keadaan gila (maka tunggulah terhadapnya) tunggulah dia, atau biarkanlah dia (sampai suatu waktu\") hingga saat kematiannya. Maksud mereka biarkanlah dia begitu, nanti juga mati sendiri.",[["إِنْ","Not"],["هُوَ","he"],["إِلَّا","(is) but"],["رَجُلٌۢ","a man"],["بِهِۦ","in him"],["جِنَّةٌۭ","(is) madness"],["فَتَرَبَّصُوا۟","so wait"],["بِهِۦ","concerning him"],["حَتَّىٰ","until"],["حِينٍۢ","a time"]]],"2699":["(Berdoalah) Nabi Nuh, (\"Ya Rabbku! Tolonglah aku) atas mereka (karena mereka mendustakan aku\") yakni mereka tidak mau percaya lagi kepadaku, maka binasakanlah mereka. Maka Allah berfirman memperkenankan doanya:",[["قَالَ","He said"],["رَبِّ","My Lord"],["ٱنصُرْنِى","Help me"],["بِمَا","because"],["كَذَّبُونِ","they deny me"]]],"2700":["(Lalu Kami wahyukan kepadanya, \"Buatlah bahtera) yakni perahu (di bawah pengawasan Kami) maksudnya di bawah penilikan dan pengawasan Kami (dan wahyu Kami) yaitu perintah Kami (maka apabila perintah Kami datang) yakni perintah untuk membinasakan mereka (dan tanur telah memancarkan air) dapur pembuat roti telah memancarkan air, sebagai pertanda bagi Nabi Nuh (maka masukkanlah ke dalam bahtera itu) naikkanlah ke dalamnya (dari tiap-tiap jenis) hewan (sepasang) jantan dan betina. Lafal Itsnaini adalah Maf'ul, sedangkan huruf Min berta'alluq kepada lafal Usluk. Menurut suatu kisah disebutkan, bahwa Allah swt. mengumpulkan bagi Nabi Nuh segala macam jenis binatang liar dan burung-burung, serta hewan-hewan lainnya. Kemudian Nabi Nuh memukulkan tangannya kepada tiap-tiap jenis, tangan kanannya mengenai jenis jantan dan tangan kirinya mengenai jenis betina, kemudian ia menaikkan semuanya ke dalam bahtera. Menurut Qiraat yang lain lafal kulli dibaca Kullin; berdasarkan qiraat ini lafal Zaujaini menjadi Maf'ul dan lafal Itsnaini berkedudukan mengukuhkan maknanya (dan juga keluargamu) istri dan anak-anakmu (kecuali orang yang telah lebih dahulu ketetapan azab atasnya di antara mereka) yaitu istri dan anaknya yang bernama Kan`an, lain halnya dengan anak-anaknya yang lain, yaitu Sam, Ham dan Yafits, Nabi Nuh mengangkut mereka bersama dengan istri-istri mereka ke dalam bahtera. Di dalam surah Hud telah disebutkan melalui firman-Nya, 'Dan muatkan pula orang-orang yang beriman. Dan tidak beriman bersama dengan Nuh itu kecuali sedikit.' (Q.S. Hud, 40). Menurut suatu pendapat dikatakan, bahwa jumlah mereka ada enam orang laki-laki berikut istri mereka. Menurut pendapat yang lain dikatakan, bahwa semua orang yang ada di dalam bahtera jumlahnya tujuh puluh delapan orang; separuh laki-laki dan yang separuh lagi perempuan. (Dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim) yaitu orang-orang yang kafir, biarkanlah mereka binasa (karena sesungguhnya mereka akan ditenggelamkan).",[["فَأَوْحَيْنَآ","So We inspired"],["إِلَيْهِ","to him"],["أَنِ","That"],["ٱصْنَعِ","construct"],["ٱلْفُلْكَ","the ship"],["بِأَعْيُنِنَا","under Our eyes"],["وَوَحْيِنَا","and Our inspiration"],["فَإِذَا","then when"],["جَآءَ","comes"],["أَمْرُنَا","Our Command"],["وَفَارَ","and gushes forth"],["ٱلتَّنُّورُ ۙ","the oven"],["فَٱسْلُكْ","then put"],["فِيهَا","into it"],["مِن","of"],["كُلٍّۢ","every (kind)"],["زَوْجَيْنِ","(of) mates"],["ٱثْنَيْنِ","two"],["وَأَهْلَكَ","and your family"],["إِلَّا","except"],["مَن","those"],["سَبَقَ","(has) preceded"],["عَلَيْهِ","against whom"],["ٱلْقَوْلُ","the Word"],["مِنْهُمْ ۖ","thereof"],["وَلَا","And (do) not"],["تُخَـٰطِبْنِى","address Me"],["فِى","concerning"],["ٱلَّذِينَ","those who"],["ظَلَمُوٓا۟ ۖ","wronged"],["إِنَّهُم","indeed, they"],["مُّغْرَقُونَ","(are) the ones to be drowned"]]],"2701":["(Apabila kamu telah lengkap) telah genap (yakni kamu dan orang-orang yang bersamamu berada di atas bahtera itu, maka ucapkanlah, 'Segala puji bagi Allah yang telah menyelamatkan kami dari orang-orang yang zalim') yakni orang-orang yang kafir dengan dibinasakannya mereka.",[["فَإِذَا","And when"],["ٱسْتَوَيْتَ","you (have) boarded"],["أَنتَ","you"],["وَمَن","and whoever"],["مَّعَكَ","(is) with you"],["عَلَى","[on]"],["ٱلْفُلْكِ","the ship"],["فَقُلِ","then say"],["ٱلْحَمْدُ","Praise"],["لِلَّهِ","(be) to Allah"],["ٱلَّذِى","Who"],["نَجَّىٰنَا","(has) saved us"],["مِنَ","from"],["ٱلْقَوْمِ","the people "],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"2702":["(Dan berdoalah) di kala kamu turun dari bahtera, ('Ya Rabbku! Tempatkanlah aku pada tempat) kalau dibaca Munzalan berarti menjadi Mashdar dan Isim Makan/tempat sekaligus, apabila dibaca Manzilan berarti tempat berlabuh (yang diberkati) yakni tempat tersebut diberkati (dan Engkau adalah sebaik-baik yang memberi tempat'\") maksudnya Engkau adalah pemberi tempat yang paling baik kepada semua yang telah disebutkan tadi.",[["وَقُل","And say"],["رَّبِّ","My Lord"],["أَنزِلْنِى","cause me to land"],["مُنزَلًۭا","(at) a landing place"],["مُّبَارَكًۭا","blessed"],["وَأَنتَ","and You"],["خَيْرُ","(are) the Best"],["ٱلْمُنزِلِينَ","(of) those who cause to land.'"]]],"2703":["(Sesungguhnya pada kejadian itu) kisah Nabi Nuh dan bahteranya serta dibinasakan-Nya orang-orang kafir (benar-benar terdapat beberapa tanda) yang menunjukkan kepada kekuasaan Allah swt. (dan sesungguhnya) huruf In di sini adalah bentuk Takhfif daripada Inna, sedangkan isimnya adalah Dhamir Sya'an, bentuk asalnya adalah Innahu yakni sesungguhnya hal itu (Kamilah yang mencoba mereka) menguji kaum Nuh dengan mengutus Nuh kepada mereka supaya Nuh memberi nasihat dan pelajaran kepada mereka.",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) Signs"],["وَإِن","and indeed"],["كُنَّا","We are"],["لَمُبْتَلِينَ","surely testing"]]],"2704":["(Kemudian, Kami jadikan sesudah mereka umat) kaum (yang lain) mereka adalah kaum Ad.",[["ثُمَّ","Then"],["أَنشَأْنَا","We produced"],["مِنۢ","after them"],["بَعْدِهِمْ","after them"],["قَرْنًا","a generation"],["ءَاخَرِينَ","another"]]],"2705":["(Lalu Kami utus kepada mereka, seorang rasul dari kalangan mereka sendiri) yaitu Nabi Hud (\"Hendaklah) ia mengatakan kepada mereka (kalian menyembah Allah, sekali-kali tidak ada Tuhan selain daripada-Nya. Mengapa kalian tidak bertakwa) takut kepada azab-Nya karenanya kalian harus beriman kepada-Nya.",[["فَأَرْسَلْنَا","And We sent"],["فِيهِمْ","among them"],["رَسُولًۭا","a Messenger"],["مِّنْهُمْ","from themselves"],["أَنِ","[that]"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","for you"],["مِّنْ","(is) any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥٓ ۖ","other than Him"],["أَفَلَا","Then will not"],["تَتَّقُونَ","you fear"]]],"2706":["(Dan berkatalah pemuka-pemuka yang kafir di antara kaumnya dan yang mendustakan akan menemui hari akhirat) yakni tempat mereka kembali kelak (dan yang telah Kami mewahkan mereka) Kami berikan nikmat kepada mereka (dalam kehidupan di dunia, 'Orang ini tidak lain hanyalah manusia seperti kalian, dia makan dari apa yang kalian makan dan minum dari apa yang kalian minum').",[["وَقَالَ","And said"],["ٱلْمَلَأُ","the chiefs"],["مِن","of"],["قَوْمِهِ","his people"],["ٱلَّذِينَ","who"],["كَفَرُوا۟","disbelieved"],["وَكَذَّبُوا۟","and denied"],["بِلِقَآءِ","(the) meeting"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["وَأَتْرَفْنَـٰهُمْ","while We had given them luxury"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["مَا","Not"],["هَـٰذَآ","(is) this"],["إِلَّا","but"],["بَشَرٌۭ","a man"],["مِّثْلُكُمْ","like you"],["يَأْكُلُ","He eats"],["مِمَّا","of what"],["تَأْكُلُونَ","you eat"],["مِنْهُ","[from it]"],["وَيَشْرَبُ","and he drinks"],["مِمَّا","of what"],["تَشْرَبُونَ","you drink"]]],"2707":["(Dan) demi Allah (sesungguhnya jika kamu sekalian menaati manusia yang seperti kalian) di dalam ayat ini terkandung makna Qasam atau sumpah dan Syarat, sedangkan Jawab dari Syarat tersebut terkandung pada ayat selanjutnya (niscaya bila demikian, kalian benar-benar) yakni jika kalian menaatinya (menjadi orang-orang yang merugi\") mendapat kerugian.",[["وَلَئِنْ","And surely if"],["أَطَعْتُم","you obey"],["بَشَرًۭا","a man"],["مِّثْلَكُمْ","like you"],["إِنَّكُمْ","indeed, you"],["إِذًۭا","then"],["لَّخَـٰسِرُونَ","surely (will be) losers"]]],"2708":["(\"Apakah ia menjanjikan kepada kalian, bahwa bila kalian telah mati dan telah menjadi tanah dan tulang-belulang, kalian sesungguhnya akan dikeluarkan dari kuburan kalian) lafal Mukhrajuuna merupakan Khabar dari Annakum yang pertama, sedangkan lafal Annakum yang kedua berfungsi mengukuhkan makna Annakum yang pertama tadi, disebutkan lagi karena panjangnya Fashl atau pemisah antara Khabar dan 'Amilnya.",[["أَيَعِدُكُمْ","Does he promise you "],["أَنَّكُمْ","that you"],["إِذَا","when"],["مِتُّمْ","you are dead"],["وَكُنتُمْ","and you become"],["تُرَابًۭا","dust"],["وَعِظَـٰمًا","and bones"],["أَنَّكُم","that you"],["مُّخْرَجُونَ","(will be) brought forth"]]],"2709":["(Jauh, jauh sekali) lafal Haihaata Haihaata adalah Isim Fi'il Madhi yang bermakna Mashdar, artinya jauh, jauh sekali dari kebenaran (apa yang diancamkan kepada kalian itu) yaitu dihidupkannya kembali kalian dari kuburan. Huruf Lam pada lafal Limaa Tuu'aduna adalah Lam Zaidah yang mengandung makna Bayan atau penjelasan.",[["۞ هَيْهَاتَ","Far-(fetched)"],["هَيْهَاتَ","far-(fetched)"],["لِمَا","is what"],["تُوعَدُونَ","you are promised"]]],"2710":["(Tiada lain hal itu) yakni kehidupan yang sesungguhnya (hanyalah kehidupan kita di dunia ini, kita mati kemudian kita hidup) yaitu dengan hidupnya anak-anak kita (dan sekali-kali kita tidak akan dibangkitkan kembali).",[["إِنْ","Not"],["هِىَ","it"],["إِلَّا","(is) but"],["حَيَاتُنَا","our life"],["ٱلدُّنْيَا","(of) the world"],["نَمُوتُ","we die"],["وَنَحْيَا","and we live"],["وَمَا","and not"],["نَحْنُ","we"],["بِمَبْعُوثِينَ","(will be) resurrected"]]],"2711":["(Ia tiada lain) Rasul itu (hanyalah seorang laki-laki yang mengada-adakan kebohongan terhadap Allah, dan kami sekali-kali tidak akan beriman kepadanya\") tidak akan percaya dengan adanya berbangkit sesudah mati.",[["إِنْ","Not"],["هُوَ","(is) he"],["إِلَّا","but"],["رَجُلٌ","a man"],["ٱفْتَرَىٰ","who (has) invented"],["عَلَى","about"],["ٱللَّهِ","Allah"],["كَذِبًۭا","a lie"],["وَمَا","and not"],["نَحْنُ","we"],["لَهُۥ","(in) him"],["بِمُؤْمِنِينَ","(are) believers"]]],"2712":["(Rasul itu berdoa, \"Ya Rabbku! Tolonglah aku karena mereka mendustakanku\").",[["قَالَ","He said"],["رَبِّ","My Lord"],["ٱنصُرْنِى","Help me"],["بِمَا","because"],["كَذَّبُونِ","they deny me"]]],"2713":["(Allah berfirman, \"Dalam sedikit waktu lagi) sebentar lagi. Huruf Ma di sini adalah Zaidah (pasti mereka akan menjadi) akan menjadi orang-orang (yang menyesal\") atas kekafiran dan kedustaan mereka.",[["قَالَ","He said"],["عَمَّا","After a little while"],["قَلِيلٍۢ","After a little while"],["لَّيُصْبِحُنَّ","surely they will become"],["نَـٰدِمِينَ","regretful"]]],"2714":["(Maka dimusnahkanlah mereka oleh suara yang mengguntur) suara yang menandakan turunnya azab dan binasanya makhluk (dengan hak) maka matilah mereka (dan Kami jadikan mereka bagaikan tumbuh-tumbuhan yang kering) Kami jadikan mereka seperti tanaman yang kering atau mati (maka alangkah jauhnya) dari rahmat (bagi orang-orang yang zalim itu) yakni orang-orang yang mendustakan Rasul itu.",[["فَأَخَذَتْهُمُ","So seized them"],["ٱلصَّيْحَةُ","the awful cry"],["بِٱلْحَقِّ","in truth"],["فَجَعَلْنَـٰهُمْ","and We made them"],["غُثَآءًۭ ۚ","(as) rubbish of dead leaves"],["فَبُعْدًۭا","So away"],["لِّلْقَوْمِ","with the people "],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"2715":["(Kemudian Kami ciptakan sesudah mereka umat-umat) kaum-kaum (yang lain).",[["ثُمَّ","Then"],["أَنشَأْنَا","We produced"],["مِنۢ","after them"],["بَعْدِهِمْ","after them"],["قُرُونًا","a generation"],["ءَاخَرِينَ","another"]]],"2716":["(Tidak dapat sesuatu umat pun mendahului ajalnya) seumpamanya mereka mati sebelum ajal mereka (dan tidak dapat pula mereka terlambat) dari ajalnya itu. Lafal Yasta'khiruna dalam bentuk jamak dikaitkan kepada lafal Ummatin yang bentuknya muannats, hal ini memandang dari segi maknanya, karena ummatin berarti jamak.",[["مَا","Not"],["تَسْبِقُ","can precede"],["مِنْ","any"],["أُمَّةٍ","nation"],["أَجَلَهَا","its term"],["وَمَا","and not"],["يَسْتَـْٔخِرُونَ","they (can) delay (it)"]]],"2717":["(Kemudian Kami utus rasul-rasul Kami berturut-turut) lafal Tatran dapat pula dibaca Tatraa tanpa memakai harakat Tanwin, artinya berturut-turut yang di antara kedua rasul terdapat pemisah jarak waktu yang cukup lama. (Manakala datang kepada suatu umat) lafal Jaa-a Ummatan dapat dibaca Jaa-a ummatan yakni dengan mentashhilkan huruf Hamzah yang kedua, sehingga ucapannya seolah-olah ada huruf Wau (Rasul, umat itu mendustakannya, maka Kami perikutkan sebagian mereka dengan sebagian yang lain) Kami samakan mereka dengan umat-umat terdahulu dalam hal terbinasa (dan Kami jadikan mereka buah tutur manusia maka kebinasaanlah bagi orang-orang yang tidak beriman).",[["ثُمَّ","Then"],["أَرْسَلْنَا","We sent"],["رُسُلَنَا","Our Messengers"],["تَتْرَا ۖ","(in) succession"],["كُلَّ","Every time"],["مَا","Every time"],["جَآءَ","came"],["أُمَّةًۭ","(to) a nation"],["رَّسُولُهَا","its Messenger"],["كَذَّبُوهُ ۚ","they denied him"],["فَأَتْبَعْنَا","so We made (them) follow "],["بَعْضَهُم","some of them"],["بَعْضًۭا","others"],["وَجَعَلْنَـٰهُمْ","and We made them"],["أَحَادِيثَ ۚ","narrations"],["فَبُعْدًۭا","So away"],["لِّقَوْمٍۢ","with a people "],["لَّا","not"],["يُؤْمِنُونَ","they believe"]]],"2718":["(Kemudian Kami utus Musa dan saudaranya Harun dengan membawa tanda-tanda kebesaran Kami, dan bukti yang nyata) hujah yang nyata, yaitu berupa tangan, tongkat dan mukjizat-mukjizat lainnya.",[["ثُمَّ","Then"],["أَرْسَلْنَا","We sent"],["مُوسَىٰ","Musa"],["وَأَخَاهُ","and his brother"],["هَـٰرُونَ","Harun"],["بِـَٔايَـٰتِنَا","with Our Signs"],["وَسُلْطَـٰنٍۢ","and an authority"],["مُّبِينٍ","clear"]]],"2719":["(Kepada Firaun dan pembesar-pembesar kaumnya, maka mereka ini takabur) sombong tidak mau beriman kepada ayat-ayat dan mukjizat-mukjizat, dan juga mereka tidak mau beriman kepada Allah (dan mereka adalah orang-orang yang sombong) yaitu menindas kaum Bani Israel secara lalim.",[["إِلَىٰ","To"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","and his chiefs"],["فَٱسْتَكْبَرُوا۟","but they behaved arrogantly"],["وَكَانُوا۟","and they were"],["قَوْمًا","a people"],["عَالِينَ","haughty"]]],"2720":["(Dan mereka berkata, \"Apakah pantas kita percaya kepada dua orang manusia seperti kita juga, padahal kaum mereka adalah orang-orang yang menghambakan diri kepada kita?\") yakni kaum Bani Israel; mereka tunduk dan dianggap hina oleh Firaun.",[["فَقَالُوٓا۟","Then they said"],["أَنُؤْمِنُ","Shall we believe"],["لِبَشَرَيْنِ","(in) two men"],["مِثْلِنَا","like ourselves"],["وَقَوْمُهُمَا","while their people"],["لَنَا","for us"],["عَـٰبِدُونَ","(are) slaves"]]],"2721":["(Maka tetaplah mereka mendustakan keduanya, sebab itu mereka adalah termasuk orang-orang yang dibinasakan).",[["فَكَذَّبُوهُمَا","So they denied them"],["فَكَانُوا۟","and they became"],["مِنَ","of"],["ٱلْمُهْلَكِينَ","those who were destroyed"]]],"2722":["(Dan sesungguhnya telah Kami berikan Kitab kepada Musa) kitab Taurat (agar mereka) kaumnya, yaitu bangsa Bani Israel (mendapat petunjuk) dengan adanya kitab Taurat itu dari kesesatan. Aku memberikannya sekali turun sesudah Firaun dan kaumnya binasa",[["وَلَقَدْ","And verily"],["ءَاتَيْنَا","We gave"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","the Scripture"],["لَعَلَّهُمْ","so that they may"],["يَهْتَدُونَ","be guided"]]],"2723":["(Dan telah Kami jadikan putra Maryam) yakni Nabi Isa (beserta ibunya suatu tanda) kekuasaan Kami. Dalam ayat ini tidak disebutkan dua tanda karena keduanya terlibat dalam satu tanda itu, yaitu Maryam dapat melahirkan Nabi Isa tanpa suami (dan Kami menempatkan keduanya di suatu tanah tinggi) yakni tempat di dataran tinggi, yaitu di Baitulmakdis, atau di Damaskus, atau di Palestina; sehubungan dengan hal ini banyak pendapat mengenainya (yang datar) rata tanahnya sehingga para penghuninya menetap dengan nyaman (dan mempunyai banyak sumber air) yang mengalir lagi jernih sebagai suatu kenyataan.",[["وَجَعَلْنَا","And We made"],["ٱبْنَ","(the) son"],["مَرْيَمَ","(of) Maryam"],["وَأُمَّهُۥٓ","and his mother"],["ءَايَةًۭ","a Sign"],["وَءَاوَيْنَـٰهُمَآ","and We sheltered them"],["إِلَىٰ","to"],["رَبْوَةٍۢ","a high ground"],["ذَاتِ","of tranquility"],["قَرَارٍۢ","of tranquility"],["وَمَعِينٍۢ","and water springs"]]],"2724":["(Hai Rasul-rasul! Makanlah dari makanan yang baik-baik) makanan-makanan yang halal (dan kerjakanlah amal yang saleh) amal-amal yang fardu dan sunah. (Sesungguhnya Aku Maha Mengetahui apa yang kalian kerjakan) maka kelak Aku akan memperhitungkannya atas kalian.",[["يَـٰٓأَيُّهَا","O Messengers"],["ٱلرُّسُلُ","O Messengers"],["كُلُوا۟","Eat"],["مِنَ","of"],["ٱلطَّيِّبَـٰتِ","the good things"],["وَٱعْمَلُوا۟","and do"],["صَـٰلِحًا ۖ","righteous (deeds)"],["إِنِّى","Indeed, I Am"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["عَلِيمٌۭ","All-Knower"]]],"2725":["(Dan) ketahuilah (bahwasanya ini) yakni agama Islam (adalah agama kalian) hai orang-orang yang diajak bicara, maksudnya kalian harus memeluknya (agama yang satu) lafal Ummatan Waahidatan ini menjadi Hal yang bersifat Lazimah atau tetap. Menurut suatu qiraat yang lain lafal Anna haadzihi dibaca Takhfif sehingga menjadi An Haadzihi, sedangkan menurut qiraat yang lainnya lagi dibaca Inna Haadzihi, dan dianggap sebagai jumlah Isti'naf atau kalimat baru, sehingga artinya menjadi, sesungguhnya agama Islam ini (dan Aku adalah Rabb kalian, maka bertakwalah kalian kepada-Ku) artinya takutlah kalian kepada-Ku.",[["وَإِنَّ","And indeed"],["هَـٰذِهِۦٓ","this"],["أُمَّتُكُمْ","your religion"],["أُمَّةًۭ","(is) religion"],["وَٰحِدَةًۭ","one"],["وَأَنَا۠","And I Am"],["رَبُّكُمْ","your Lord"],["فَٱتَّقُونِ","so fear Me"]]],"2726":["(Kemudian mereka memecah belah) para pengikut Rasul itu (perkara mereka) yakni agama mereka (menjadi beberapa pecahan di antara mereka) lafal Zuburan ini menjadi Hal dari Fa'ilnya lafal Taqaththa'uu, artinya, menjadi sekte-sekte yang bertentangan, seperti yang terjadi di kalangan orang-orang Yahudi dan orang-orang Nasrani serta lain-lainnya. (Tiap-tiap golongan terhadap apa yang ada pada sisi mereka) agama yang mereka pegang (merasa bangga) merasa puas dan gembira.",[["فَتَقَطَّعُوٓا۟","But they cut off"],["أَمْرَهُم","their affair (of unity)"],["بَيْنَهُمْ","between them"],["زُبُرًۭا ۖ","(into) sects"],["كُلُّ","each"],["حِزْبٍۭ","faction"],["بِمَا","in what"],["لَدَيْهِمْ","they have"],["فَرِحُونَ","rejoicing"]]],"2727":["(Maka biarkanlah mereka) biarkanlah orang-orang kafir Mekah itu (dalam kesesatannya) (sampai suatu waktu) hingga saat kematian mereka.",[["فَذَرْهُمْ","So leave them"],["فِى","in"],["غَمْرَتِهِمْ","their confusion"],["حَتَّىٰ","until"],["حِينٍ","a time"]]],"2728":["(Apakah mereka mengira bahwa sesungguhnya apa-apa yang Kami berikan kepada mereka) artinya, Kami limpahkan kepada mereka (berupa harta benda dan anak-anak) di dunia ini.",[["أَيَحْسَبُونَ","Do they think"],["أَنَّمَا","that what"],["نُمِدُّهُم","We extend to them"],["بِهِۦ","[with it]"],["مِن","of"],["مَّالٍۢ","wealth"],["وَبَنِينَ","and children"]]],"2729":["(Kami bersegera) menyegerakan (memberikan kebaikan-kebaikan kepada mereka) tidak, sesungguhnya tidak demikian (sebenarnya mereka tidak sadar) bahwasanya hal itu adalah pengluluh atau Istidraj buat mereka.",[["نُسَارِعُ","We hasten"],["لَهُمْ","to them"],["فِى","in"],["ٱلْخَيْرَٰتِ ۚ","the good"],["بَل","Nay"],["لَّا","not"],["يَشْعُرُونَ","they perceive"]]],"2730":["(Sesungguhnya orang-orang yang karena perasaan khasyyah mereka kepada Rabb mereka) disebabkan mereka takut kepada-Nya (mereka merasa takut sekali) kepada azab-Nya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["هُم","[they]"],["مِّنْ","from"],["خَشْيَةِ","(the) fear"],["رَبِّهِم","(of) their Lord"],["مُّشْفِقُونَ","(are) cautious"]]],"2731":["(Dan orang-orang yang terhadap ayat-ayat Rabb mereka) Alquran (mereka beriman) sangat percaya kepadanya.",[["وَٱلَّذِينَ","And those"],["هُم","[they]"],["بِـَٔايَـٰتِ","in (the) Signs"],["رَبِّهِمْ","(of) their Lord"],["يُؤْمِنُونَ","believe"]]],"2732":["(Dan orang-orang yang tidak mempersekutukan dengan Rabb mereka) sesuatu apa pun.",[["وَٱلَّذِينَ","And those"],["هُم","[they]"],["بِرَبِّهِمْ","with their Lord"],["لَا","(do) not"],["يُشْرِكُونَ","associate partners"]]],"2733":["(Dan orang-orang yang memberikan) yang menginfakkan (apa yang telah mereka berikan) mereka infakkan berupa zakat dan amal-amal saleh (dengan hati yang takut) takut amalnya tidak diterima (karena mereka tahu bahwa sesungguhnya mereka) sebelum lafal Annahum ini diperkirakan adanya huruf Lam yang menjarkannya (akan dikembalikan kepada Rabb mereka).",[["وَٱلَّذِينَ","And those who"],["يُؤْتُونَ","give"],["مَآ","what"],["ءَاتَوا۟","they give"],["وَّقُلُوبُهُمْ","while their hearts"],["وَجِلَةٌ","(are) fearful"],["أَنَّهُمْ","because they"],["إِلَىٰ","to"],["رَبِّهِمْ","their Lord"],["رَٰجِعُونَ","(will) return"]]],"2734":["(Mereka itu bersegera untuk mendapatkan kebaikan-kebaikan, dan merekalah orang-orang yang segera memperolehnya) menurut ilmu Allah.",[["أُو۟لَـٰٓئِكَ","(It is) those"],["يُسَـٰرِعُونَ","who hasten"],["فِى","in"],["ٱلْخَيْرَٰتِ","the good (deeds)"],["وَهُمْ","and they"],["لَهَا","in them"],["سَـٰبِقُونَ","(are) foremost"]]],"2735":["(Kami tiada membebani seseorang melainkan menurut kesanggupannya) yang sesuai dengan kemampuannya, oleh karenanya barang siapa tidak mampu melakukan salat sambil berdiri, maka ia boleh melakukannya sambil duduk, dan barang siapa tidak mampu melakukan puasa maka ia boleh berbuka (dan pada sisi Kami) di sisi Kami (ada suatu kitab yang membicarakan dengan benar) apa yang telah dilakukan oleh seseorang, yaitu Lohmahfuz; padanya ditulis semua amal-amal perbuatan (dan mereka) kita semua orang yang beramal (tidak dianiaya) barang sedikit pun dari amal-amalnya, oleh karenanya sedikit pun tidak dikurangi pahala amal kebaikannya, dan tidak pula ditambah dosa-dosanya.",[["وَلَا","And not"],["نُكَلِّفُ","We burden"],["نَفْسًا","any soul"],["إِلَّا","except"],["وُسْعَهَا ۖ","(to) its capacity"],["وَلَدَيْنَا","and with Us"],["كِتَـٰبٌۭ","(is) a Record"],["يَنطِقُ","(which) speaks"],["بِٱلْحَقِّ ۚ","with the truth"],["وَهُمْ","and they"],["لَا","(will) not"],["يُظْلَمُونَ","be wronged"]]],"2736":["(Tetapi hati mereka) yakni orang-orang kafir itu (dalam kealpaan) artinya, kebodohan (mengenai hal ini) yaitu Alquran (dan mereka banyak mengerjakan perbuatan-perbuatan selain daripada itu) selain amal-amal kebaikan yang dilakukan oleh orang-orang yang beriman (mereka tetap mengerjakannya) oleh sebab itu mereka diazab.",[["بَلْ","Nay"],["قُلُوبُهُمْ","their hearts"],["فِى","(are) in"],["غَمْرَةٍۢ","confusion"],["مِّنْ","over"],["هَـٰذَا","this"],["وَلَهُمْ","and for them"],["أَعْمَـٰلٌۭ","(are) deeds"],["مِّن","besides"],["دُونِ","besides"],["ذَٰلِكَ","that"],["هُمْ","they"],["لَهَا","for it"],["عَـٰمِلُونَ","(are) doers"]]],"2737":["(Hingga) menunjukkan makna Ibtida (apabila Kami timpakan kepada orang-orang yang hidup mewah di antara mereka) yakni orang-orang kaya dan pemimpin-pemimpin mereka (azab) dengan pedang dalam perang Badar (dengan serta merta mereka memekik minta tolong) mereka ribut meminta tolong. Kemudian dikatakan kepada mereka,",[["حَتَّىٰٓ","Until"],["إِذَآ","when"],["أَخَذْنَا","We seize"],["مُتْرَفِيهِم","their affluent ones"],["بِٱلْعَذَابِ","with the punishment"],["إِذَا","behold"],["هُمْ","They"],["يَجْـَٔرُونَ","cry for help"]]],"2738":["(\"Janganlah kalian memekik, minta tolong pada hari ini. Sesungguhnya kalian tidak akan mendapat pertolongan dari Kami) maksudnya tidak ada seorang pun yang dapat menolong kalian.",[["لَا","(Do) not"],["تَجْـَٔرُوا۟","cry for help"],["ٱلْيَوْمَ ۖ","today"],["إِنَّكُم","Indeed, you"],["مِّنَّا","from Us"],["لَا","not"],["تُنصَرُونَ","will be helped"]]],"2739":["(Sesungguhnya ayat-ayat-Ku) dari Alquran (selalu dibacakan kepada kalian, tetapi kalian selalu berpaling ke belakang) mundur ke belakang maksudnya kalian tidak mau menerimanya.",[["قَدْ","Verily"],["كَانَتْ","were"],["ءَايَـٰتِى","My Verses"],["تُتْلَىٰ","recited"],["عَلَيْكُمْ","to you"],["فَكُنتُمْ","but you used"],["عَلَىٰٓ","(to) on"],["أَعْقَـٰبِكُمْ","your heels"],["تَنكِصُونَ","turn back"]]],"2740":["(Dengan menyombongkan diri) tidak mau beriman (akan keakuan kalian) yakni membanggakan Kakbah atau tanah suci yang kalian tempati, maksudnya kalian beranggapan bahwa diri kalian adalah penduduknya, oleh karena itu kalian merasa dalam keadaan aman dari azab Allah, berbeda dengan kaum-kaum yang lain di tempat tinggal mereka selain dari tanah suci (dan seraya bergadang) lafal Samiran menjadi Hal, artinya mereka berkumpul membentuk suatu kelompok sambil berbincang-bincang di waktu malam hari; hal ini mereka lakukan di sekeliling Kakbah (kalian mengucapkan perkataan-perkataan yang keji terhadapnya\") lafal Tahjuruuna ini jika berasal dari Fi'il Tsulatsi artinya tidak menganggap Alquran. Jika berasal dari Fi'il Ruba'i berarti mereka membuat-buat perkataan yang keji tanpa hak terhadap diri Nabi saw. dan Alquran. Selanjutnya Allah swt. berfirman,",[["مُسْتَكْبِرِينَ","(Being) arrogant"],["بِهِۦ","about it"],["سَـٰمِرًۭا","conversing by night"],["تَهْجُرُونَ","speaking evil"]]],"2741":["(Maka apakah mereka tidak memperhatikan) asal lafal Yaddabbaruu adalah Yatadabbaruuna, kemudian huruf Ta dimasukkan ke dalam huruf Dal setelah terlebih dahulu diganti menjadi Dal, sehingga jadilah Yaddabbaruuna (perkataan ini) Alquran ini yang menunjukkan kebenaran Nabi saw. (atau apakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka dahulu?)",[["أَفَلَمْ","Then, do not"],["يَدَّبَّرُوا۟","they ponder"],["ٱلْقَوْلَ","the Word"],["أَمْ","or"],["جَآءَهُم","has come to them"],["مَّا","what"],["لَمْ","not"],["يَأْتِ","(had) come"],["ءَابَآءَهُمُ","(to) their forefathers"],["ٱلْأَوَّلِينَ","(to) their forefathers"]]],"2742":["(Ataukah mereka tidak mengenal Rasul mereka, karena itu mereka memungkirinya?)",[["أَمْ","Or"],["لَمْ","(do) not"],["يَعْرِفُوا۟","they recognize"],["رَسُولَهُمْ","their Messenger"],["فَهُمْ","so they"],["لَهُۥ","(are) rejecting him"],["مُنكِرُونَ","(are) rejecting him"]]],"2743":["(Atau apakah patut mereka berkata, \"Padanya ada penyakit gila\") Istifham atau kata tanya di sini mengandung arti Taqrir atau menetapkan perkara yang hak, yaitu membenarkan Nabi dan membenarkan bahwa Rasul-rasul telah datang kepada umat-umat terdahulu, serta mereka mengetahui bahwa Rasul mereka adalah orang yang jujur dan dapat dipercaya, dan bahwasanya Rasul mereka itu tidak gila. (Sebenarnya) lafal Bal menunjukkan makna Intiqal (dia telah membawa kebenaran kepada mereka) yakni Alquran yang di dalamnya terkandung ajaran Tauhid dan hukum-hukum Islam (dan kebanyakan mereka benci kepada kebenaran itu).",[["أَمْ","Or"],["يَقُولُونَ","they say"],["بِهِۦ","In him"],["جِنَّةٌۢ ۚ","(is) madness"],["بَلْ","Nay"],["جَآءَهُم","he brought them"],["بِٱلْحَقِّ","the truth"],["وَأَكْثَرُهُمْ","but most of them"],["لِلْحَقِّ","to the truth"],["كَـٰرِهُونَ","(are) averse"]]],"2744":["(Andaikata kebenaran itu menuruti) artinya Alquran itu menuruti (hawa nafsu mereka) seumpamanya Alquran itu datang dengan membawa hal-hal yang mereka sukai, seperti menisbatkan sekutu dan anak kepada Allah, padahal Allah Maha Suci dari hal tersebut (pasti binasalah langit dan bumi dan semua yang ada di dalamnya) yakni menyimpang dari tatanan yang sebenarnya dan tidak seperti apa yang disaksikan sekarang, hal itu disebabkan adanya dua pengaruh kekuasaan yang saling tarik-menarik. (Sebenarnya Kami telah mendatangkan kepada mereka kebanggaan mereka) yaitu Alquran yang di dalamnya terkandung sebutan dan kemuliaan mereka (tetapi mereka berpaling dari kebanggaan itu).",[["وَلَوِ","But if"],["ٱتَّبَعَ","(had) followed"],["ٱلْحَقُّ","the truth"],["أَهْوَآءَهُمْ","their desires"],["لَفَسَدَتِ","surely (would) have been corrupted"],["ٱلسَّمَـٰوَٰتُ","the heavens"],["وَٱلْأَرْضُ","and the earth"],["وَمَن","and whoever"],["فِيهِنَّ ۚ","(is) therein"],["بَلْ","Nay"],["أَتَيْنَـٰهُم","We have brought them"],["بِذِكْرِهِمْ","their reminder"],["فَهُمْ","but they"],["عَن","from"],["ذِكْرِهِم","their reminder"],["مُّعْرِضُونَ","(are) turning away"]]],"2745":["(Atau kamu meminta upah kepada mereka) sebagai imbalan dari apa yang kamu datangkan buat mereka yaitu masalah keimanan (maka upah Rabbmu) adalah pahala, upah dan rezeki-Nya (adalah lebih baik) dan menurut qiraat yang lain dibaca Kharjan dalam dua tempat tadi; tetapi menurut qiraat yang lainnya lagi dibaca Kharaajan pada keduanya (dan Dia adalah Pemberi rezeki Yang Paling Baik) Pengupah Yang Paling Utama.",[["أَمْ","Or"],["تَسْـَٔلُهُمْ","you ask them"],["خَرْجًۭا","(for) a payment"],["فَخَرَاجُ","But the payment"],["رَبِّكَ","(of) your Lord"],["خَيْرٌۭ ۖ","(is) best"],["وَهُوَ","and He"],["خَيْرُ","(is) the Best"],["ٱلرَّٰزِقِينَ","(of) the Providers"]]],"2746":["(Dan sesungguhnya kamu benar-benar menyeru mereka kepada jalan) tuntunan (yang lurus) yaitu agama Islam.",[["وَإِنَّكَ","And indeed, you"],["لَتَدْعُوهُمْ","certainly call them"],["إِلَىٰ","to"],["صِرَٰطٍۢ","(the) Path"],["مُّسْتَقِيمٍۢ","Straight"]]],"2747":["(Dan sesungguhnya orang-orang yang tidak beriman kepada adanya hari akhirat) adanya hari berbangkit dan pembalasan pahala serta azab (dari jalan yang lurus) dari tuntunan yang lurus (mereka benar-benar menyimpang) yakni membelok.",[["وَإِنَّ","And indeed"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["عَنِ","from"],["ٱلصِّرَٰطِ","the path"],["لَنَـٰكِبُونَ","surely (are) deviating"]]],"2748":["(Andaikata mereka Kami belas kasihani, dan Kami lenyapkan kemudaratan yang mereka alami) yakni kelaparan yang menimpa mereka di Mekah selama tujuh tahun itu (benar-benar mereka akan terus-menerus) masih tetap dan berkepanjangan (dalam keterlaluan mereka) dalam kesesatan mereka (mereka bergelimang) terombang-ambing.",[["۞ وَلَوْ","And if"],["رَحِمْنَـٰهُمْ","We had mercy on them"],["وَكَشَفْنَا","and We removed"],["مَا","what"],["بِهِم","(was) on them"],["مِّن","of"],["ضُرٍّۢ","(the) hardship"],["لَّلَجُّوا۟","surely they would persist"],["فِى","in"],["طُغْيَـٰنِهِمْ","their transgression"],["يَعْمَهُونَ","wandering blindly"]]],"2749":["(Dan sesungguhnya Kami telah pernah menimpakan azab kepada mereka) kelaparan itu (tetapi mereka masih tidak tunduk) masih tidak mau merendahkan diri (kepada Rabb mereka, dan juga mereka tidak mau ber-tadharru' kepada-Nya) maksudnya mereka tidak mau juga meminta kepada Allah dengan berdoa kepada-Nya.",[["وَلَقَدْ","And verily"],["أَخَذْنَـٰهُم","We seized them"],["بِٱلْعَذَابِ","with the punishment"],["فَمَا","but not"],["ٱسْتَكَانُوا۟","they submit"],["لِرَبِّهِمْ","to their Lord"],["وَمَا","and not"],["يَتَضَرَّعُونَ","they supplicate humbly"]]],"2750":["(Hingga) lafal Hattaa menunjukkan makna Ibtida atau permulaan (apabila Kami bukakan untuk mereka suatu pintu yang di dalamnya ada) terdapat (azab yang keras) yaitu perang Badar tempat mereka terbunuh (tiba-tiba mereka menjadi berputus asa) putus harapan dari semua kebaikan.",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["فَتَحْنَا","We opened"],["عَلَيْهِم","for them"],["بَابًۭا","a gate"],["ذَا","of a punishment"],["عَذَابٍۢ","of a punishment"],["شَدِيدٍ","severe"],["إِذَا","behold"],["هُمْ","They"],["فِيهِ","in it"],["مُبْلِسُونَ","(will be in) despair"]]],"2751":["(Dan Dialah Yang menciptakan) yang menjadikan (bagi kamu sekalian pendengaran) lafal As Sam'u maknanya Al Asmaa', dalam bentuk jamak (penglihatan dan kalbu) hati. (Amat sedikitlah) lafal Maa mengukuhkan makna yang terkandung dalam lafal Qaliilan (kalian bersyukur).",[["وَهُوَ","And He"],["ٱلَّذِىٓ","(is) the One Who"],["أَنشَأَ","produced"],["لَكُمُ","for you"],["ٱلسَّمْعَ","the hearing"],["وَٱلْأَبْصَـٰرَ","and the sight"],["وَٱلْأَفْـِٔدَةَ ۚ","and the feeling"],["قَلِيلًۭا","little"],["مَّا","(is) what"],["تَشْكُرُونَ","you give thanks"]]],"2752":["(Dan Dialah yang mengembangbiakkan kalian) menciptakan kalian (di bumi ini, dan hanya kepada-Nyalah kalian akan dihimpunkan) akan dibangkitkan menjadi hidup kembali kemudian menghadap kepada-Nya.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["ذَرَأَكُمْ","multiplied you"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَإِلَيْهِ","and to Him"],["تُحْشَرُونَ","you will be gathered"]]],"2753":["(Dan Dialah yang menghidupkan) dengan meniupkan roh ke dalam Mudhghah atau janin (dan mematikan, dan Dialah yang mengatur pertukaran malam dan siang) malam gelap, dan siang menjadi terang, serta menambah panjang dan mengurangi waktu salah satu di antara keduanya. (Maka apakah kalian tidak memahaminya?) maksudnya memahami ciptaan Allah swt., kemudian kalian mengambil pelajaran daripadanya.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["يُحْىِۦ","gives life"],["وَيُمِيتُ","and causes death"],["وَلَهُ","and for Him"],["ٱخْتِلَـٰفُ","(is the) alternation"],["ٱلَّيْلِ","(of) the night"],["وَٱلنَّهَارِ ۚ","and the day"],["أَفَلَا","Then will not"],["تَعْقِلُونَ","you reason"]]],"2754":["(Sebenarnya mereka mengucapkan perkataan yang serupa dengan perkataan yang diucapkan oleh orang-orang dahulu kala).",[["بَلْ","Nay"],["قَالُوا۟","they say"],["مِثْلَ","(the) like"],["مَا","(of) what"],["قَالَ","said"],["ٱلْأَوَّلُونَ","the former (people)"]]],"2755":["(Mereka berkata) orang-orang dahulu itu, (\"Apakah betul, apabila kami telah mati dan kami telah menjadi tanah dan tulang-belulang, apakah sesungguhnya kami benar-benar akan dibangkitkan hidup kembali?) memang kalian akan dibangkitkan kembali oleh-Nya. Kedua huruf Hamzah pada dua tempat ini dapat dibaca Tahqiq, sehingga bacaannya menjadi A-innaa. Sebagaimana huruf Hamzah yang keduanya dapat pula dibaca Tas-hil, sehingga bacaannya menjadi Ayinnaa. Sehubungan dengan bacaan ini ada dua pendapat, yaitu men-tahqiq-kan kedua Hamzahnya dan men-tashil-kan Hamzah yang kedua.",[["قَالُوٓا۟","They said"],["أَءِذَا","What! When"],["مِتْنَا","we are dead"],["وَكُنَّا","and become"],["تُرَابًۭا","dust"],["وَعِظَـٰمًا","and bones"],["أَءِنَّا","would we"],["لَمَبْعُوثُونَ","surely be resurrected"]]],"2756":["(Sesungguhnya kami dan bapak-bapak kami telah diberi ancaman dengan ini) yaitu dengan masalah akan dibangkitkan menjadi hidup kembali sesudah mati (dahulu, tiada lain) tidak lain (ia hanyalah dongengan-dongengan) kebohongan-kebohongan (orang-orang dahulu kala\") wazan lafal Asaathiir sama dengan lafal Al Adhaahiik dan Al-A`aajiib, adalah bentuk jamak dari lafal Usthuurah artinya dongengan atau fiksi.",[["لَقَدْ","Verily"],["وُعِدْنَا","we have been promised"],["نَحْنُ","[we]"],["وَءَابَآؤُنَا","and our forefathers"],["هَـٰذَا","this"],["مِن","before"],["قَبْلُ","before"],["إِنْ","not"],["هَـٰذَآ","(is) this"],["إِلَّآ","but"],["أَسَـٰطِيرُ","(the) tales"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"2757":["(Katakanlah) kepada mereka, (\"Kepunyaan siapakah bumi ini, dan semua yang ada padanya) yakni semua makhluk yang ada padanya (jika kalian mengetahui?\") siapa pencipta dan pemiliknya.",[["قُل","Say"],["لِّمَنِ","To whom (belongs)"],["ٱلْأَرْضُ","the earth"],["وَمَن","and whoever"],["فِيهَآ","(is) in it"],["إِن","if"],["كُنتُمْ","you"],["تَعْلَمُونَ","know"]]],"2758":["(Mereka akan menjawab, \"Kepunyaan Allah.\" Katakanlah) kepada mereka, (\"Maka apakah kalian tidak memikirkannya?\") asal Tadzakkaruuna adalah Tatadzakkaruuna kemudian huruf Ta yang kedua diidgamkan atau dimasukkan ke dalam huruf Dzal setelah terlebih dahulu diganti menjadi Dzal, sehingga jadilah Tadzakkaruuna, artinya mengambil pelajaran. Maksudnya, apakah kalian tidak mengambil pelajaran daripadanya, karena kalian mengetahui, bahwa Tuhan Yang Maha Kuasa yang telah menciptakan untuk pertama kali, Maha Kuasa pula untuk menghidupkannya kembali, sesudah ciptaan-Nya mati.",[["سَيَقُولُونَ","They will say"],["لِلَّهِ ۚ","To Allah"],["قُلْ","Say"],["أَفَلَا","Then will not"],["تَذَكَّرُونَ","you remember"]]],"2759":["(Katakanlah! \"Siapakah Rabb langit yang tujuh dan Rabb Arasy yang besar\") yakni Al Kursi.",[["قُلْ","Say"],["مَن","Who"],["رَّبُّ","(is the) Lord"],["ٱلسَّمَـٰوَٰتِ","(of) the seven heavens"],["ٱلسَّبْعِ","(of) the seven heavens"],["وَرَبُّ","and (the) Lord"],["ٱلْعَرْشِ","(of) the Throne"],["ٱلْعَظِيمِ","the Great"]]],"2760":["(Mereka akan menjawab, \"Kepunyaan Allah\". Katakanlah! \"Apakah kalian tidak bertakwa?\") tidak takut bila kalian menyembah selain-Nya.",[["سَيَقُولُونَ","They will say"],["لِلَّهِ ۚ","Allah"],["قُلْ","Say"],["أَفَلَا","Then will not"],["تَتَّقُونَ","you fear (Him)"]]],"2761":["(Katakanlah! \"Siapakah yang di tangan-Nya berada kekuasaan) yakni merajai (segala sesuatu) lafal Malakuut huruf Ta yang ada padanya menunjukkan makna Mubalaghah, yakni kekuasaan di atas segala kekuasaan (sedangkan Dia melindungi dan tidak membutuhkan perlindungan) Dia melindungi dan tidak memerlukan perlindungan (jika kalian mengetahui?\")",[["قُلْ","Say"],["مَنۢ","Who is (it)"],["بِيَدِهِۦ","in Whose Hand(s)"],["مَلَكُوتُ","(is the) dominion"],["كُلِّ","(of) all"],["شَىْءٍۢ","things"],["وَهُوَ","and He"],["يُجِيرُ","protects"],["وَلَا","and no (one)"],["يُجَارُ","(can) be protected"],["عَلَيْهِ","against Him"],["إِن","If"],["كُنتُمْ","you"],["تَعْلَمُونَ","know"]]],"2762":["(Mereka akan menjawab, \"Kepunyaan Allah\") menurut qiraat yang lain dibaca Allah, baik dalam ayat ini maupun dalam ayat sebelumnya. Demikian itu karena makna yang dimaksud adalah, kepunyaan siapakah hal-hal yang telah disebutkan itu (Katakanlah! \"Kalau demikian maka dari jalan manakah kalian merasa ditipu?\") ditipu dan dikelabui dari perkara yang hak, yaitu menyembah Allah semata. Maksudnya, bagaimanakah bisa terbayangkan dalam benak kalian bahwasanya hal ini batil?",[["سَيَقُولُونَ","They will say"],["لِلَّهِ ۚ","Allah"],["قُلْ","Say"],["فَأَنَّىٰ","Then how"],["تُسْحَرُونَ","are you deluded"]]],"2763":["(Sebenarnya Kami telah membawa kebenaran kepada mereka) dengan sesungguhnya (dan sesungguhnya mereka benar-benar orang-orang yang berdusta) sewaktu mereka menentang kebenaran itu; kebenaran tersebut adalah,",[["بَلْ","Nay"],["أَتَيْنَـٰهُم","We (have) brought them"],["بِٱلْحَقِّ","the truth"],["وَإِنَّهُمْ","but indeed, they"],["لَكَـٰذِبُونَ","surely, (are) liars"]]],"2764":["(Allah sekali-kali tidak mempunyai anak, dan sekali-kali tidak ada tuhan yang lain beserta-Nya, kalau ada tuhan beserta-Nya) jika ada tuhan lain di samping Dia (masing-masing tuhan itu akan membawa makhluk yang diciptakannya) yang menguasai makhluknya sendiri dan mempertahankannya dari makhluk tuhan yang lain (dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain) sebagian di antara mereka berupaya untuk mengalahkan sebagian yang lain sebagaimana apa yang biasa dilakukan oleh raja-raja di dunia. (Maha Suci Allah) lafal Subhaanallaah ini berarti mensucikan Dia (dari apa yang mereka sifatkan) kepada-Nya, seperti apa yang telah disebutkan tadi.",[["مَا","Not"],["ٱتَّخَذَ","Allah has taken"],["ٱللَّهُ","Allah has taken"],["مِن","any"],["وَلَدٍۢ","son"],["وَمَا","and not"],["كَانَ","is"],["مَعَهُۥ","with Him"],["مِنْ","any"],["إِلَـٰهٍ ۚ","god"],["إِذًۭا","Then"],["لَّذَهَبَ","surely (would have) taken away"],["كُلُّ","each"],["إِلَـٰهٍۭ","god"],["بِمَا","what"],["خَلَقَ","he created"],["وَلَعَلَا","and surely would have overpowered"],["بَعْضُهُمْ","some of them"],["عَلَىٰ","[on]"],["بَعْضٍۢ ۚ","others"],["سُبْحَـٰنَ","Glory be"],["ٱللَّهِ","(to) Allah"],["عَمَّا","above what"],["يَصِفُونَ","they attribute"]]],"2765":["(Yang mengetahui semua yang gaib dan semua yang tampak) maksudnya semua yang tidak tampak dan semua yang tampak. Kalau dibaca 'Aalimil Ghaibi menjadi sifat, artinya yang mengetahui dan seterusnya. Jika dibaca 'Aalimul Ghaibi berarti menjadi Khabar dari Mubtada yang tidak disebutkan yaitu lafal Huwa, artinya Dia Mengetahui yang gaib (maka Maha Tinggi Dia) Maha Besar Dia (dari apa yang mereka persekutukan) kepada-Nya.",[["عَـٰلِمِ","Knower"],["ٱلْغَيْبِ","(of) the unseen"],["وَٱلشَّهَـٰدَةِ","and the witnessed"],["فَتَعَـٰلَىٰ","exalted is He"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate"]]],"2766":["(Katakanlah! \"Ya Rabbku! Jika) lafal Imma pada asalnya terdiri daripada gabungan antara In Syarthiyyah dan Ma Zaidah (Engkau sungguh-sungguh hendak memperlihatkan kepadaku apa yang diancamkan kepada mereka) berupa azab, hal ini benar-benar terjadi dalam perang Badar, yaitu banyak dari kalangan orang-orang musyrik yang mati terbunuh.",[["قُل","Say"],["رَّبِّ","My Lord"],["إِمَّا","If"],["تُرِيَنِّى","You should show me"],["مَا","what"],["يُوعَدُونَ","they are promised"]]],"2767":["(Ya Rabbku! Maka janganlah Engkau jadikan aku berada di antara orang-orang yang zalim.\") karena aku pun nanti akan binasa pula bersama dengan mereka.",[["رَبِّ","My Lord"],["فَلَا","then (do) not"],["تَجْعَلْنِى","place me"],["فِى","among"],["ٱلْقَوْمِ","the people "],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"2768":["(Dan sesungguhnya Kami benar-benar kuasa untuk memperlihatkan kepadamu apa yang Kami ancamkan kepada mereka).",[["وَإِنَّا","And indeed We"],["عَلَىٰٓ","on"],["أَن","that"],["نُّرِيَكَ","We show you"],["مَا","what"],["نَعِدُهُمْ","We have promised them"],["لَقَـٰدِرُونَ","surely able"]]],"2769":["(Tolaklah dengan menampilkan hal yang lebih baik) yaitu budi pekerti yang baik, bersikap lapang dada dan berpaling dari mereka yang kafir (hal yang buruk itu) perlakuan mereka yang menyakitkan terhadap dirimu. Ayat ini diturunkan sebelum ada perintah untuk berperang. (Kami lebih mengetahui apa yang mereka sifatkan) kedustaan dan buat-buatan mereka, maka kelak Kami akan membalasnya kepada mereka.",[["ٱدْفَعْ","Repel"],["بِٱلَّتِى","by that"],["هِىَ","which"],["أَحْسَنُ","(is) best "],["ٱلسَّيِّئَةَ ۚ","the evil"],["نَحْنُ","We"],["أَعْلَمُ","know best"],["بِمَا","of what"],["يَصِفُونَ","they attribute"]]],"2770":["(Dan katakanlah! \"Ya Rabbku! Aku berlindung kepada Engkau) aku meminta perlindungan (dari bisikan-bisikan setan) dari kecenderungan-kecenderungan setan yang selalu setan embus-embuskan itu.",[["وَقُل","And say"],["رَّبِّ","My Lord"],["أَعُوذُ","I seek refuge"],["بِكَ","in You"],["مِنْ","from"],["هَمَزَٰتِ","(the) suggestions"],["ٱلشَّيَـٰطِينِ","(of) the evil ones"]]],"2771":["(Dan aku berlindung pula kepada Engkau, ya Rabbku, dari kedatangan setan-setan itu kepadaku\") dalam perkara-perkaraku, karena sesungguhnya mereka datang hanya dengan membawa keburukan belaka.",[["وَأَعُوذُ","And I seek refuge"],["بِكَ","in You"],["رَبِّ","My Lord"],["أَن","Lest"],["يَحْضُرُونِ","they be present with me"]]],"2772":["(Sehingga) lafal Hattaa menunjukkan makna Ibtida atau permulaan (apabila datang kematian kepada seseorang dari mereka) kemudian ia melihat kedudukannya di neraka dan di surga seandainya ia beriman (dia berkata, \"Ya Rabbku! Kembalikanlah aku) ke dunia. Ungkapan Jamak pada lafal Irji'uuni mengandung makna Ta'zhim atau mengagungkan.",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["جَآءَ","comes"],["أَحَدَهُمُ","(to) one of them"],["ٱلْمَوْتُ","the death"],["قَالَ","he says"],["رَبِّ","My Lord"],["ٱرْجِعُونِ","Send me back"]]],"2773":["(Agar aku berbuat amal yang saleh) dengan mengatakan, 'Aku bersaksi tiada Tuhan selain Allah', hal ini akan menjadi penghapus (terhadap yang telah aku tinggalkan\") aku sia-siakan umurku. Maksudnya, supaya hal itu menjadi penggantinya. Maka Allah berfirman, (\"Sekali-kali tidak) tidak ada kembali lagi. (Sesungguhnya itu) permohonan untuk kembali ke dunia (adalah perkataan yang diucapkannya saja) tidak ada manfaat bagi pembicaranya. (Dan di hadapan mereka) (ada dinding) penghalang yang menahan mereka untuk dapat kembali lagi ke dunia (sampai hari mereka dibangkitkan\") yang tiada kembali lagi sesudahnya.",[["لَعَلِّىٓ","That I may"],["أَعْمَلُ","do"],["صَـٰلِحًۭا","righteous (deeds)"],["فِيمَا","in what"],["تَرَكْتُ ۚ","I left behind"],["كَلَّآ ۚ","No"],["إِنَّهَا","Indeed, it"],["كَلِمَةٌ","(is) a word"],["هُوَ","he"],["قَآئِلُهَا ۖ","speaks it"],["وَمِن","and before them"],["وَرَآئِهِم","and before them"],["بَرْزَخٌ","(is) a barrier"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["يُبْعَثُونَ","they are resurrected"]]],"2774":["(Apabila sangkakala ditiup) tiupan malaikat Israfil yang pertama atau yang kedua (maka tidaklah ada lagi pertalian nasab di antara mereka pada hari itu) yang dapat mereka bangga-banggakan (dan tidak pula mereka saling bertanya) tentang nasab tersebut, berbeda dengan ketika mereka hidup di dunia. Hal tersebut disebabkan kengerian yang menyibukkan diri mereka pada hari kiamat itu, yakni melihat sebagian kengerian-kengerian yang ada padanya. Pada sebagian waktu dari hari kiamat mereka sadar pula, sebagaimana yang diungkapkan oleh ayat yang lain, yaitu, \"Dan sebagian dari mereka menghadap kepada sebagian yang lain berbantah-bantahan.\" (Q.S. Ash-Shaffat, 27).",[["فَإِذَا","So when"],["نُفِخَ","is blown"],["فِى","in"],["ٱلصُّورِ","the trumpet"],["فَلَآ","then not"],["أَنسَابَ","(there) will be relationship"],["بَيْنَهُمْ","among them"],["يَوْمَئِذٍۢ","that Day"],["وَلَا","and not"],["يَتَسَآءَلُونَ","will they ask each other"]]],"2775":["(Barang siapa yang berat timbangannya) karena amal-amal kebaikan (maka mereka itulah orang-orang yang mendapat keberuntungan) yakni orang-orang yang beruntung.",[["فَمَن","Then (the one) whose"],["ثَقُلَتْ","(are) heavy"],["مَوَٰزِينُهُۥ","his scales"],["فَأُو۟لَـٰٓئِكَ","then those "],["هُمُ","they"],["ٱلْمُفْلِحُونَ","(are) the successful"]]],"2776":["(Dan barang siapa yang ringan timbangannya) karena dosa-dosanya (maka mereka itulah orang-orang yang merugikan dirinya sendiri) maka mereka (kekal di dalam neraka Jahanam).",[["وَمَنْ","But (the one) whose"],["خَفَّتْ","(are) light"],["مَوَٰزِينُهُۥ","his scales"],["فَأُو۟لَـٰٓئِكَ","then those"],["ٱلَّذِينَ","they [who]"],["خَسِرُوٓا۟","have lost"],["أَنفُسَهُمْ","their souls"],["فِى","in"],["جَهَنَّمَ","Hell"],["خَـٰلِدُونَ","they (will) abide forever"]]],"2777":["(Muka mereka dibakar api neraka) api neraka membakarnya (dan mereka di dalam neraka itu dalam keadaan cacat) bibir mereka bagian atas dan bawah mengkerut memperlihatkan gigi-gigi mereka, kemudian dikatakan kepada mereka,",[["تَلْفَحُ","Will burn"],["وُجُوهَهُمُ","their faces"],["ٱلنَّارُ","the Fire"],["وَهُمْ","and they"],["فِيهَا","in it"],["كَـٰلِحُونَ","(will) grin with displaced lips"]]],"2778":["(Bukankah ayat-ayat-Ku) dari Alquran (telah dibacakan kepada kamu sekalian) maksudnya kalian telah diperingatkan melaluinya (tetapi kalian selalu mendustakannya?)",[["أَلَمْ","Were not"],["تَكُنْ","Were not"],["ءَايَـٰتِى","My Verses"],["تُتْلَىٰ","recited"],["عَلَيْكُمْ","to you"],["فَكُنتُم","and you used (to)"],["بِهَا","deny them"],["تُكَذِّبُونَ","deny them"]]],"2779":["(Mereka berkata, \"Ya Rabb kami! Kami telah dikuasai oleh kejahatan kami) menurut qiraat yang lain dibaca Syaqawatunaa, keduanya merupakan Mashdar dan bermakna sama, yaitu kejahatan kami (dan adalah kami orang-orang yang sesat) dari jalan petunjuk.",[["قَالُوا۟","They (will) say"],["رَبَّنَا","Our Lord"],["غَلَبَتْ","Overcame"],["عَلَيْنَا","[on] us"],["شِقْوَتُنَا","our wretchedness"],["وَكُنَّا","and we were"],["قَوْمًۭا","a people"],["ضَآلِّينَ","astray"]]],"2780":["(Ya Rabb kami! Keluarkanlah kami daripadanya maka jika kami kembali) kepada pelanggaran lagi (maka sesungguhnya kami adalah orang-orang yang zalim\").",[["رَبَّنَآ","Our Lord"],["أَخْرِجْنَا","Bring us out"],["مِنْهَا","from it"],["فَإِنْ","then if"],["عُدْنَا","we return"],["فَإِنَّا","then indeed, we"],["ظَـٰلِمُونَ","(would be) wrongdoers"]]],"2781":["(Allah berfirman) kepada mereka melalui lisan malaikat Malik penjaga neraka, sesudah jangka waktu yang lamanya dua kali lipat umur dunia, (\"Tinggallah dengan hina di dalamnya) makin menjauhlah kalian di dalam neraka dengan hina (dan janganlah kalian berbicara dengan Aku\") untuk meminta supaya azab dihentikan dari diri kalian; dijawab demikian supaya mereka tidak mempunyai harapan lagi untuk dapat diangkat dari dalam neraka.",[["قَالَ","He (will) say"],["ٱخْسَـُٔوا۟","Remain despised"],["فِيهَا","in it"],["وَلَا","and (do) not"],["تُكَلِّمُونِ","speak to Me"]]],"2782":["(Sesungguhnya ada segolongan dari hamba-hamba-Ku) mereka adalah kaum Muhajirin (berdoa, \"Ya Rabb kami! Kami telah beriman, maka ampunilah kami dan berilah kami rahmat dan Engkau adalah Pemberi rahmat Yang Paling Baik\").",[["إِنَّهُۥ","Indeed"],["كَانَ","(there) was"],["فَرِيقٌۭ","a party"],["مِّنْ","of"],["عِبَادِى","My slaves"],["يَقُولُونَ","(who) said"],["رَبَّنَآ","Our Lord"],["ءَامَنَّا","We believe"],["فَٱغْفِرْ","so forgive"],["لَنَا","us"],["وَٱرْحَمْنَا","and have mercy on us"],["وَأَنتَ","and You"],["خَيْرُ","(are) best"],["ٱلرَّٰحِمِينَ","(of) those who show mercy"]]],"2783":["(Lalu kalian menjadikan mereka buah ejekan) lafal Sikhriyyan dapat pula dibaca Sukhriyyan keduanya merupakan bentuk Mashdar, maknanya adalah ejekan. Di antara mereka yang menjadi bahan ejekan orang-orang musyrik adalah sahabat Bilal, sahabat Shuhaib, sahabat Ammar, sahabat Salman (sehingga menjadikan kalian lupa mengingat Aku) kalian melupakannya disebabkan kalian sibuk dengan memperolok-olokkan mereka. Mengingat mereka sering lupa, maka sifat pelupa dinisbatkan kepada mereka (dan adalah kalian selalu menertawakan mereka).",[["فَٱتَّخَذْتُمُوهُمْ","But you took them"],["سِخْرِيًّا","(in) mockery"],["حَتَّىٰٓ","until"],["أَنسَوْكُمْ","they made you forget"],["ذِكْرِى","My remembrance"],["وَكُنتُم","and you used (to)"],["مِّنْهُمْ","at them"],["تَضْحَكُونَ","laugh"]]],"2784":["(Sesungguhnya Aku memberi balasan kepada mereka di hari ini) kenikmatan yang abadi (karena kesabaran mereka) dalam menghadapi ejekan kalian dan perlakuan yang menyakitkan dari kalian terhadap mereka (sesungguhnya mereka) bila dibaca Innahum berarti jumlah Isti'naf, artinya, sesungguhnya mereka. Jika dibaca Annahum berarti menjadi Maf'ul kedua dari lafal Jazaituhum, artinya, bahwasanya mereka (itulah orang-orang yang menang) memperoleh apa yang mereka dambakan.",[["إِنِّى","Indeed, I"],["جَزَيْتُهُمُ","have rewarded them"],["ٱلْيَوْمَ","this Day"],["بِمَا","because"],["صَبَرُوٓا۟","they were patient"],["أَنَّهُمْ","indeed, they"],["هُمُ","[they]"],["ٱلْفَآئِزُونَ","(are) the successful ones"]]],"2785":["(Berfirmanlah) Allah swt. kepada mereka melalui lisan malaikat Malik. Menurut qiraat yang lain dibaca Qul, yakni katakanlah kepada mereka, (\"Berapa lamakah kalian tinggal di bumi) di dunia dan di dalam kuburan kalian (yakni berapa tahunkah bilangannya?\") lafal 'Adada Siniina berkedudukan menjadi Tamyiz.",[["قَـٰلَ","He will say"],["كَمْ","How long"],["لَبِثْتُمْ","did you remain"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["عَدَدَ","(in) number"],["سِنِينَ","(of) years"]]],"2786":["(Mereka menjawab, \"Kami tinggal hanya sehari atau setengah hari) mereka ragu, dan menganggap pendek masa tinggal mereka disebabkan kengerian mereka melihat besarnya azab di hari itu (maka tanyakanlah kepada malaikat-malaikat yang menghitung\") amal perbuatan makhluk.",[["قَالُوا۟","They will say"],["لَبِثْنَا","We remained"],["يَوْمًا","a day"],["أَوْ","or"],["بَعْضَ","a part"],["يَوْمٍۢ","(of) a day"],["فَسْـَٔلِ","but ask"],["ٱلْعَآدِّينَ","those who keep count"]]],"2787":["(Berfirmanlah) Allah swt. melalui lisan malaikat Malik. Menurut qiraat yang lain lafal Qaala dibaca Qul, artinya katakanlah. (\"Tiada lain) (kalian tinggal hanya sebentar saja, kalau kalian sesungguhnya mengetahui\") lama masa tinggal kalian itu, sedikit sekali jika dibandingkan keabadian kalian di dalam neraka.",[["قَـٰلَ","He will say"],["إِن","Not"],["لَّبِثْتُمْ","you stayed"],["إِلَّا","but"],["قَلِيلًۭا ۖ","a little"],["لَّوْ","if"],["أَنَّكُمْ","only you"],["كُنتُمْ","[you]"],["تَعْلَمُونَ","knew"]]],"2788":["(Maka apakah kalian mengira, bahwa sesungguhnya Kami menciptakan kalian secara bermain-main) yakni tidak ada hikmah dan manfaatnya (dan bahwa kalian tidak akan dikembalikan kepada Kami?) kalau dibaca Laa Turja'uuna artinya, kalian tidak dikembalikan. Dan kalau dibaca Tarji'uuna artinya, kalian akan kembali. Tentu saja tidak, sebenarnya supaya kalian menjadi hamba-hamba-Ku untuk Kami perintah dan Kami larang, kemudian kalian kembali kepada Kami untuk menerima pembalasan amal perbuatan kalian. Hal ini sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Dan Aku tidak menciptakan jin dan manusia melainkan supaya mereka menyembah Aku.\" (Q.S. Adz-Dzariyat, 56).",[["أَفَحَسِبْتُمْ","Then did you think"],["أَنَّمَا","that"],["خَلَقْنَـٰكُمْ","We created you"],["عَبَثًۭا","uselessly"],["وَأَنَّكُمْ","and that you"],["إِلَيْنَا","to Us"],["لَا","not"],["تُرْجَعُونَ","will be returned"]]],"2789":["(Maka Maha Tinggi Allah) dari main-main dan hal-hal lainnya yang tidak layak bagi kebesaran-Nya (Raja Yang Sebenarnya; tidak ada Tuhan selain Dia, Rabb Yang mempunyai Arasy yang mulia) yakni Al-Kursi atau singgasana bagi raja.",[["فَتَعَـٰلَى","So exalted is"],["ٱللَّهُ","Allah"],["ٱلْمَلِكُ","the King"],["ٱلْحَقُّ ۖ","the Truth"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ","Him"],["رَبُّ","(the) Lord"],["ٱلْعَرْشِ","(of) the Throne"],["ٱلْكَرِيمِ","Honorable"]]],"2790":["(Dan barang siapa menyembah tuhan yang lain di samping Allah, padahal tak ada suatu dalil pun baginya tentang itu) lafal Laa Burhaana ini menjadi sifat yang Kasyifah atau yang terbuka, akan tetapi tidak dimengerti, karena pada kenyataannya hal itu mustahil (maka sesungguhnya perhitungannya) yakni pembalasan perbuatannya itu (di sisi Rabbnya. Sesungguhnya orang-orang yang kafir itu tidak beruntung) yakni tidak berbahagia.",[["وَمَن","And whoever"],["يَدْعُ","invokes"],["مَعَ","with"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","god"],["ءَاخَرَ","other"],["لَا","no"],["بُرْهَـٰنَ","proof"],["لَهُۥ","for him"],["بِهِۦ","in it"],["فَإِنَّمَا","Then only"],["حِسَابُهُۥ","his account"],["عِندَ","(is) with"],["رَبِّهِۦٓ ۚ","his Lord"],["إِنَّهُۥ","Indeed, [he]"],["لَا","not"],["يُفْلِحُ","will succeed"],["ٱلْكَـٰفِرُونَ","the disbelievers"]]],"2791":["(Dan katakanlah! \"Ya Rabbku! Berilah ampun dan berilah rahmat) kepada orang-orang Mukmin dalam bentuk rahmat di samping ampunan itu (dan Engkau adalah pemberi rahmat yang paling baik\") artinya Pemberi rahmat yang paling utama.",[["وَقُل","And say"],["رَّبِّ","My Lord"],["ٱغْفِرْ","Forgive"],["وَٱرْحَمْ","and have mercy"],["وَأَنتَ","and You"],["خَيْرُ","(are the) Best"],["ٱلرَّٰحِمِينَ","(of) those who show mercy"]]],"2792":["Ini adalah (suatu surah yang Kami turunkan dan Kami wajibkan) dapat dibaca secara Takhfif, yaitu Faradhnaahaa, dapat pula dibaca secara Musyaddad, yaitu Farradhnaahaa. Dikatakan demikian karena banyaknya fardu-fardu atau kewajiban-kewajiban yang terkandung di dalamnya (dan Kami turunkan di dalamnya ayat-ayat yang jelas) yakni jelas dan gamblang maksud-maksudnya (agar kalian selalu mengingatnya) asal kata Tadzakkaruuna ialah Tatadzakkaruuna, kemudian huruf Ta yang kedua diidgamkan kepada huruf Zal, sehingga menjadi Tadzakkaruuna, artinya mengambil pelajaran daripadanya.",[["سُورَةٌ","A Surah "],["أَنزَلْنَـٰهَا","We (have) sent it down"],["وَفَرَضْنَـٰهَا","and We (have) made it obligatory"],["وَأَنزَلْنَا","and We (have) revealed"],["فِيهَآ","therein"],["ءَايَـٰتٍۭ","Verses"],["بَيِّنَـٰتٍۢ","clear"],["لَّعَلَّكُمْ","so that you may"],["تَذَكَّرُونَ","take heed"]]],"2793":["(Perempuan yang berzina dan laki-laki yang berzina) kedua-duanya bukan muhshan atau orang yang terpelihara dari berzina disebabkan telah kawin. Hadd bagi pelaku zina muhshan adalah rajam, menurut keterangan dari Sunah. Huruf Al yang memasuki kedua lafal ini adalah Al Maushulah sekaligus sebagai Mubtada, mengingat kedudukan Mubtada di sini mirip dengan Syarat, maka Khabarnya kemasukan huruf Fa, sebagaimana yang disebutkan dalam ayat berikutnya, yaitu, (maka deralah tiap-tiap seorang dari keduanya seratus kali dera) yakni sebanyak seratus kali pukulan. Jika dikatakan Jaladahu artinya ia memukul kulit seseorang; makna yang dimaksud adalah mendera. Kemudian ditambahkan hukuman pelaku zina yang bukan muhshan ini menurut keterangan dari Sunah, yaitu harus diasingkan atau dibuang selama satu tahun penuh. Bagi hamba sahaya hanya dikenakan hukuman separuh dari hukuman orang yang merdeka tadi (dan janganlah belas kasihan kalian kepada keduanya mencegah kalian untuk menjalankan agama Allah) yakni hukum-Nya, seumpamanya kalian melalaikan sesuatu dari hudud yang harus diterima keduanya (jika kalian beriman kepada Allah dan hari akhirat) yaitu hari berbangkit. Dalam ungkapan ayat ini terkandung anjuran untuk melakukan pengertian yang terkandung sebelum syarat. Ungkapan sebelum syarat tadi, yaitu kalimat \"Dan janganlah belas kasihan kalian kepada keduanya, mencegah kalian untuk menjalankan hukum Allah\", merupakan Jawab dari Syarat, atau menunjukkan kepada pengertian Jawab Syarat (dan hendaklah hukuman mereka berdua disaksikan) dalam pelaksanaan hukuman deranya (oleh sekumpulan dari orang-orang yang beriman) menurut suatu pendapat para saksi itu cukup tiga orang saja; sedangkan menurut pendapat yang lain, bahwa saksi-saksi itu jumlahnya harus sama dengan para saksi perbuatan zina, yaitu sebanyak empat orang saksi laki-laki.",[["ٱلزَّانِيَةُ","The fornicatress"],["وَٱلزَّانِى","and the fornicator"],["فَٱجْلِدُوا۟","[then] flog"],["كُلَّ","each"],["وَٰحِدٍۢ","one"],["مِّنْهُمَا","of them"],["مِا۟ئَةَ","(with) hundred"],["جَلْدَةٍۢ ۖ","lash(es)"],["وَلَا","And (let) not"],["تَأْخُذْكُم","withhold you"],["بِهِمَا","pity for them"],["رَأْفَةٌۭ","pity for them"],["فِى","concerning"],["دِينِ","(the) religion of Allah"],["ٱللَّهِ","(the) religion of Allah"],["إِن","if"],["كُنتُمْ","you"],["تُؤْمِنُونَ","believe"],["بِٱللَّهِ","in Allah"],["وَٱلْيَوْمِ","and the Day"],["ٱلْـَٔاخِرِ ۖ","the Last"],["وَلْيَشْهَدْ","And let witness"],["عَذَابَهُمَا","their punishment"],["طَآئِفَةٌۭ","a group"],["مِّنَ","of"],["ٱلْمُؤْمِنِينَ","the believers"]]],"2794":["(Laki-laki yang berzina tidak menikahi) (melainkan perempuan yang berzina atau perempuan yang musyrik; dan perempuan yang berzina tidak dikawini melainkan oleh laki-laki yang berzina atau laki-laki yang musyrik) pasangan yang cocok buat masing-masingnya sebagaimana yang telah disebutkan tadi (dan yang demikian itu diharamkan) menikahi perempuan-perempuan yang berzina (atas orang-orang Mukmin) yang terpilih. Ayat ini diturunkan tatkala orang-orang miskin dari kalangan sahabat Muhajirin berniat untuk mengawini para pelacur orang-orang musyrik, karena mereka orang kaya-kaya. Kaum Muhajirin yang miskin menyangka kekayaan yang dimilikinya itu akan dapat menanggung nafkah mereka. Karena itu dikatakan, bahwa pengharaman ini khusus bagi para sahabat Muhajirin yang miskin tadi. Tetapi menurut pendapat yang lain mengatakan pengharaman ini bersifat umum dan menyeluruh, kemudian ayat ini dinasakh oleh firman-Nya yang lain, yaitu, \"Dan nikahkanlah orang-orang yang sendirian di antara kalian...\" (Q.S. An Nur, 32).",[["ٱلزَّانِى","The fornicator"],["لَا","(will) not"],["يَنكِحُ","marry"],["إِلَّا","except"],["زَانِيَةً","a fornicatress"],["أَوْ","or"],["مُشْرِكَةًۭ","a polytheist woman"],["وَٱلزَّانِيَةُ","and the fornicatress "],["لَا","(will) not"],["يَنكِحُهَآ","marry her"],["إِلَّا","except"],["زَانٍ","a fornicator"],["أَوْ","or"],["مُشْرِكٌۭ ۚ","a polytheist man"],["وَحُرِّمَ","And is forbidden"],["ذَٰلِكَ","that"],["عَلَى","to"],["ٱلْمُؤْمِنِينَ","the believers"]]],"2795":["(Dan orang-orang yang menuduh wanita-wanita yang baik-baik) menuduh berzina wanita-wanita yang memelihara dirinya dari perbuatan zina (dan mereka tidak mendatangkan empat orang saksi) yang menyaksikan perbuatan zina mereka dengan mata kepala sendiri (maka deralah mereka) bagi masing-masing dari mereka (delapan puluh kali dera, dan janganlah kalian terima kesaksian mereka) dalam suatu perkara pun (buat selama-lamanya. Dan mereka itulah orang-orang yang fasik) karena mereka telah melakukan dosa besar.",[["وَٱلَّذِينَ","And those who"],["يَرْمُونَ","accuse"],["ٱلْمُحْصَنَـٰتِ","the chaste women"],["ثُمَّ","then"],["لَمْ","not"],["يَأْتُوا۟","they bring"],["بِأَرْبَعَةِ","four"],["شُهَدَآءَ","witnesses"],["فَٱجْلِدُوهُمْ","then flog them"],["ثَمَـٰنِينَ","(with) eighty"],["جَلْدَةًۭ","lashe(s)"],["وَلَا","and (do) not"],["تَقْبَلُوا۟","accept"],["لَهُمْ","their"],["شَهَـٰدَةً","testimony"],["أَبَدًۭا ۚ","ever"],["وَأُو۟لَـٰٓئِكَ","And those"],["هُمُ","they"],["ٱلْفَـٰسِقُونَ","(are) the defiantly disobedient"]]],"2796":["(Kecuali orang-orang yang bertobat sesudah itu dan memperbaiki) amal perbuatan mereka (maka sesungguhnya Allah Maha Pengampun) terhadap dosa tuduhan mereka itu (lagi Maha Penyayang) kepada mereka, yaitu dengan memberikan inspirasi untuk bertobat kepada mereka, yang dengan tobat itu terhapuslah julukan fasik dari diri mereka, kemudian kesaksian mereka dapat diterima kembali. Akan tetapi menurut suatu pendapat bahwa kesaksian mereka tetap tidak dapat diterima. Pendapat ini beranggapan bahwa pengertian Istitsna atau pengecualian di sini hanya kembali kepada kalimat terakhir dari ayat sebelumnya tadi, yaitu, \"Dan mereka itulah orang-orang yang fasik\". Maksudnya hanya status fasik saja yang dihapus dari mereka, sedangkan ketiadagunaan kesaksiannya masih tetap.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["تَابُوا۟","repent"],["مِنۢ","after"],["بَعْدِ","after"],["ذَٰلِكَ","that"],["وَأَصْلَحُوا۟","and reform"],["فَإِنَّ","Then indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"2797":["(Dan orang-orang yang menuduh istrinya) berbuat zina (padahal mereka tidak mempunyai saksi-saksi) atas perbuatan itu (selain diri mereka sendiri) kasus ini telah terjadi pada segolongan para Sahabat (maka persaksian orang itu) lafal ayat ini menjadi Mubtada (ialah empat kali bersumpah) lafal ayat ini dapat dinashabkan karena dianggap sebagai Mashdar (dengan nama Allah, sesungguhnya dia adalah termasuk orang-orang yang benar) dalam tuduhan yang ia lancarkan kepada istrinya itu, yakni tuduhan berbuat zina.",[["وَٱلَّذِينَ","And those who"],["يَرْمُونَ","accuse"],["أَزْوَٰجَهُمْ","their spouses"],["وَلَمْ","and not"],["يَكُن","have"],["لَّهُمْ","for them"],["شُهَدَآءُ","witnesses"],["إِلَّآ","except"],["أَنفُسُهُمْ","themselves"],["فَشَهَـٰدَةُ","then (the) testimony"],["أَحَدِهِمْ","(of) one of them"],["أَرْبَعُ","(is) four"],["شَهَـٰدَٰتٍۭ","testimonies"],["بِٱللَّهِ ۙ","by Allah"],["إِنَّهُۥ","that he"],["لَمِنَ","(is) surely of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"2798":["(Dan sumpah yang kelima, bahwa laknat Allah atasnya, jika ia termasuk orang-orang yang berdusta) dalam hal ini yang menjadi Khabar dari Mubtada pada ayat yang sebelumnya tadi ialah, Untuk menolak hukuman hudud menuduh berzina yang akan ditimpakan atas dirinya.",[["وَٱلْخَـٰمِسَةُ","And the fifth"],["أَنَّ","that"],["لَعْنَتَ","(the) curse of Allah"],["ٱللَّهِ","(the) curse of Allah"],["عَلَيْهِ","(be) upon him"],["إِن","if"],["كَانَ","he is"],["مِنَ","of"],["ٱلْكَـٰذِبِينَ","the liars"]]],"2799":["(Istrinya itu dapat dihindarkan) dapat mempertahankan dirinya (dari hukuman) hudud berzina yang telah dikuatkan dengan kesaksian sumpah suaminya yaitu (oleh sumpahnya empat kali atas nama Allah, sesungguhnya suaminya itu benar-benar termasuk orang-orang yang dusta) dalam tuduhan yang ia lancarkan terhadap dirinya, yaitu tuduhan melakukan zina.",[["وَيَدْرَؤُا۟","But it would prevent"],["عَنْهَا","from her"],["ٱلْعَذَابَ","the punishment"],["أَن","that"],["تَشْهَدَ","she bears witness"],["أَرْبَعَ","four"],["شَهَـٰدَٰتٍۭ","testimonies"],["بِٱللَّهِ ۙ","by Allah"],["إِنَّهُۥ","that he"],["لَمِنَ","(is) surely of"],["ٱلْكَـٰذِبِينَ","the liars"]]],"2800":["(Dan yang kelima, bahwa laknat Allah atasnya jika suaminya itu termasuk orang-orang yang benar) dalam tuduhannya itu.",[["وَٱلْخَـٰمِسَةَ","And the fifth"],["أَنَّ","that"],["غَضَبَ","the wrath of Allah"],["ٱللَّهِ","the wrath of Allah"],["عَلَيْهَآ","(be) upon her"],["إِن","if"],["كَانَ","he is"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"2801":["(Dan andaikata tidak ada karunia Allah dan rahmat-Nya atas diri kalian) dengan menutupi hal tersebut (dan andaikata Allah bukan Penerima tobat) maksudnya, Allah menerima tobatnya yang disebabkan tuduhannya itu dan dosa-dosa yang lainnya (lagi Maha Bijaksana) dalam keputusan-Nya mengenai masalah ini dan hal-hal yang lain, niscaya Dia akan menjelaskan mana yang benar dalam masalah ini, dan niscaya pula Dia akan menyegerakan hukuman-Nya kepada orang-orang yang berhak menerimanya.",[["وَلَوْلَا","And if not"],["فَضْلُ","(for) the Grace of Allah"],["ٱللَّهِ","(for) the Grace of Allah"],["عَلَيْكُمْ","upon you"],["وَرَحْمَتُهُۥ","and His Mercy "],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["تَوَّابٌ","(is) Oft-Returning (to Mercy)"],["حَكِيمٌ","All-Wise"]]],"2802":["(Sesungguhnya orang-orang yang membawa berita bohong) kedustaan yang paling buruk yang dilancarkan terhadap Siti Aisyah r.a. Umulmukminin, ia dituduh melakukan zina (adalah dari golongan kalian juga) yakni segolongan dari kaum Mukmin. Siti Aisyah mengatakan, bahwa mereka adalah Hissan bin Tsabit, Abdullah bin Ubay, Misthah dan Hamnah binti Jahsy. (Janganlah kalian kira bahwa berita bohong itu) hai orang-orang Mukmin selain dari mereka yang melancarkan tuduhan itu (buruk bagi kalian, tetapi hal itu mengandung kebaikan bagi kalian) dan Allah akan memberikan pahalanya kepada kalian. Kemudian Allah swt. menampakkan kebersihan Siti Aisyah r.a. Dan orang yang telah menolongnya yaitu Shofwan. Sehubungan dengan peristiwa ini Siti Aisyah r.a. telah menceritakan, sebagai berikut, \"Aku ikut bersama Nabi saw. dalam suatu peperangan, yaitu sesudah diturunkannya ayat mengenai hijab bagi kaum wanita. Setelah Nabi saw. menunaikan tugasnya, lalu ia kembali dan kota Madinah sudah dekat. Pada suatu malam setelah istirahat Nabi saw. menyerukan supaya rombongan melanjutkan perjalanan kembali. Aku pergi dari rombongan untuk membuang hajat besarku. Setelah selesai, aku kembali ke rombongan yang sedang bersiap-siap untuk berangkat, akan tetapi ternyata kalungku putus/jatuh, lalu aku kembali lagi ke tempat buang hajat tadi untuk mencarinya. Mereka mengangkat sekedupku ke atas unta kendaraanku, karena mereka menduga bahwa aku telah berada di dalamnya. Karena kaum wanita pada saat itu beratnya ringan sekali, disebabkan mereka hanya makan sedikit. Aku menemukan kembali kalungku yang hilang itu, lalu aku datang ke tempat rombongan, ternyata mereka telah berlalu. Lalu aku duduk di tempat semula, dengan harapan bahwa rombongan akan merasa kehilangan aku, lalu mereka kembali ke tempatku. Mataku mengantuk sekali, sehingga aku tertidur; sedangkan Shofwan pada waktu itu berada jauh dari rombongan pasukan karena beristirahat sendirian. Kemudian dari tempat istirahatnya itu ia melanjutkan kembali perjalanannya menyusul pasukan. Ketika ia sampai ke tempat pasukan, ia melihat ada seseorang sedang tidur, lalu ia langsung mengenaliku, karena ia pernah melihatku sebelum ayat hijab diturunkan. Aku terbangun ketika dia mengucapkan Istirja', 'yaitu kalimat Innaa Lillaahi Wa Innaa Ilaihi RaaJi'uuna'. Aku segera menutup wajahku dengan kain jilbab. Demi Allah, sepatah kata pun ia tidak berbicara denganku, terkecuali hanya kalimat Istirja'nya sewaktu ia merundukkan hewan hendaraannya kemudian ia turun dengan berpijak kepada kaki depan untanya. Selanjutnya aku menaiki unta kendaraannya dan ia langsung menuntun kendaraannya yang kunaiki, hingga kami dapat menyusul rombongan pasukan, yaitu sesudah mereka beristirahat pada siang hari yang panasnya terik. Akhirnya tersiarlah berita bohong yang keji itu, semoga binasalah mereka yang membuat-buatnya. Sumber pertama yang menyiarkannya adalah Abdullah bin Ubay bin Salul.\" Hanya sampai di sinilah kisah siti Aisyah menurut riwayat yang dikemukakan oleh Imam Bukhari dan Imam Muslim. Selanjutnya Allah berfirman, (\"Tiap-tiap seseorang dari mereka) akan dibalas kepadanya (dari dosa yang dikerjakannya) mengenai berita bohong ini. (Dan siapa di antara mereka yang mengambil bagian yang terbesar dalam penyiaran berita bohong itu) maksudnya orang yang menjadi biang keladi dan berperanan penting dalam penyiaran berita bohong ini, yang dimaksud adalah Abdullah bin Ubay (baginya azab yang besar\") yakni neraka kelak di akhirat",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["جَآءُو","brought"],["بِٱلْإِفْكِ","the lie"],["عُصْبَةٌۭ","(are) a group"],["مِّنكُمْ ۚ","among you"],["لَا","(Do) not"],["تَحْسَبُوهُ","think it"],["شَرًّۭا","bad"],["لَّكُم ۖ","for you"],["بَلْ","nay"],["هُوَ","it"],["خَيْرٌۭ","(is) good"],["لَّكُمْ ۚ","for you"],["لِكُلِّ","For every"],["ٱمْرِئٍۢ","person"],["مِّنْهُم","among them"],["مَّا","(is) what"],["ٱكْتَسَبَ","he earned"],["مِنَ","of"],["ٱلْإِثْمِ ۚ","the sin"],["وَٱلَّذِى","and the one who"],["تَوَلَّىٰ","took upon himself a greater share of it"],["كِبْرَهُۥ","took upon himself a greater share of it"],["مِنْهُمْ","among them "],["لَهُۥ","for him"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"2803":["(Mengapa tidak, sewaktu kalian mendengar berita bohong itu orang-orang Mukmin dan Mukminat berprasangka terhadap diri mereka sendiri) sebagian dari mereka mempunyai prasangka terhadap sebagian yang lain (dengan sangkaan yang baik, dan mengapa tidak berkata, \"Ini adalah suatu berita bohong yang nyata\") dan jelas bohongnya. Di dalam ayat ini terkandung ungkapan Iltifat dari orang-orang yang diajak bicara. Maksudnya, mengapa kalian hai golongan orang-orang yang menuduh, mempunyai dugaan seperti itu dan berani mengatakan hal itu?",[["لَّوْلَآ","Why not"],["إِذْ","when"],["سَمِعْتُمُوهُ","you heard it"],["ظَنَّ","think"],["ٱلْمُؤْمِنُونَ","the believing men"],["وَٱلْمُؤْمِنَـٰتُ","and the believing women"],["بِأَنفُسِهِمْ","good of themselves"],["خَيْرًۭا","good of themselves"],["وَقَالُوا۟","and say"],["هَـٰذَآ","This"],["إِفْكٌۭ","(is) a lie"],["مُّبِينٌۭ","clear"]]],"2804":["(Mengapa tidak) (mendatangkan) golongan yang menuduh itu (empat orang saksi atas berita bohong itu?) maksudnya orang-orang yang menyaksikan peristiwa itu. (Oleh karena mereka tidak mendatangkan saksi-saksi maka mereka itulah pada sisi Allah) menurut hukum-Nya (orang-orang yang dusta) dalam tuduhannya.",[["لَّوْلَا","Why (did) not"],["جَآءُو","they bring"],["عَلَيْهِ","for it"],["بِأَرْبَعَةِ","four"],["شُهَدَآءَ ۚ","witnesses"],["فَإِذْ","Then when"],["لَمْ","not"],["يَأْتُوا۟","they brought"],["بِٱلشُّهَدَآءِ","the witnesses"],["فَأُو۟لَـٰٓئِكَ","then those"],["عِندَ","near Allah"],["ٱللَّهِ","near Allah"],["هُمُ","they"],["ٱلْكَـٰذِبُونَ","(are) the liars"]]],"2805":["(Sekiranya tidak ada karunia Allah dan rahmat-Nya kepada kalian semua di dunia dan di akhirat, niscaya kalian ditimpa, karena pembicaraan kalian) hai golongan yang menuduh (tentang berita bohong itu, azab yang besar) di akhirat kelak.",[["وَلَوْلَا","And if not"],["فَضْلُ","(for the) Grace"],["ٱللَّهِ","(of) Allah"],["عَلَيْكُمْ","upon you"],["وَرَحْمَتُهُۥ","and His Mercy"],["فِى","in"],["ٱلدُّنْيَا","the world"],["وَٱلْـَٔاخِرَةِ","and the Hereafter"],["لَمَسَّكُمْ","surely would have touched you"],["فِى","in"],["مَآ","what"],["أَفَضْتُمْ","you had rushed glibly"],["فِيهِ","concerning it"],["عَذَابٌ","a punishment"],["عَظِيمٌ","great"]]],"2806":["(Di waktu kalian menerima berita bohong itu dari mulut ke mulut) yaitu sebagian di antara kalian menceritakannya kepada sebagian yang lain. Lafal Talaqqaunahu berasal dari lafal Tatalaqqaunahu, kemudian salah satu dari huruf Ta dibuang sehingga jadilah Talaqqaunahu. Lafal Idz tadi dinashabkan oleh lafal Massakum atau oleh lafal Afadhtum (dan kalian katakan dengan mulut kalian apa yang tidak kalian ketahui sedikit jua, dan kalian menganggapnya suatu yang ringan saja) sebagai sesuatu hal yang tidak berdosa. (Padahal dia pada sisi Allah adalah besar) dosanya.",[["إِذْ","When"],["تَلَقَّوْنَهُۥ","you received it"],["بِأَلْسِنَتِكُمْ","with your tongues"],["وَتَقُولُونَ","and you said"],["بِأَفْوَاهِكُم","with your mouths"],["مَّا","what"],["لَيْسَ","not"],["لَكُم","for you"],["بِهِۦ","of it"],["عِلْمٌۭ","any knowledge"],["وَتَحْسَبُونَهُۥ","and you thought it"],["هَيِّنًۭا","(was) insignificant"],["وَهُوَ","while it"],["عِندَ","(was) near Allah"],["ٱللَّهِ","(was) near Allah"],["عَظِيمٌۭ","great"]]],"2807":["(Dan mengapa tidak, sewaktu) ketika (kalian mendengar berita bohong itu, kalian tidak mengatakan, \"Sekali-kali tidaklah pantas) maksudnya tidak layak (bagi kita memperkatakan ini. Maha Suci Engkau) lafal Subhaanaka menunjukkan makna Ta'ajjub (ini adalah dusta) bohong (yang besar.\")",[["وَلَوْلَآ","And why not"],["إِذْ","when"],["سَمِعْتُمُوهُ","you heard it"],["قُلْتُم","you said"],["مَّا","Not"],["يَكُونُ","it is"],["لَنَآ","for us"],["أَن","that"],["نَّتَكَلَّمَ","we speak"],["بِهَـٰذَا","of this"],["سُبْحَـٰنَكَ","Glory be to You"],["هَـٰذَا","This"],["بُهْتَـٰنٌ","(is) a slander"],["عَظِيمٌۭ","great"]]],"2808":["(Allah memperingatkan kalian) yakni melarang kalian (agar jangan kembali memperbuat yang seperti itu selama-lamanya, jika kalian orang-orang yang beriman) yang mau mengambil pelajaran dari hal tersebut.",[["يَعِظُكُمُ","Allah warns you"],["ٱللَّهُ","Allah warns you"],["أَن","that"],["تَعُودُوا۟","you return"],["لِمِثْلِهِۦٓ","(to the) like of it"],["أَبَدًا","ever"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"2809":["(Dan Allah menerangkan ayat-ayat-Nya kepada kalian) mengenai perintah dan larangan. (Dan Allah Maha Mengetahui) tentang apa yang Dia perintahkan dan apa yang Dia larang (lagi Maha Bijaksana) dalam hal ini.",[["وَيُبَيِّنُ","And Allah makes clear"],["ٱللَّهُ","And Allah makes clear"],["لَكُمُ","to you"],["ٱلْـَٔايَـٰتِ ۚ","the Verses"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌ","All-Wise"]]],"2810":["(Sesungguhnya orang-orang yang ingin agar berita perbuatan yang amat keji itu tersiar) dengan melalui mulut mereka (di kalangan orang-orang yang beriman) dengan menisbatkan perbuatan keji itu kepada mereka, yang dimaksud adalah segolongan dari kaum Mukmin (bagi mereka azab yang pedih di dunia) mendapat hukuman hudud menuduh berzina (dan di akhirat) oleh Allah dimasukkan ke dalam neraka. (Dan Allah Maha Mengetahui) ketiadaan perbuatan keji itu dari kalangan mereka (sedangkan kalian) hai golongan orang-orang yang melancarkan berita bohong, terhadap apa yang kalian katakan itu (tidak mengetahui) tentang adanya perbuatan keji di kalangan orang-orang yang beriman.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يُحِبُّونَ","like"],["أَن","that"],["تَشِيعَ","(should) spread"],["ٱلْفَـٰحِشَةُ","the immorality"],["فِى","among"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["لَهُمْ","for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"],["فِى","in"],["ٱلدُّنْيَا","the world"],["وَٱلْـَٔاخِرَةِ ۚ","and the Hereafter"],["وَٱللَّهُ","And Allah"],["يَعْلَمُ","knows"],["وَأَنتُمْ","while you"],["لَا","(do) not"],["تَعْلَمُونَ","know"]]],"2811":["(Dan sekiranya tidaklah karena karunia Allah kepada kalian) hai orang-orang yang menuduh (dan rahmat-Nya, dan Allah Maha Penyantun lagi Maha Penyayang) kepada kalian, niscaya Dia akan menyegerakan hukuman-Nya kepada kalian.",[["وَلَوْلَا","And if not"],["فَضْلُ","(for the) Grace of Allah"],["ٱللَّهِ","(for the) Grace of Allah"],["عَلَيْكُمْ","upon you"],["وَرَحْمَتُهُۥ","and His Mercy"],["وَأَنَّ","And that"],["ٱللَّهَ","Allah"],["رَءُوفٌۭ","(is) Full of Kindness"],["رَّحِيمٌۭ","Most Merciful"]]],"2812":["(Hai orang-orang yang beriman! Janganlah kalian mengikuti langkah-langkah setan) mengikuti godaan-godaannya. (Barang siapa yang mengikuti langkah-langkah setan, sesungguhnya setan itu) yakni yang diikutinya itu (selalu menyuruh mengerjakan perbuatan yang keji) yakni perbuatan yang buruk (dan yang mungkar) menurut syariat, yaitu jika perbuatan itu diikuti (Sekiranya tidaklah karena karunia Allah dan rahmat-Nya kepada kamu sekalian, niscaya tidak seorang pun dari kalian bersih) hai orang-orang yang menuduh, disebabkan berita bohong yang kalian katakan itu (selama-lamanya) tidak akan menjadi baik dan tidak akan menjadi bersih dari dosa ini hanya dengan bertobat daripadanya (tetapi Allah membersihkan) menyucikan (siapa yang dikehendaki-Nya) dari dosa, yaitu dengan menerima tobatnya. (Dan Allah Maha Mendengar) tentang apa yang telah kalian katakan (lagi Maha Mengetahui) tentang apa yang kalian maksud.",[["۞ يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["لَا","(Do) not"],["تَتَّبِعُوا۟","follow"],["خُطُوَٰتِ","(the) footsteps"],["ٱلشَّيْطَـٰنِ ۚ","(of) the Shaitaan"],["وَمَن","and whoever"],["يَتَّبِعْ","follows"],["خُطُوَٰتِ","(the) footsteps"],["ٱلشَّيْطَـٰنِ","(of) the Shaitaan"],["فَإِنَّهُۥ","then indeed, he"],["يَأْمُرُ","commands"],["بِٱلْفَحْشَآءِ","the immorality"],["وَٱلْمُنكَرِ ۚ","and the evil"],["وَلَوْلَا","And if not"],["فَضْلُ","(for the) Grace of Allah"],["ٱللَّهِ","(for the) Grace of Allah"],["عَلَيْكُمْ","upon you"],["وَرَحْمَتُهُۥ","and His Mercy"],["مَا","not"],["زَكَىٰ","(would) have been pure"],["مِنكُم","among you"],["مِّنْ","anyone"],["أَحَدٍ","anyone"],["أَبَدًۭا","ever"],["وَلَـٰكِنَّ","but"],["ٱللَّهَ","Allah"],["يُزَكِّى","purifies"],["مَن","whom"],["يَشَآءُ ۗ","He wills"],["وَٱللَّهُ","And Allah"],["سَمِيعٌ","(is) All-Hearer"],["عَلِيمٌۭ","All-Knower"]]],"2813":["(Dan janganlah bersumpah orang-orang yang mempunyai kelebihan) yaitu orang-orang kaya (dan kelapangan di antara kalian, bahwa mereka) tidak (akan memberi bantuan kepada kaum kerabatnya, orang-orang yang miskin dan orang-orang yang berhijrah pada jalan Allah) ayat ini diturunkan berkenaan dengan sahabat Abu Bakar r. a, ia bersumpah tidak akan memberikan nafkah lagi kepada Misthah saudara sepupunya yang miskin lagi seorang Muhajir, padahal Misthah adalah sahabat yang ikut dalam perang Badar. Misthah terlibat dalam peristiwa berita bohong ini; maka sahabat Abu Bakar menghentikan nafkah yang biasa ia berikan kepadanya. Para sahabat lainnya telah bersumpah pula, bahwa mereka juga tidak akan memberikan nafkah lagi kepada seorang yang terlibat membicarakan masalah berita bohong tersebut (dan hendaklah mereka memaafkan dan berlapang dada) terhadap mereka yang terlibat, dengan mengembalikan keadaan seperti semula. (Apakah kalian tidak ingin bahwa Allah mengampuni kalian? Dan Allah adalah Maha Pengampun lagi Maha Penyayang) terhadap orang-orang yang beriman. Sahabat Abu Bakar r.a. berkata sesudah turunnya ayat ini, \"Tentu saja, aku menginginkan supaya Allah mengampuni aku\", lalu ia memberikan lagi bantuannya kepada Misthah sebagaimana biasanya.",[["وَلَا","And not"],["يَأْتَلِ","let swear"],["أُو۟لُوا۟","those of virtue"],["ٱلْفَضْلِ","those of virtue"],["مِنكُمْ","among you"],["وَٱلسَّعَةِ","and the amplitude of means"],["أَن","that"],["يُؤْتُوٓا۟","they give"],["أُو۟لِى","(to) the near of kin"],["ٱلْقُرْبَىٰ","(to) the near of kin"],["وَٱلْمَسَـٰكِينَ","and the needy"],["وَٱلْمُهَـٰجِرِينَ","and the emigrants"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۖ","(of) Allah"],["وَلْيَعْفُوا۟","And let them pardon"],["وَلْيَصْفَحُوٓا۟ ۗ","and let them overlook"],["أَلَا","(Do) not"],["تُحِبُّونَ","you like"],["أَن","that"],["يَغْفِرَ","Allah should forgive"],["ٱللَّهُ","Allah should forgive"],["لَكُمْ ۗ","you"],["وَٱللَّهُ","And Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌ","Most Merciful"]]],"2814":["(Sesungguhnya orang-orang yang menuduh) berzina (wanita-wanita yang baik-baik) terpelihara kehormatannya (yang lengah) dari perbuatan-perbuatan keji, seumpamanya dalam hati mereka tidak sedikit pun terbetik niat untuk melakukannya (lagi beriman) kepada Allah dan Rasul-Nya (mereka kena laknat di dunia dan akhirat, dan bagi mereka azab yang besar).",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَرْمُونَ","accuse"],["ٱلْمُحْصَنَـٰتِ","the chaste women"],["ٱلْغَـٰفِلَـٰتِ","the unaware women"],["ٱلْمُؤْمِنَـٰتِ","(and) the believing women"],["لُعِنُوا۟","are cursed"],["فِى","in"],["ٱلدُّنْيَا","the world"],["وَٱلْـَٔاخِرَةِ","and the Hereafter"],["وَلَهُمْ","And for them"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"2815":["(Pada hari) yauma dinashabkan oleh lafal Istaqarra yang berta'alluq kepadanya, maksudnya pada hari yang telah ditetapkan bagi mereka (memberi kesaksian) dapat dibaca Tasyhadu dan Yasyhadu (lidah, tangan dan kaki mereka atas mereka terhadap apa yang dahulu mereka kerjakan) berupa perbuatan dan perkataan yang telah mereka kerjakan, yaitu pada hari kiamat.",[["يَوْمَ","(On a) Day"],["تَشْهَدُ","will bear witness"],["عَلَيْهِمْ","against them"],["أَلْسِنَتُهُمْ","their tongues"],["وَأَيْدِيهِمْ","and their hands"],["وَأَرْجُلُهُم","and their feet"],["بِمَا","for what"],["كَانُوا۟","they used"],["يَعْمَلُونَ","(to) do"]]],"2816":["(Di hari itu, Allah akan memberi mereka balasan yang setimpal) Dia akan membalas mereka dengan pembalasan yang semestinya mereka terima (dan tahulah mereka bahwa Allahlah Yang Benar lagi Yang menjelaskan) karena Dia benar-benar membuktikan pembalasan-Nya yang selama ini mereka ragukan kebenarannya; di antara mereka yang mendapat pembalasan adalah Abdullah bin Ubay bin Salul. Yang dimaksud dengan wanita-wanita yang terpelihara kehormatannya adalah istri-istri Nabi saw. Adapun mengenai wanita-wanita yang disebutkan Qadzafnya dalam awal surah At-Taubah, yang dimaksud adalah wanita-wanita selain istri-istri Nabi.",[["يَوْمَئِذٍۢ","That Day"],["يُوَفِّيهِمُ","Allah will pay them in full"],["ٱللَّهُ","Allah will pay them in full"],["دِينَهُمُ","their recompense"],["ٱلْحَقَّ","the due"],["وَيَعْلَمُونَ","and they will know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["هُوَ","He"],["ٱلْحَقُّ","(is) the Truth"],["ٱلْمُبِينُ","the Manifest"]]],"2817":["(Wanita-wanita yang keji) baik perbuatannya maupun perkataannya (adalah untuk laki-laki yang keji) pula (dan laki-laki yang keji) di antara manusia (adalah buat wanita-wanita yang keji pula) sebagaimana yang sebelumnya tadi (dan wanita-wanita yang baik) baik perbuatan maupun perkataannya (adalah untuk laki-laki yang baik) di antara manusia (dan laki-laki yang baik) di antara mereka (adalah untuk wanita-wanita yang baik pula) baik perbuatan maupun perkataannya. Maksudnya, hal yang layak adalah orang yang keji berpasangan dengan orang yang keji, dan orang baik berpasangan dengan orang yang baik. (Mereka itu) yaitu kaum laki-laki yang baik dan kaum wanita yang baik, antara lain ialah Siti Aisyah dan Sofwan (bersih dari apa yang dituduhkan oleh mereka) yang keji dari kalangan kaum laki-laki dan wanita. (Bagi mereka) yakni laki-laki yang baik dan wanita yang baik itu (ampunan dan rezeki yang mulia) di surga. Siti Aisyah merasa puas dan bangga dengan beberapa hal yang ia peroleh, antara lain, ia diciptakan dalam keadaan baik, dan dijanjikan mendapat ampunan dari Allah, serta diberi rezeki yang mulia.",[["ٱلْخَبِيثَـٰتُ","Evil women"],["لِلْخَبِيثِينَ","(are) for evil men"],["وَٱلْخَبِيثُونَ","and evil men"],["لِلْخَبِيثَـٰتِ ۖ","(are) for evil women"],["وَٱلطَّيِّبَـٰتُ","And good women"],["لِلطَّيِّبِينَ","(are) for good men"],["وَٱلطَّيِّبُونَ","and good men"],["لِلطَّيِّبَـٰتِ ۚ","(are) for good women"],["أُو۟لَـٰٓئِكَ","Those"],["مُبَرَّءُونَ","(are) innocent"],["مِمَّا","of what"],["يَقُولُونَ ۖ","they say"],["لَهُم","For them"],["مَّغْفِرَةٌۭ","(is) forgiveness"],["وَرِزْقٌۭ","and a provision"],["كَرِيمٌۭ","noble"]]],"2818":["(Hai orang-orang yang beriman! Janganlah kalian memasuki rumah yang bukan rumah kalian sebelum meminta izin) maksudnya sebelum kalian meminta izin kepada empunya (dan memberi salam kepada penghuninya). Seseorang jika mau memasuki rumah orang lain hendaknya ia mengucapkan, \"Assalaamu Alaikum, bolehkah aku masuk?\" demikianlah menurut tuntunan hadis. (Yang demikian itu lebih baik bagi kalian) daripada masuk tanpa izin (agar kalian selalu ingat) lafal Tadzakkaruuna dengan mengidgamkan huruf Ta kedua kepada huruf Dzal; maksudnya supaya kalian mengerti akan kebaikan meminta izin itu, kemudian kalian mengerjakannya.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تَدْخُلُوا۟","enter"],["بُيُوتًا","houses"],["غَيْرَ","other (than)"],["بُيُوتِكُمْ","your houses"],["حَتَّىٰ","until"],["تَسْتَأْنِسُوا۟","you have asked permission"],["وَتُسَلِّمُوا۟","and you have greeted"],["عَلَىٰٓ","[on]"],["أَهْلِهَا ۚ","its inhabitants"],["ذَٰلِكُمْ","That"],["خَيْرٌۭ","(is) best"],["لَّكُمْ","for you"],["لَعَلَّكُمْ","so that you may"],["تَذَكَّرُونَ","pay heed"]]],"2819":["(Jika kalian tidak menemukan seorang pun di dalamnya) maksudnya orang yang mengizinkan kalian masuk (maka janganlah kalian masuk sebelum kalian mendapat izin. Dan jika dikatakan kepada kalian) sesudah kalian meminta izin (\"Kembalilah\" maka hendaklah kalian kembali. Itu) yakni kembali itu (lebih bersih) dan lebih baik (bagi kalian) daripada berdiam menunggu di pintu (dan Allah terhadap apa yang kalian kerjakan) yakni mengenai memasuki rumah orang lain dengan memakai izin atau tidak (Maha Mengetahui) Dia kelak akan membalasnya kepada kalian.",[["فَإِن","But if"],["لَّمْ","not"],["تَجِدُوا۟","you find"],["فِيهَآ","in it"],["أَحَدًۭا","anyone"],["فَلَا","then (do) not"],["تَدْخُلُوهَا","enter it"],["حَتَّىٰ","until"],["يُؤْذَنَ","permission has been given"],["لَكُمْ ۖ","to you"],["وَإِن","And if"],["قِيلَ","it is said"],["لَكُمُ","to you"],["ٱرْجِعُوا۟","Go back"],["فَٱرْجِعُوا۟ ۖ","then go back"],["هُوَ","it"],["أَزْكَىٰ","(is) purer"],["لَكُمْ ۚ","for you"],["وَٱللَّهُ","And Allah"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["عَلِيمٌۭ","(is) All-Knower"]]],"2820":["(Tidak ada dosa atas kalian memasuki rumah yang tidak disediakan untuk didiami, yang di dalamnya ada keperluan) maksudnya, ada manfaat (bagi kalian) misalnya dijadikannya sebagai tempat tinggal sementara atau untuk keperluan yang lainnya, seperti rumah-rumah asrama dan lain sebagainya (dan Allah mengetahui apa yang kalian nyatakan) yakni semua apa yang kalian lahirkan (dan apa yang kalian sembunyikan) artinya yang kalian rahasiakan sewaktu kalian masuk ke dalam rumah yang bukan rumah kalian, termasuk maksud baik atau maksud-maksud lainnya. Pada pembahasan yang akan datang akan diceritakan, bahwa mereka para sahabat, jika mereka memasuki rumah mereka sendiri, mereka mengucapkan salam kepada diri mereka sendiri.",[["لَّيْسَ","Not"],["عَلَيْكُمْ","upon you"],["جُنَاحٌ","(is) any blame"],["أَن","that"],["تَدْخُلُوا۟","you enter"],["بُيُوتًا","houses"],["غَيْرَ","not"],["مَسْكُونَةٍۢ","inhabited"],["فِيهَا","in it"],["مَتَـٰعٌۭ","(is) a provision"],["لَّكُمْ ۚ","for you"],["وَٱللَّهُ","And Allah"],["يَعْلَمُ","knows"],["مَا","what"],["تُبْدُونَ","you reveal"],["وَمَا","and what"],["تَكْتُمُونَ","you conceal"]]],"2821":["(Katakanlah kepada orang laki-laki yang beriman, \"Hendaklah mereka menahan pandangannya) dari apa-apa yang tidak dihalalkan bagi mereka melihatnya. Huruf Min di sini adalah Zaidah (dan memelihara kemaluannya) daripada hal-hal yang tidak dihalalkan untuknya (yang demikian itu adalah lebih suci) adalah lebih baik (bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat\") melalui penglihatan dan kemaluan mereka, kelak Dia akan membalasnya kepada mereka.",[["قُل","Say"],["لِّلْمُؤْمِنِينَ","to the believing men"],["يَغُضُّوا۟","they should lower"],["مِنْ","their gaze"],["أَبْصَـٰرِهِمْ","their gaze"],["وَيَحْفَظُوا۟","and they should guard"],["فُرُوجَهُمْ ۚ","their chastity"],["ذَٰلِكَ","That"],["أَزْكَىٰ","(is) purer"],["لَهُمْ ۗ","for them"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(is) All-Aware"],["بِمَا","of what"],["يَصْنَعُونَ","they do"]]],"2822":["(Dan katakanlah kepada wanita yang beriman, \"Hendaklah mereka menahan pandangannya) daripada hal-hal yang tidak dihalalkan bagi mereka melihatnya (dan memelihara kemaluannya) dari hal-hal yang tidak dihalalkan untuknya (dan janganlah mereka menampakkan) memperlihatkan (perhiasannya, kecuali yang biasa tampak daripadanya) yaitu wajah dan dua telapak tangannya, maka kedua perhiasannya itu boleh dilihat oleh lelaki lain, jika tidak dikhawatirkan adanya fitnah. Demikianlah menurut pendapat yang membolehkannya. Akan tetapi menurut pendapat yang lain hal itu diharamkan secara mutlak, sebab merupakan sumber terjadinya fitnah. Pendapat yang kedua ini lebih kuat demi untuk menutup pintu fitnah. (Dan hendaklah mereka menutupkan kain kerudung ke dadanya) hendaknya mereka menutupi kepala, leher dan dada mereka dengan kerudung atau jilbabnya (dan janganlah menampakkan perhiasannya) perhiasan yang tersembunyi, yaitu selain dari wajah dan dua telapak tangan (kecuali kepada suami mereka) bentuk jamak dari lafal Ba'lun artinya suami (atau ayah mereka, atau ayah suami mereka, atau putra-putra mereka, atau putra-putra suami mereka, atau saudara-saudara mereka, atau putra-putra saudara-saudara mereka, atau putra-putra saudara-saudara perempuan mereka, atau wanita-wanita Islam atau budak-budak yang mereka miliki) diperbolehkan bagi mereka melihatnya kecuali anggota tubuh antara pusar dan lututnya, anggota tersebut haram untuk dilihat oleh mereka selain dari suaminya sendiri. Dikecualikan dari lafal Nisaaihinna, yaitu perempuan-perempuan yang kafir, bagi wanita Muslimat tidak boleh membuka aurat di hadapan mereka. Termasuk pula ke dalam pengertian Maa Malakat Aymaanuhunna, yaitu hamba sahaya laki-laki miliknya (atau pelayan-pelayan laki-laki) yakni pembantu-pembantu laki-laki (yang tidak) kalau dibaca Ghairi berarti menjadi sifat dan kalau dibaca Ghaira berarti menjadi Istitsna (mempunyai keinginan) terhadap wanita (dari kalangan kaum laki-laki) seumpamanya penis masing-masing tidak dapat bereaksi (atau anak-anak) lafal Ath-Thifl bermakna jamak sekalipun bentuk lafalnya tunggal (yang masih belum mengerti) belum memahami (tentang aurat wanita) belum mengerti persetubuhan, maka kaum wanita boleh menampakkan aurat mereka terhadap orang-orang tersebut selain antara pusar dan lututnya. (Dan janganlah mereka memukulkan kaki mereka agar diketahui perhiasan yang mereka sembunyikan) yaitu berupa gelang kaki, sehingga menimbulkan suara gemerincing. (Dan bertobatlah kamu sekalian kepada Allah, hai orang-orang yang beriman) dari apa yang telah kalian kerjakan, yaitu sehubungan dengan pandangan yang dilarang ini dan hal-hal lainnya yang dilarang (supaya kalian beruntung\") maksudnya selamat dari hal tersebut karena tobat kalian diterima. Pada ayat ini ungkapan Mudzakkar mendominasi atas Muannats.",[["وَقُل","And say"],["لِّلْمُؤْمِنَـٰتِ","to the believing women"],["يَغْضُضْنَ","(that) they should lower"],["مِنْ","[of]"],["أَبْصَـٰرِهِنَّ","their gaze"],["وَيَحْفَظْنَ","and they should guard"],["فُرُوجَهُنَّ","their chastity"],["وَلَا","and not"],["يُبْدِينَ","(to) display"],["زِينَتَهُنَّ","their adornment"],["إِلَّا","except"],["مَا","what"],["ظَهَرَ","is apparent"],["مِنْهَا ۖ","of it"],["وَلْيَضْرِبْنَ","And let them draw"],["بِخُمُرِهِنَّ","their head covers"],["عَلَىٰ","over"],["جُيُوبِهِنَّ ۖ","their bosoms"],["وَلَا","and not"],["يُبْدِينَ","(to) display"],["زِينَتَهُنَّ","their adornment"],["إِلَّا","except"],["لِبُعُولَتِهِنَّ","to their husbands"],["أَوْ","or"],["ءَابَآئِهِنَّ","their fathers"],["أَوْ","or"],["ءَابَآءِ","fathers"],["بُعُولَتِهِنَّ","(of) their husbands"],["أَوْ","or"],["أَبْنَآئِهِنَّ","their sons"],["أَوْ","or"],["أَبْنَآءِ","sons"],["بُعُولَتِهِنَّ","(of) their husbands"],["أَوْ","or"],["إِخْوَٰنِهِنَّ","their brothers"],["أَوْ","or"],["بَنِىٓ","sons"],["إِخْوَٰنِهِنَّ","(of) their brothers"],["أَوْ","or"],["بَنِىٓ","sons"],["أَخَوَٰتِهِنَّ","(of) their sisters"],["أَوْ","or"],["نِسَآئِهِنَّ","their women"],["أَوْ","or"],["مَا","what"],["مَلَكَتْ","possess"],["أَيْمَـٰنُهُنَّ","their right hands"],["أَوِ","or"],["ٱلتَّـٰبِعِينَ","the attendants"],["غَيْرِ","having no physical desire"],["أُو۟لِى","having no physical desire"],["ٱلْإِرْبَةِ","having no physical desire"],["مِنَ","among"],["ٱلرِّجَالِ","[the] men"],["أَوِ","or"],["ٱلطِّفْلِ","[the] children"],["ٱلَّذِينَ","who"],["لَمْ","(are) not"],["يَظْهَرُوا۟","aware"],["عَلَىٰ","of"],["عَوْرَٰتِ","private aspects"],["ٱلنِّسَآءِ ۖ","(of) the women"],["وَلَا","And not"],["يَضْرِبْنَ","let them stamp"],["بِأَرْجُلِهِنَّ","their feet"],["لِيُعْلَمَ","to make known"],["مَا","what"],["يُخْفِينَ","they conceal"],["مِن","of"],["زِينَتِهِنَّ ۚ","their adornment"],["وَتُوبُوٓا۟","And turn"],["إِلَى","to"],["ٱللَّهِ","Allah"],["جَمِيعًا","altogether"],["أَيُّهَ","O believers"],["ٱلْمُؤْمِنُونَ","O believers"],["لَعَلَّكُمْ","So that you may"],["تُفْلِحُونَ","succeed"]]],"2823":["(Dan kawinkanlah orang-orang yang sendirian di antara kalian) lafal Ayaama adalah bentuk jamak dari lafal Ayyimun artinya wanita yang tidak mempunyai suami, baik perawan atau janda, dan laki-laki yang tidak mempunyai istri; hal ini berlaku untuk laki-laki dan perempuan yang merdeka (dan orang-orang yang layak kawin) yakni yang Mukmin (dari hamba-hamba sahaya kalian yang lelaki dan hamba-hamba sahaya kalian yang perempuan) lafal 'ibaadun adalah bentuk jamak dari lafal 'Abdun. (Jika mereka) yakni orang-orang yang merdeka itu (miskin Allah akan memampukan mereka) berkat adanya perkawinan itu (dengan karunia-Nya. Dan Allah Maha Luas) pemberian-Nya kepada makhluk-Nya (lagi Maha Mengetahui) mereka.",[["وَأَنكِحُوا۟","And marry"],["ٱلْأَيَـٰمَىٰ","the single"],["مِنكُمْ","among you"],["وَٱلصَّـٰلِحِينَ","and the righteous"],["مِنْ","among"],["عِبَادِكُمْ","your male slaves"],["وَإِمَآئِكُمْ ۚ","and your female slaves"],["إِن","If"],["يَكُونُوا۟","they are"],["فُقَرَآءَ","poor"],["يُغْنِهِمُ","Allah will enrich them"],["ٱللَّهُ","Allah will enrich them"],["مِن","from"],["فَضْلِهِۦ ۗ","His Bounty"],["وَٱللَّهُ","And Allah"],["وَٰسِعٌ","(is) All-Encompassing"],["عَلِيمٌۭ","All-Knowing"]]],"2824":["(Dan orang-orang yang tidak mampu kawin hendaklah menjaga kesuciannya) maksudnya mereka yang tidak mempunyai mahar dan nafkah untuk kawin, hendaklah mereka memelihara kesuciannya dari perbuatan zina (sehingga Allah memampukan mereka) memberikan kemudahan kepada mereka (dengan karunia-Nya) hingga mereka mampu kawin. (Dan orang-orang yang menginginkan perjanjian) lafal Al Kitaaba bermakna Al Mukaatabah, yaitu perjanjian untuk memerdekakan diri (di antara budak-budak yang kalian miliki) baik hamba sahaya laki-laki maupun perempuan (maka hendaklah kalian buat perjanjian dengan mereka jika kalian mengetahui ada kebaikan pada mereka) artinya dapat dipercaya dan memiliki kemampuan untuk berusaha yang hasilnya kelak dapat membayar perjanjian kemerdekaan dirinya. Shighat atau teks perjanjian ini, misalnya seorang pemilik budak berkata kepada budaknya, \"Aku memukatabahkan kamu dengan imbalan dua ribu dirham, selama jangka waktu dua bulan. Jika kamu mampu membayarnya, berarti kamu menjadi orang yang merdeka.\" Kemudian budak yang bersangkutan menjawab, \"Saya menyanggupi dan mau menerimanya\" (dan berikanlah kepada mereka) perintah di sini ditujukan kepada para pemilik budak (sebagian dari harta Allah yang dikaruniakan-Nya kepada kalian) berupa apa-apa yang dapat membantu mereka untuk menunaikan apa yang mereka harus bayarkan kepada kalian. Di dalam lafal Al-Iitaa terkandung pengertian meringankan sebagian dari apa yang harus mereka bayarkan kepada kalian, yaitu dengan menganggapnya lunas. (Dan janganlah kalian paksakan budak-budak wanita kalian) yaitu sahaya wanita milik kalian (untuk melakukan pelacuran) berbuat zina (sedangkan mereka sendiri menginginkan kesucian) memelihara kehormatannya dari perbuatan zina. Adanya keinginan untuk memelihara kehormatan inilah yang menyebabkan dilarang memaksa, sedangkan syarath di sini tidak berfungsi sebagaimana mestinya lagi (karena kalian hendak mencari) melalui paksaan itu (keuntungan duniawi) ayat ini diturunkan berkenaan dengan Abdullah bin Ubay, karena dia memaksakan hamba-hamba sahaya perempuannya untuk berpraktek sebagai pelacur demi mencari keuntungan bagi dirinya. (Dan barang siapa memaksa mereka, maka sesungguhnya Allah kepada mereka yang telah dipaksa itu adalah Maha Pengampun) (lagi Maha Penyayang).",[["وَلْيَسْتَعْفِفِ","And let be chaste"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَجِدُونَ","find"],["نِكَاحًا","(means for) marriage"],["حَتَّىٰ","until"],["يُغْنِيَهُمُ","Allah enriches them"],["ٱللَّهُ","Allah enriches them"],["مِن","from"],["فَضْلِهِۦ ۗ","His Bounty"],["وَٱلَّذِينَ","And those who"],["يَبْتَغُونَ","seek"],["ٱلْكِتَـٰبَ","the writing"],["مِمَّا","from (those) whom"],["مَلَكَتْ","possess"],["أَيْمَـٰنُكُمْ","your right hands"],["فَكَاتِبُوهُمْ","then give them (the) writing"],["إِنْ","if"],["عَلِمْتُمْ","you know"],["فِيهِمْ","in them"],["خَيْرًۭا ۖ","any good"],["وَءَاتُوهُم","and give them"],["مِّن","from"],["مَّالِ","the wealth of Allah"],["ٱللَّهِ","the wealth of Allah"],["ٱلَّذِىٓ","which"],["ءَاتَىٰكُمْ ۚ","He has given you"],["وَلَا","And (do) not"],["تُكْرِهُوا۟","compel"],["فَتَيَـٰتِكُمْ","your slave girls"],["عَلَى","to"],["ٱلْبِغَآءِ","[the] prostitution"],["إِنْ","if"],["أَرَدْنَ","they desire"],["تَحَصُّنًۭا","chastity"],["لِّتَبْتَغُوا۟","that you may seek"],["عَرَضَ","temporary gain"],["ٱلْحَيَوٰةِ","(of) the life"],["ٱلدُّنْيَا ۚ","(of) the world"],["وَمَن","And whoever"],["يُكْرِههُّنَّ","compels them"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["مِنۢ","after"],["بَعْدِ","after"],["إِكْرَٰهِهِنَّ","their compulsion"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"2825":["(Dan sesungguhnya Kami telah menurunkan kepada kalian ayat-ayat yang memberi penerangan) dapat dibaca Mubayyanatin dan Mubayyinatin. Artinya, telah dijelaskan di dalamnya hal-hal yang telah disebutkan tadi (dan contoh-contoh) yakni berita yang aneh, yaitu berita tentang Siti Aisyah (dari orang-orang yang terdahulu sebelum kalian) maksudnya sama jenisnya dengan berita-berita mereka dalam hal keanehannya, seperti kisah mengenai Nabi Yusuf dan Siti Maryam (dan pelajaran bagi orang-orang yang bertakwa) yaitu dalam firman-Nya, \"Dan janganlah belas kasihan kalian kepada keduanya mencegah kalian untuk menjalankan agama (hukum) Allah.\" (Q.S. An-Nur, 2) dan firman-Nya, \"Mengapa di waktu kalian mendengar berita bohong itu orang-orang Mukmin dan Mukminat tidak berprasangka baik\". (Q.S. An-Nur, 12). Dan firman-Nya, \"Dan mengapa kalian tidak berkata di waktu mendengar berita bohong itu...\" (Q.S. An-Nur, 16). Dan firman-Nya, \"Allah memperingatkan kalian agar jangan kembali memperbuat yang seperti itu...\" (Q.S. An-Nur, 17). Dalam ayat ini orang-orang yang bertakwa disebutkan secara khusus mengingat hanya merekalah yang dapat mengambil manfaat dari pelajaran yang terkandung di dalamnya.",[["وَلَقَدْ","And verily"],["أَنزَلْنَآ","We have sent down"],["إِلَيْكُمْ","to you"],["ءَايَـٰتٍۢ","Verses"],["مُّبَيِّنَـٰتٍۢ","clear"],["وَمَثَلًۭا","and an example"],["مِّنَ","of"],["ٱلَّذِينَ","those who"],["خَلَوْا۟","passed away"],["مِن","before you"],["قَبْلِكُمْ","before you"],["وَمَوْعِظَةًۭ","and an admonition"],["لِّلْمُتَّقِينَ","for those who fear (Allah)"]]],"2826":["(Allah cahaya langit dan bumi) yakni pemberi cahaya langit dan bumi dengan matahari dan bulan. (Perumpamaan cahaya Allah) sifat cahaya Allah di dalam kalbu orang Mukmin (adalah seperti misykat yang di dalamnya ada pelita besar. Pelita itu di dalam kaca) yang dinamakan lampu lentera atau Qandil. Yang dimaksud Al Mishbah adalah lampu atau sumbu yang dinyalakan. Sedangkan Al Misykaat artinya sebuah lubang yang tidak tembus. Sedangkan pengertian pelita di dalam kaca, maksudnya lampu tersebut berada di dalamnya (kaca itu seakan-akan) cahaya yang terpancar darinya (bintang yang bercahaya seperti mutiara) kalau dibaca Diriyyun atau Duriyyun berarti berasal dari kata Ad Dar'u yang artinya menolak atau menyingkirkan, dikatakan demikian karena dapat mengusir kegelapan, maksudnya bercahaya. Jika dibaca Durriyyun dengan mentasydidkan huruf Ra, berarti mutiara, maksudnya cahayanya seperti mutiara (yang dinyalakan) kalau dibaca Tawaqqada dalam bentuk Fi'il Madhi, artinya lampu itu menyala. Menurut suatu qiraat dibaca dalam bentuk Fi'il Mudhari' yaitu Tuuqidu, menurut qiraat lainnya dibaca Yuuqadu, dan menurut qiraat yang lainnya lagi dapat dibaca Tuuqadu, artinya kaca itu seolah-olah dinyalakan (dengan) minyak (dari pohon yang banyak berkahnya, yaitu pohon zaitun yang tumbuh tidak di sebelah Timur dan pula tidak di sebelah Barat) akan tetapi tumbuh di antara keduanya, sehingga tidak terkena panas atau dingin yang dapat merusaknya (yang minyaknya saja hampir-hampir menerangi, walaupun tidak disentuh api) mengingat jernihnya minyak itu. (Cahaya) yang disebabkannya (di atas cahaya) api dari pelita itu. Makna yang dimaksud dengan cahaya Allah adalah petunjuk-Nya kepada orang Mukmin, maksudnya hal itu adalah cahaya di atas cahaya iman (Allah membimbing kepada cahaya-Nya) yaitu kepada agama Islam (siapa yang Dia kehendaki, dan Allah memperbuat) yakni menjelaskan (perumpamaan-perumpamaan bagi manusia) supaya dapat dicerna oleh pemahaman mereka, kemudian supaya mereka mengambil pelajaran daripadanya, sehingga mereka mau beriman (dan Allah Maha Mengetahui segala sesuatu) antara lain ialah membuat perumpamaan-perumpamaan ini.",[["۞ ٱللَّهُ","Allah"],["نُورُ","(is the) Light"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["مَثَلُ","(The) example"],["نُورِهِۦ","(of) His Light"],["كَمِشْكَوٰةٍۢ","(is) like a niche"],["فِيهَا","in it"],["مِصْبَاحٌ ۖ","(is) a lamp"],["ٱلْمِصْبَاحُ","the lamp"],["فِى","(is) in"],["زُجَاجَةٍ ۖ","a glass"],["ٱلزُّجَاجَةُ","the glass"],["كَأَنَّهَا","as if it were"],["كَوْكَبٌۭ","a star"],["دُرِّىٌّۭ","brilliant"],["يُوقَدُ","(which) is lit"],["مِن","from"],["شَجَرَةٍۢ","a tree"],["مُّبَـٰرَكَةٍۢ","blessed "],["زَيْتُونَةٍۢ","an olive"],["لَّا","not"],["شَرْقِيَّةٍۢ","(of the) east"],["وَلَا","and not"],["غَرْبِيَّةٍۢ","(of the) west"],["يَكَادُ","would almost"],["زَيْتُهَا","its oil"],["يُضِىٓءُ","glow"],["وَلَوْ","even if"],["لَمْ","not"],["تَمْسَسْهُ","touched it"],["نَارٌۭ ۚ","fire"],["نُّورٌ","Light"],["عَلَىٰ","upon"],["نُورٍۢ ۗ","Light"],["يَهْدِى","Allah guides"],["ٱللَّهُ","Allah guides"],["لِنُورِهِۦ","to His Light"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَيَضْرِبُ","And Allah sets forth"],["ٱللَّهُ","And Allah sets forth"],["ٱلْأَمْثَـٰلَ","the examples"],["لِلنَّاسِ ۗ","for the mankind"],["وَٱللَّهُ","And Allah"],["بِكُلِّ","of every"],["شَىْءٍ","thing"],["عَلِيمٌۭ","(is) All-Knower"]]],"2827":["(Di rumah-rumah Allah) maksudnya mesjid-mesjid, lafal Fii Buyuutin berta'alluq kepada lafal Yusabbihu yang akan disebutkan nanti. (Yang Allah telah memerintahkan supaya dimuliakan) yakni diagungkan (dan disebut nama-Nya di dalamnya) dengan mentauhidkan-Nya (bertasbihlah) dapat dibaca Yusabbahu artinya dibacakan tasbih dalam salat. Dapat pula dibaca Yusabbihu, artinya membaca tasbih dalam salat (kepada Allah di dalamnya, pada waktu pagi) lafal Al-Ghuduwwi adalah Mashdar yang maknanya Al-Ghadwaati, artinya pagi hari (dan waktu petang) waktu sore sesudah matahari tergelincir.",[["فِى","In"],["بُيُوتٍ","houses"],["أَذِنَ","(which) Allah ordered"],["ٱللَّهُ","(which) Allah ordered"],["أَن","that"],["تُرْفَعَ","they be raised"],["وَيُذْكَرَ","and be mentioned"],["فِيهَا","in them"],["ٱسْمُهُۥ","His name"],["يُسَبِّحُ","Glorify"],["لَهُۥ","[to] Him"],["فِيهَا","in them"],["بِٱلْغُدُوِّ","in the mornings"],["وَٱلْـَٔاصَالِ","and (in) the evenings"]]],"2828":["(Laki-laki) menjadi Fa'il atau subyek daripada Fi'il Yusabbihu, jika dibaca Yusabbahu berkedudukan menjadi Naibul Fa'il. Lafal Rijaalun adalah Fa'il dari Fi'il atau kata kerja yang diperkirakan keberadaannya sebagai jawab dari soal yang diperkirakan pula. Jadi seolah-olah dikatakan, siapakah yang melakukan tasbih kepada-Nya itu, jawabnya adalah laki-laki (yang tidak dilalaikan oleh perniagaan) perdagangan (dan tidak pula oleh jual beli dari mengingat Allah dan dari mendirikan salat) huruf Ha lafal Iqaamatish Shalaati dibuang demi untuk meringankan bacaan sehingga jadilah Iqaamish Shalaati (dan dari membayar zakat. Mereka takut kepada suatu hari yang di hari itu menjadi guncang) yakni panik (hati dan penglihatan) karena merasa khawatir, apakah dirinya selamat atau binasa, dan penglihatan jelalatan ke kanan dan ke kiri karena ngeri melihat pemandangan azab pada saat itu, yaitu hari kiamat.",[["رِجَالٌۭ","Men "],["لَّا","not"],["تُلْهِيهِمْ","distracts them"],["تِجَـٰرَةٌۭ","trade"],["وَلَا","and not"],["بَيْعٌ","sale"],["عَن","from"],["ذِكْرِ","(the) remembrance of Allah"],["ٱللَّهِ","(the) remembrance of Allah"],["وَإِقَامِ","and (from) establishing"],["ٱلصَّلَوٰةِ","the prayer"],["وَإِيتَآءِ","and giving"],["ٱلزَّكَوٰةِ ۙ","zakah"],["يَخَافُونَ","They fear"],["يَوْمًۭا","a Day"],["تَتَقَلَّبُ","will turn about"],["فِيهِ","therein"],["ٱلْقُلُوبُ","the hearts"],["وَٱلْأَبْصَـٰرُ","and the eyes"]]],"2829":["(Dengan harapan supaya Allah memberi balasan kepada mereka dengan balasan yang lebih baik dari apa yang telah mereka kerjakan) maksudnya pahala yang baik, karena lafal Ahsan bermakna Hasan (dan supaya Allah menambah karunia-Nya kepada mereka. Dan Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa batas) jika dikatakan, Fulaanun Yunfiqu Bighairi Hisabin, maka artinya, dia membelanjakan harta tanpa perhitungan lagi.",[["لِيَجْزِيَهُمُ","That Allah may reward them"],["ٱللَّهُ","That Allah may reward them"],["أَحْسَنَ","(with the) best"],["مَا","(of) what"],["عَمِلُوا۟","they did"],["وَيَزِيدَهُم","and increase them"],["مِّن","from"],["فَضْلِهِۦ ۗ","His Bounty"],["وَٱللَّهُ","And Allah"],["يَرْزُقُ","provides"],["مَن","whom"],["يَشَآءُ","He wills"],["بِغَيْرِ","without"],["حِسَابٍۢ","measure"]]],"2830":["(Dan orang-orang yang kafir amal-amal mereka adalah laksana fatamorgana di tanah yang datar) lafal Qii'ah adalah bentuk jamak dari lafal Qaa'un, yakni padang sahara yang datar. Yang dimaksud dengan lafal Saraabun adalah pemandangan yang tampak di kala matahari sedang terik-teriknya yang rupanya mirip seperti air yang mengalir, atau lazim disebut fatamorgana (ia disangka) diduga (oleh orang yang kehausan) yaitu orang yang dahaga (air, tetapi bila didatanginya air itu dia tidak mendapatinya sesuatu apa pun) apa yang disangkanya itu, demikian pula halnya orang kafir, ia menduga bahwa amal kebaikannya seperti sedekah, yang ia sangka bermanfaat bagi dirinya, tetapi bila ia mati kemudian ia menghadap kepada Rabbnya, maka ia tidak mendapati amal kebaikannya itu. Atau dengan kata lain amalnya itu tidak memberi manfaat kepada dirinya. (Dan ia mendapatkan Allah di sisinya) yakni di sisi amalnya (lalu Allah memberikan kepadanya perhitungan amal-amal dengan cukup) Allah memberikan balasan amal perbuatannya itu hanya di dunia (dan Allah adalah sangat cepat perhitungan-Nya) di dalam memberikan balasan-Nya.",[["وَٱلَّذِينَ","But those who"],["كَفَرُوٓا۟","disbelieve"],["أَعْمَـٰلُهُمْ","their deeds"],["كَسَرَابٍۭ","(are) like a mirage"],["بِقِيعَةٍۢ","in a lowland"],["يَحْسَبُهُ","thinks it"],["ٱلظَّمْـَٔانُ","the thirsty one"],["مَآءً","(to be) water"],["حَتَّىٰٓ","until"],["إِذَا","when"],["جَآءَهُۥ","he comes to it"],["لَمْ","not"],["يَجِدْهُ","he finds it"],["شَيْـًۭٔا","(to be) anything"],["وَوَجَدَ","but he finds"],["ٱللَّهَ","Allah"],["عِندَهُۥ","before him"],["فَوَفَّىٰهُ","He will pay him in full"],["حِسَابَهُۥ ۗ","his due"],["وَٱللَّهُ","And Allah"],["سَرِيعُ","(is) swift"],["ٱلْحِسَابِ","(in) the account"]]],"2831":["(Atau) amal perbuatan orang-orang kafir yang buruk (seperti gelap-gulita di lautan yang dalam) yakni laut yang amat dalam (yang diliputi oleh ombak di atasnya) di atas ombak itu (ada ombak pula, di atasnya lagi) maksudnya di atas ombak yang kedua itu (awan) yang mendung dan gelap; ini adalah (gelap-gulita yang tindih-menindih) yakni gelapnya laut, gelapnya ombak yang pertama, gelapnya ombak yang kedua, dan gelapnya mendung (apabila dia mengeluarkan) yakni orang yang melihatnya (tangannya) di dalam gelap-gulita yang sangat ini (tiadalah dia dapat melihatnya) artinya hampir saja ia tidak dapat melihat tangannya sendiri (dan barang siapa yang tiada diberi cahaya oleh Allah tiadalah dia mempunyai cahaya sedikit pun) maksudnya barang siapa yang tidak diberi petunjuk oleh Allah, niscaya ia tidak akan mendapatkan petunjuk.",[["أَوْ","Or"],["كَظُلُمَـٰتٍۢ","(is) like (the) darkness[es]"],["فِى","in"],["بَحْرٍۢ","a sea"],["لُّجِّىٍّۢ","deep"],["يَغْشَىٰهُ","covers it"],["مَوْجٌۭ","a wave"],["مِّن","on it"],["فَوْقِهِۦ","on it"],["مَوْجٌۭ","a wave"],["مِّن","on it"],["فَوْقِهِۦ","on it"],["سَحَابٌۭ ۚ","a cloud"],["ظُلُمَـٰتٌۢ","darkness[es]"],["بَعْضُهَا","some of it"],["فَوْقَ","on"],["بَعْضٍ","others"],["إِذَآ","When"],["أَخْرَجَ","he puts out"],["يَدَهُۥ","his hand"],["لَمْ","hardly"],["يَكَدْ","hardly"],["يَرَىٰهَا ۗ","he (can) see it"],["وَمَن","And (for) whom"],["لَّمْ","not"],["يَجْعَلِ","Allah (has) made"],["ٱللَّهُ","Allah (has) made"],["لَهُۥ","for him"],["نُورًۭا","a light"],["فَمَا","then not"],["لَهُۥ","for him"],["مِن","(is) any"],["نُّورٍ","light"]]],"2832":["(Tidakkah kamu melihat, bahwasanya Allah kepada-Nya bertasbih apa yang di langit dan di bumi) dan termasuk ke dalam pengertian bertasbih adalah salat (dan juga burung-burung) lafal Thair adalah bentuk jamak dari lafal Ath Thaair, yakni makhluk yang terbang antara bumi dan langit (dengan mengembangkan sayapnya) lafal Shaaffaatin adalah Hal atau kata keterangan keadaan dari burung-burung tadi, yaitu burung-burung itu membaca tasbih dengan mengembangkan sayapnya. (Masing-masingnya telah diketahui) oleh Allah (cara salat dan bertasbihnya, dan Allah Maha Mengetahui apa yang mereka kerjakan). Di dalam ungkapan ini, semuanya dianggap sebagai makhluk yang berakal.",[["أَلَمْ","Do not"],["تَرَ","you see"],["أَنَّ","that"],["ٱللَّهَ","Allah "],["يُسَبِّحُ","glorify"],["لَهُۥ","Him"],["مَن","whoever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَٱلطَّيْرُ","and the birds"],["صَـٰٓفَّـٰتٍۢ ۖ","(with) wings outspread"],["كُلٌّۭ","Each one"],["قَدْ","verily"],["عَلِمَ","knows"],["صَلَاتَهُۥ","its prayer"],["وَتَسْبِيحَهُۥ ۗ","and its glorification"],["وَٱللَّهُ","And Allah"],["عَلِيمٌۢ","(is) All-Knower"],["بِمَا","of what"],["يَفْعَلُونَ","they do"]]],"2833":["(Dan kepunyaan Allahlah kerajaan langit dan bumi) maksudnya perbendaharaan-perbendaharaan hujan, rezeki dan tumbuh-tumbuhan (dan kepada Allahlah kembali) semua makhluk.",[["وَلِلَّهِ","And to Allah (belongs)"],["مُلْكُ","(the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۖ","and the earth"],["وَإِلَى","And to"],["ٱللَّهِ","Allah"],["ٱلْمَصِيرُ","(is) the destination"]]],"2834":["(Tidaklah kamu melihat bahwa Allah mengarak awan) menggiringnya secara lembut (kemudian mengumpulkan antara bagian-bagiannya) dengan menghimpun sebagiannya dengan sebagian yang lain, sehingga yang tadinya tersebar kini menjadi satu kumpulan (kemudian menjadikannya bertindih-tindih) yakni sebagiannya di atas sebagian yang lain (maka kelihatanlah olehmu air) hujan (keluar dari celah-celahnya) yakni melalui celah-celahnya (dan Allah juga menurunkan dari langit). Huruf Min yang kedua ini berfungsi menjadi Shilah atau kata penghubung (yakni dari gunung-gunung yang menjulang padanya) menjulang ke langit; Min Jibaalin menjadi Badal daripada lafal Minas Samaa-i dengan mengulangi huruf Jarrnya (berupa es) sebagiannya terdiri dari es (maka ditimpakannya es tersebut kepada siapa yang dikehendaki-Nya dan dipalingkan-Nya dari siapa yang dikehendaki-Nya. Hampir-hampir) hampir saja (kilauan kilat awan itu) yakni cahayanya yang berkilauan (menghilangkan penglihatan) mata yang memandangnya, karena silau olehnya.",[["أَلَمْ","Do not"],["تَرَ","you see"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["يُزْجِى","drives"],["سَحَابًۭا","clouds"],["ثُمَّ","then"],["يُؤَلِّفُ","joins"],["بَيْنَهُۥ","between them"],["ثُمَّ","then"],["يَجْعَلُهُۥ","makes them"],["رُكَامًۭا","(into) a mass"],["فَتَرَى","then you see"],["ٱلْوَدْقَ","the rain"],["يَخْرُجُ","come forth"],["مِنْ","from"],["خِلَـٰلِهِۦ","their midst"],["وَيُنَزِّلُ","And He sends down"],["مِنَ","from"],["ٱلسَّمَآءِ","(the) sky"],["مِن","[from]"],["جِبَالٍۢ","mountains"],["فِيهَا","within it"],["مِنۢ","[of]"],["بَرَدٍۢ","(is) hail"],["فَيُصِيبُ","and He strikes"],["بِهِۦ","with it"],["مَن","whom"],["يَشَآءُ","He wills"],["وَيَصْرِفُهُۥ","and averts it"],["عَن","from"],["مَّن","whom"],["يَشَآءُ ۖ","He wills"],["يَكَادُ","Nearly"],["سَنَا","(the) flash"],["بَرْقِهِۦ","(of) its lighting"],["يَذْهَبُ","takes away"],["بِٱلْأَبْصَـٰرِ","the sight"]]],"2835":["(Allah mempergantikan malam dan siang) mendatangkan masing-masingnya sebagai pengganti dari yang lain. (sesungguhnya pada yang demikian itu) yakni pergantian ini (terdapat pelajaran) yang menunjukkan kebesaran-Nya (bagi orang-orang yang mempunyai penglihatan) bagi mereka yang memiliki penglihatan memandang kekuasaan Allah swt.",[["يُقَلِّبُ","Allah alternates"],["ٱللَّهُ","Allah alternates"],["ٱلَّيْلَ","the night"],["وَٱلنَّهَارَ ۚ","and the day"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَعِبْرَةًۭ","surely is a lesson"],["لِّأُو۟لِى","for those who have vision"],["ٱلْأَبْصَـٰرِ","for those who have vision"]]],"2836":["(Dan Allah telah menciptakan semua jenis hewan) maksudnya makhluk hidup (dari air) yakni air mani (maka sebagian dari hewan itu ada yang berjalan di atas perutnya) seperti ulat dan binatang melata lainnya (dan sebagian berjalan dengan dua kaki) seperti manusia dan burung (sedangkan sebagian yang lain berjalan dengan empat kaki) seperti hewan liar dan hewan ternak. (Allah menciptakan apa yang dikehendaki-Nya, sesungguhnya Allah Maha Kuasa atas segala sesuatu).",[["وَٱللَّهُ","And Allah"],["خَلَقَ","created"],["كُلَّ","every"],["دَآبَّةٍۢ","moving creature"],["مِّن","from"],["مَّآءٍۢ ۖ","water"],["فَمِنْهُم","Of them"],["مَّن","(is a kind) who"],["يَمْشِى","walks"],["عَلَىٰ","on"],["بَطْنِهِۦ","its belly"],["وَمِنْهُم","and of them"],["مَّن","(is a kind) who"],["يَمْشِى","walks"],["عَلَىٰ","on"],["رِجْلَيْنِ","two legs"],["وَمِنْهُم","and of them"],["مَّن","(is a kind) who"],["يَمْشِى","walks"],["عَلَىٰٓ","on"],["أَرْبَعٍۢ ۚ","four"],["يَخْلُقُ","Allah creates"],["ٱللَّهُ","Allah creates"],["مَا","what"],["يَشَآءُ ۚ","He wills"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلَىٰ","on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","(is) All-Powerful"]]],"2837":["(Sesungguhnya Kami telah menurunkan ayat-ayat yang menjelaskan) yaitu Alquran. (Dan Allah memimpin siapa yang dikehendaki-Nya kepada jalan) yakni tuntunan (yang lurus) yaitu agama Islam.",[["لَّقَدْ","Verily"],["أَنزَلْنَآ","We have sent down"],["ءَايَـٰتٍۢ","Verses"],["مُّبَيِّنَـٰتٍۢ ۚ","clear"],["وَٱللَّهُ","And Allah"],["يَهْدِى","guides"],["مَن","whom"],["يَشَآءُ","He wills"],["إِلَىٰ","to"],["صِرَٰطٍۢ","a path"],["مُّسْتَقِيمٍۢ","straight"]]],"2838":["(Dan mereka berkata) maksudnya orang-orang munafik, (\"Kami telah beriman) Kami telah percaya (kepada Allah) dengan mengesakan-Nya (dan Rasul) yaitu Nabi Muhammad (dan Kami menaati\") apa yang telah ditetapkan oleh Allah dan Rasul-Nya. (Kemudian berpalinglah) memalingkan diri (sebagian dari mereka sesudah itu) dari apa yang telah ditetapkan oleh Allah dan Rasul-Nya (sekali-kali mereka itu bukanlah) orang-orang yang berpaling itu (orang-orang yang beriman) sejati, yang hati dan lisan mereka bersesuaian.",[["وَيَقُولُونَ","And they say"],["ءَامَنَّا","We believe"],["بِٱللَّهِ","in Allah"],["وَبِٱلرَّسُولِ","and in the Messenger"],["وَأَطَعْنَا","and we obey"],["ثُمَّ","Then"],["يَتَوَلَّىٰ","turns away"],["فَرِيقٌۭ","a party"],["مِّنْهُم","of them"],["مِّنۢ","after"],["بَعْدِ","after"],["ذَٰلِكَ ۚ","that"],["وَمَآ","And not"],["أُو۟لَـٰٓئِكَ","those"],["بِٱلْمُؤْمِنِينَ","(are) believers"]]],"2839":["(Dan apabila mereka dipanggil kepada Allah dan Rasul-Nya) yang menyampaikan kepada mereka (agar Rasul menghukum/mengadili di antara mereka, tiba-tiba sebagian dari mereka berpaling) menolak untuk datang memenuhi seruan Rasul.",[["وَإِذَا","And when"],["دُعُوٓا۟","they are called"],["إِلَى","to"],["ٱللَّهِ","Allah"],["وَرَسُولِهِۦ","and His Messenger"],["لِيَحْكُمَ","to judge"],["بَيْنَهُمْ","between them"],["إِذَا","behold"],["فَرِيقٌۭ","a party"],["مِّنْهُم","of them"],["مُّعْرِضُونَ","(is) averse"]]],"2840":["(Tetapi jika keputusan itu untuk kemaslahatan mereka, mereka mau datang kepada Rasul dengan patuh) dengan segera dan penuh ketaatan.",[["وَإِن","But if"],["يَكُن","is"],["لَّهُمُ","with them"],["ٱلْحَقُّ","the truth"],["يَأْتُوٓا۟","they come"],["إِلَيْهِ","to him"],["مُذْعِنِينَ","(as) promptly obedient"]]],"2841":["(Apakah di dalam hati mereka ada penyakit) yakni kekafiran (atau karena mereka ragu-ragu) mereka meragukan kenabiannya (ataukah karena mereka takut kalau-kalau Allah dan Rasul-Nya berlaku zalim kepada mereka?) di dalam peradilan, yakni mereka diperlakukan secara aniaya di dalamnya. Tidak (sebenarnya, mereka itulah orang-orang yang zalim) karena mereka berpaling dari peradilan itu.",[["أَفِى","Is (there) in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌ","a disease"],["أَمِ","or"],["ٱرْتَابُوٓا۟","do they doubt"],["أَمْ","or"],["يَخَافُونَ","they fear"],["أَن","that"],["يَحِيفَ","Allah will be unjust"],["ٱللَّهُ","Allah will be unjust"],["عَلَيْهِمْ","to them"],["وَرَسُولُهُۥ ۚ","and His Messenger"],["بَلْ","Nay"],["أُو۟لَـٰٓئِكَ","those"],["هُمُ","[they]"],["ٱلظَّـٰلِمُونَ","(are) the wrongdoers"]]],"2842":["(Sesungguhnya jawaban orang-orang Mukmin, bila mereka dipanggil kepada Allah dan Rasul-Nya agar Rasul mengadili di antara mereka) maka jawaban yang pantas mereka katakan (ialah ucapan, \"Kami mendengar dan Kami patuh\") yakni mengiakan secara spontan. (Dan mereka) sejak saat itu (adalah orang-orang yang beruntung) artinya orang-orang yang selamat di dunia dan akhirat.",[["إِنَّمَا","Only"],["كَانَ","is"],["قَوْلَ","(the) statement"],["ٱلْمُؤْمِنِينَ","(of) the believers"],["إِذَا","when"],["دُعُوٓا۟","they are called"],["إِلَى","to"],["ٱللَّهِ","Allah"],["وَرَسُولِهِۦ","and His Messenger"],["لِيَحْكُمَ","to judge"],["بَيْنَهُمْ","between them"],["أَن","(is) that"],["يَقُولُوا۟","they say"],["سَمِعْنَا","We hear"],["وَأَطَعْنَا ۚ","and we obey"],["وَأُو۟لَـٰٓئِكَ","And those"],["هُمُ","[they]"],["ٱلْمُفْلِحُونَ","(are) the successful"]]],"2843":["(Dan barang siapa yang taat kepada Allah dan Rasul-Nya dan takut kepada Allah) merasa takut kepada-Nya (dan bertakwa kepada-Nya) dapat dibaca Wayattaqih dan Wayattaqhi, yakni dengan menaati-Nya (maka mereka adalah orang-orang yang mendapat kemenangan) yaitu mendapat surga.",[["وَمَن","And whoever"],["يُطِعِ","obeys"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["وَيَخْشَ","and fears"],["ٱللَّهَ","Allah"],["وَيَتَّقْهِ","and (is) conscious of Him"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْفَآئِزُونَ","(are) the successful ones"]]],"2844":["(Dan mereka bersumpah dengan nama Allah sekuat-kuat sumpah) dengan sekuatnya (jika kalian suruh mereka) untuk pergi berjihad (pastilah mereka akan pergi. Katakanlah!) kepada mereka (\"Janganlah kalian bersumpah, karena ketaatan yang diminta ialah ketaatan yang sebenarnya) maksudnya taat yang sebenarnya kepada Nabi adalah lebih baik daripada sumpah kalian yang tidak kalian tunaikan. (Sesungguhnya Allah Maha Mengetahui apa yang kalian kerjakan\") berupa ketaatan kalian secara lisan, padahal kalian bertentangan dalam prakteknya.",[["۞ وَأَقْسَمُوا۟","And they swear"],["بِٱللَّهِ","by Allah"],["جَهْدَ","strong"],["أَيْمَـٰنِهِمْ","their oaths"],["لَئِنْ","that if"],["أَمَرْتَهُمْ","you ordered them"],["لَيَخْرُجُنَّ ۖ","surely they (would) go forth"],["قُل","Say"],["لَّا","(Do) not"],["تُقْسِمُوا۟ ۖ","swear"],["طَاعَةٌۭ","Obedience"],["مَّعْرُوفَةٌ ۚ","(is) known"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(is) All-Aware"],["بِمَا","of what"],["تَعْمَلُونَ","you do"]]],"2845":["(Katakanlah! \"Taatlah kepada Allah dan taatlah kepada Rasul dan jika kalian berpaling) dari taat kepadanya. Lafal Tawallau asalnya adalah Tatawallau; maksudnya pembicaraan ini ditujukan kepada mereka (maka sesungguhnya kewajiban Rasul itu adalah apa yang dibebankan kepadanya) yaitu menyampaikan risalah (dan kewajiban kamu sekalian adalah semata-mata apa yang dibebankan kepada kalian) yakni untuk taat kepadanya (dan jika kalian taat kepadanya, niscaya kalian mendapat petunjuk. Dan tidak lain kewajiban Rasul itu melainkan menyampaikan amanat Allah dengan terang\") yaitu secara jelas dan gamblang.",[["قُلْ","Say"],["أَطِيعُوا۟","Obey"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","and obey"],["ٱلرَّسُولَ ۖ","the Messenger"],["فَإِن","but if"],["تَوَلَّوْا۟","you turn away"],["فَإِنَّمَا","then only"],["عَلَيْهِ","upon him"],["مَا","(is) what"],["حُمِّلَ","(is) placed on him"],["وَعَلَيْكُم","and on you"],["مَّا","(is) what"],["حُمِّلْتُمْ ۖ","(is) placed on you"],["وَإِن","And if"],["تُطِيعُوهُ","you obey him"],["تَهْتَدُوا۟ ۚ","you will be guided"],["وَمَا","And not"],["عَلَى","(is) on"],["ٱلرَّسُولِ","the Messenger"],["إِلَّا","except"],["ٱلْبَلَـٰغُ","the conveyance"],["ٱلْمُبِينُ","[the] clear"]]],"2846":["(Dan Allah telah menjanjikan kepada orang-orang yang beriman di antara kalian dan mengerjakan amal-amal yang saleh, bahwa Dia sungguh-sungguh akan menjadikan mereka berkuasa di bumi) sebagai ganti dari orang-orang kafir (sebagaimana Dia telah menjadikan berkuasa) dapat dibaca Kamastakhlafa dan Kamastukhlifa (orang-orang yang sebelum mereka) sebagaimana yang dialami oleh kaum Bani Israel sebagai pengganti dari orang-orang yang lalim dan angkara murka (dan sungguh Dia akan meneguhkan bagi mereka agama yang telah diridai-Nya untuk mereka) yaitu agama Islam; seumpamanya Dia akan memenangkannya di atas agama-agama yang lain, kemudian Dia meluaskan bagi mereka daerah-daerah mereka dan mereka menjadi para pemiliknya (dan Dia benar-benar akan menukar keadaan mereka) dapat dibaca Takhfif yaitu menjadi walayubdilannahum, dapat pula dibaca Tasydid yaitu menjadi Walayubaddilannahum (sesudah mereka berada dalam ketakutan) dari perlakuan orang-orang kafir (menjadi aman sentosa) dan Allah telah menunaikan janji-Nya kepada mereka, yaitu memberikan kepada mereka apa yang telah disebutkan tadi, kemudian Dia memuji mereka melalui firman-Nya, (Mereka tetap menyembah-Ku dengan tiada mempersekutukan sesuatu apa pun dengan Aku) ayat ini merupakan jumlah Isti'naf atau kalimat baru, akan tetapi statusnya disamakan sebagai Illat. (Dan barang siapa yang tetap kafir sesudah janji itu) sesudah pemberian nikmat kepada mereka, yaitu keamanan tadi (maka mereka itulah orang-orang yang fasik) dan orang-orang yang mula-mula kafir sesudah itu adalah para pembunuh Khalifah Usman r.a. kemudian mereka menjadi orang-orang yang saling membunuh padahal sebelumnya mereka berteman.",[["وَعَدَ","Allah (has) promised"],["ٱللَّهُ","Allah (has) promised"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["مِنكُمْ","among you"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["لَيَسْتَخْلِفَنَّهُمْ","surely He will grant them succession"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["كَمَا","as"],["ٱسْتَخْلَفَ","He gave succession"],["ٱلَّذِينَ","to those who"],["مِن","(were) before them"],["قَبْلِهِمْ","(were) before them"],["وَلَيُمَكِّنَنَّ","and that He will surely establish"],["لَهُمْ","for them"],["دِينَهُمُ","their religion"],["ٱلَّذِى","which"],["ٱرْتَضَىٰ","He has approved"],["لَهُمْ","for them"],["وَلَيُبَدِّلَنَّهُم","and surely He will change for them"],["مِّنۢ","after"],["بَعْدِ","after"],["خَوْفِهِمْ","their fear"],["أَمْنًۭا ۚ","security"],["يَعْبُدُونَنِى","(for) they worship Me"],["لَا","not"],["يُشْرِكُونَ","they associate"],["بِى","with Me"],["شَيْـًۭٔا ۚ","anything"],["وَمَن","But whoever"],["كَفَرَ","disbelieved"],["بَعْدَ","after"],["ذَٰلِكَ","that"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْفَـٰسِقُونَ","(are) the defiantly disobedient"]]],"2847":["(Dan dirikanlah salat, tunaikanlah zakat, dan taatlah kepada Rasul, supaya kalian diberi rahmat) mudah-mudahan kalian diberi rahmat.",[["وَأَقِيمُوا۟","And establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَءَاتُوا۟","and give"],["ٱلزَّكَوٰةَ","zakah"],["وَأَطِيعُوا۟","and obey"],["ٱلرَّسُولَ","the Messenger"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"2848":["(Janganlah kamu kira) dapat dibaca Tahsabanna dan Yahsabanna, yang menjadi Fa'il atau subyeknya adalah Rasulullah (bahwa orang-orang yang kafir itu dapat melemahkan) Kami (di bumi ini) yakni selamat dari azab Kami (sedangkan tempat tinggal mereka) yaitu tempat mereka kembali (adalah neraka. Dan sungguh sejelek-jelek tempat kembali adalah neraka) maksudnya tempat kembali yang paling buruk.",[["لَا","(Do) not"],["تَحْسَبَنَّ","think"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["مُعْجِزِينَ","(can) escape"],["فِى","in"],["ٱلْأَرْضِ ۚ","the earth"],["وَمَأْوَىٰهُمُ","And their abode"],["ٱلنَّارُ ۖ","(will be) the Fire"],["وَلَبِئْسَ","and wretched is"],["ٱلْمَصِيرُ","the destination"]]],"2849":["(Hai orang-orang yang beriman, hendaklah meminta izin kepada kalian budak-budak yang kalian miliki) baik yang laki-laki maupun yang perempuan (dan orang-orang yang belum balig di antara kalian) maksudnya dari kalangan orang-orang yang merdeka dan belum mengetahui perihal kaum wanita (sebanyak tiga kali) yaitu dalam tiga waktu untuk seharinya (yaitu sebelum salat subuh dan ketika kalian menanggalkan pakaian luar kalian di tengah hari) yakni waktu salat Zuhur (dan sesudah salat Isyak. Itulah tiga aurat bagi kalian) kalau dibaca Rafa' menjadi Tsalaatsu 'Auraatin, berarti menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, dan sebelum Khabar terdapat Mudhaf, kemudian kedudukan Mudhaf yang diperkirakan itu diganti oleh Mudhaf ilaih yaitu lafal Tsalaatsun itu sendiri. Makna selengkapnya ialah, Ketentuan tersebut adalah tiga waktu yang ketiga-tiganya merupakan aurat bagi kalian. Jika dibaca Nashab menjadi Tsalaatsa Auraatin Lakum, dengan memperkirakan adanya lafal Auraatin yang dinashabkan, juga karena menjadi Badal secara Mahal dari lafal sebelumnya, kemudian Mudhaf ilaih menggantikan kedudukannya. Dikatakan demikian karena pada saat-saat tersebut, yaitu ketiga waktu itu, orang-orang membuka pakaian luar mereka untuk istirahat sehingga auratnya kelihatan. (Tidak ada atas kalian dan tidak pula atas mereka) atas budak-budak yang kalian miliki dan anak-anak kecil (dosa) untuk masuk menemui kalian tanpa izin (selain dari tiga waktu itu) yakni sesudah ketiga waktu tadi, sedangkan mereka (melayani kalian) meladeni kalian (sebagian kalian) yakni pelayan itu mempunyai keperluan (kepada sebagian yang lain) kalimat ini berkedudukan mengukuhkan makna sebelumnya. (Demikianlah) sebagaimana apa yang telah disebutkan tadi (Allah menjelaskan ayat-ayat bagi kalian) yakni menjelaskan hukum-hukum-Nya. (Dan Allah Maha Mengetahui) tentang semua urusan makhluk-Nya (lagi Maha Bijaksana) di dalam mengatur kepentingan mereka. Ayat yang menyangkut masalah meminta izin ini menurut suatu pendapat telah dinasakh. Akan tetapi menurut pendapat yang lain tidak dinasakh, hanya saja orang-orang meremehkan masalah meminta izin ini, sehingga banyak dari mereka yang tidak memakainya lagi.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["لِيَسْتَـْٔذِنكُمُ","Let ask your permission"],["ٱلَّذِينَ","those whom"],["مَلَكَتْ","possess"],["أَيْمَـٰنُكُمْ","your right hands"],["وَٱلَّذِينَ","and those who"],["لَمْ","(have) not"],["يَبْلُغُوا۟","reached"],["ٱلْحُلُمَ","puberty"],["مِنكُمْ","among you"],["ثَلَـٰثَ","(at) three"],["مَرَّٰتٍۢ ۚ","times"],["مِّن","before"],["قَبْلِ","before"],["صَلَوٰةِ","(the) prayer"],["ٱلْفَجْرِ","(of) dawn"],["وَحِينَ","and when"],["تَضَعُونَ","you put aside"],["ثِيَابَكُم","your garments"],["مِّنَ","at"],["ٱلظَّهِيرَةِ","noon"],["وَمِنۢ","and after"],["بَعْدِ","and after"],["صَلَوٰةِ","(the) prayer"],["ٱلْعِشَآءِ ۚ","(of) night"],["ثَلَـٰثُ","(These) three"],["عَوْرَٰتٍۢ","(are) times of privacy"],["لَّكُمْ ۚ","for you"],["لَيْسَ","Not"],["عَلَيْكُمْ","on you"],["وَلَا","and not"],["عَلَيْهِمْ","on them"],["جُنَاحٌۢ","any blame"],["بَعْدَهُنَّ ۚ","after that"],["طَوَّٰفُونَ","(as) moving about"],["عَلَيْكُم","among you"],["بَعْضُكُمْ","some of you"],["عَلَىٰ","among"],["بَعْضٍۢ ۚ","others"],["كَذَٰلِكَ","Thus"],["يُبَيِّنُ","Allah makes clear"],["ٱللَّهُ","Allah makes clear"],["لَكُمُ","for you"],["ٱلْـَٔايَـٰتِ ۗ","the Verses"],["وَٱللَّهُ","and Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"2850":["(Dan apabila anak-anak kalian telah sampai) hai orang-orang yang merdeka (kepada usia balig, maka hendaklah mereka meminta izin) dalam semua waktu (seperti orang-orang yang sebelum mereka meminta izin) yakni orang-orang dewasa yang merdeka. (Demikianlah Allah menjelaskan ayat-ayat-Nya bagi kalian. Dan Allah Maha mengetahui lagi Maha Bijaksana).",[["وَإِذَا","And when"],["بَلَغَ","reach"],["ٱلْأَطْفَـٰلُ","the children"],["مِنكُمُ","among you"],["ٱلْحُلُمَ","the puberty"],["فَلْيَسْتَـْٔذِنُوا۟","then let them ask permission"],["كَمَا","as"],["ٱسْتَـْٔذَنَ","asked permission"],["ٱلَّذِينَ","those who"],["مِن","(were) before them"],["قَبْلِهِمْ ۚ","(were) before them"],["كَذَٰلِكَ","Thus"],["يُبَيِّنُ","Allah makes clear"],["ٱللَّهُ","Allah makes clear"],["لَكُمْ","for you"],["ءَايَـٰتِهِۦ ۗ","His Verses"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"2851":["(Dan perempuan-perempuan tua yang telah terhenti) dari haid dan dari mempunyai anak disebabkan telah lanjut umurnya (yang tiada ingin kawin lagi) bagi yang demikian itu (tiadalah atas mereka dosa menanggalkan pakaian mereka) yakni jilbab mereka, atau selendang mereka, atau penutup yang ada di atas kerudung mereka (dengan tidak bermaksud menampakkan) yakni menonjolkan (perhiasan)-nya yang tersembunyi seperti kalung, gelang tangan dan gelang kaki (dan berlaku terhormat) tidak melepaskannya (adalah lebih baik bagi mereka. Dan Allah Maha Mendengar) perkataan kalian (lagi Maha Mengetahui) apa yang tersimpan di dalam kalbu kalian.",[["وَٱلْقَوَٰعِدُ","And postmenopausal"],["مِنَ","among"],["ٱلنِّسَآءِ","the women"],["ٱلَّـٰتِى","who"],["لَا","(do) not"],["يَرْجُونَ","have desire"],["نِكَاحًۭا","(for) marriage"],["فَلَيْسَ","then not is"],["عَلَيْهِنَّ","on them"],["جُنَاحٌ","any blame"],["أَن","that"],["يَضَعْنَ","they put aside"],["ثِيَابَهُنَّ","their (outer) garments"],["غَيْرَ","not"],["مُتَبَرِّجَـٰتٍۭ","displaying"],["بِزِينَةٍۢ ۖ","their adornment"],["وَأَن","And that"],["يَسْتَعْفِفْنَ","they modestly refrain"],["خَيْرٌۭ","(is) better"],["لَّهُنَّ ۗ","for them"],["وَٱللَّهُ","And Allah"],["سَمِيعٌ","(is) All-Hearer"],["عَلِيمٌۭ","All-Knower"]]],"2852":["(Tidak ada dosa bagi orang buta, tidak pula bagi orang pincang, dan tidak pula bagi orang sakit) untuk makan bersama dengan orang-orang selain mereka (dan tidak pula) dosa (bagi diri kalian sendiri untuk makan bersama mereka di rumah kalian sendiri) yaitu di rumah anak-anak kalian (atau rumah bapak-bapak kalian, di rumah ibu-ibu kalian, di rumah saudara-saudara kalian yang laki-laki, di rumah saudara-saudara kalian yang perempuan, di rumah saudara-saudara bapak kalian yang laki-laki, di rumah saudara-saudara bapak kalian yang perempuan, di rumah saudara-saudara ibu kalian yang laki-laki, di rumah saudara-saudara ibu kalian yang perempuan, di rumah yang kalian miliki kuncinya) yang khusus kalian sediakan buat orang lain (atau - di rumah - kawan-kawan kalian) yang dimaksud dengan kawan adalah orang-orang yang benar-benar setia kepada kalian. Makna ayat ini ialah, bahwa kalian diperbolehkan makan dari rumah-rumah orang-orang yang telah disebutkan tadi, sekalipun para pemiliknya tidak hadir atau sedang tidak ada di rumah, jika memang kalian telah yakin akan kerelaan mereka terhadap sikap kalian itu (Tidak ada dosa bagi kalian makan bersama-sama mereka) yakni berbarengan dengan mereka (atau sendirian) tidak bersama-sama. Lafal Asytaatan ini adalah bentuk jamak dari kata Syatta, artinya sendiri-sendiri atau berpisah-pisah. Ayat ini diturunkan berkenaan dengan seseorang yang merasa berdosa jika ia makan sendirian. Jika ia tidak menemukan seseorang yang mau makan bersamanya, maka ia tidak mau memakan makanannya (maka apabila kalian memasuki rumah-rumah) milik kalian sendiri yang tidak ada penghuninya (hendaklah kalian memberi salam kepada diri kalian sendiri) katakanlah! \"Assalaamu 'Alainaa Wa Alaa `Ibaadillaahish Shaalihiin\" yang artinya, \"Keselamatan semoga dilimpahkan kepada diri kami dan hamba-hamba Allah yang saleh\". Karena sesungguhnya para Malaikatlah yang akan menjawab salam kalian itu. Jika ternyata di dalam rumah-rumah itu terdapat penghuninya, maka berilah salam kepada mereka (sebagai salam) lafal Tahiyyatan menjadi Mashdar artinya sebagai penghormatan (yang ditetapkan di sisi Allah, yang diberkati lagi baik) yakni diberi pahala bagi orang yang mengucapkannya. (Demikianlah Allah menjelaskan ayat-ayat-Nya bagi kalian) Dia merincikan tanda-tanda agama kalian (agar kalian memahaminya) supaya kalian mengerti hal tersebut.",[["لَّيْسَ","Not is"],["عَلَى","on"],["ٱلْأَعْمَىٰ","the blind"],["حَرَجٌۭ","any blame"],["وَلَا","and not"],["عَلَى","on"],["ٱلْأَعْرَجِ","the lame"],["حَرَجٌۭ","any blame"],["وَلَا","and not"],["عَلَى","on"],["ٱلْمَرِيضِ","the sick"],["حَرَجٌۭ","any blame"],["وَلَا","and not"],["عَلَىٰٓ","on"],["أَنفُسِكُمْ","yourselves"],["أَن","that"],["تَأْكُلُوا۟","you eat"],["مِنۢ","from"],["بُيُوتِكُمْ","your houses"],["أَوْ","or"],["بُيُوتِ","houses"],["ءَابَآئِكُمْ","(of) your fathers"],["أَوْ","or"],["بُيُوتِ","houses"],["أُمَّهَـٰتِكُمْ","(of) your mothers"],["أَوْ","or"],["بُيُوتِ","houses"],["إِخْوَٰنِكُمْ","(of) your brothers"],["أَوْ","or"],["بُيُوتِ","houses"],["أَخَوَٰتِكُمْ","(of) your sisters"],["أَوْ","or"],["بُيُوتِ","houses"],["أَعْمَـٰمِكُمْ","(of) your paternal uncles"],["أَوْ","or"],["بُيُوتِ","houses"],["عَمَّـٰتِكُمْ","(of) your paternal aunts"],["أَوْ","or"],["بُيُوتِ","houses"],["أَخْوَٰلِكُمْ","(of) your maternal uncles"],["أَوْ","or"],["بُيُوتِ","houses"],["خَـٰلَـٰتِكُمْ","(of) your maternal aunts"],["أَوْ","or"],["مَا","what"],["مَلَكْتُم","you possess"],["مَّفَاتِحَهُۥٓ","its keys"],["أَوْ","or"],["صَدِيقِكُمْ ۚ","your friend"],["لَيْسَ","Not is"],["عَلَيْكُمْ","on you"],["جُنَاحٌ","any blame"],["أَن","that"],["تَأْكُلُوا۟","you eat"],["جَمِيعًا","together"],["أَوْ","or"],["أَشْتَاتًۭا ۚ","separately"],["فَإِذَا","But when"],["دَخَلْتُم","you enter"],["بُيُوتًۭا","houses"],["فَسَلِّمُوا۟","then greet"],["عَلَىٰٓ","[on]"],["أَنفُسِكُمْ","yourselves"],["تَحِيَّةًۭ","a greeting"],["مِّنْ","from"],["عِندِ","from"],["ٱللَّهِ","Allah"],["مُبَـٰرَكَةًۭ","blessed"],["طَيِّبَةًۭ ۚ","(and) good"],["كَذَٰلِكَ","Thus"],["يُبَيِّنُ","Allah makes clear"],["ٱللَّهُ","Allah makes clear"],["لَكُمُ","for you"],["ٱلْـَٔايَـٰتِ","the Verses"],["لَعَلَّكُمْ","so that you may"],["تَعْقِلُونَ","understand"]]],"2853":["(Orang-orang Mukmin yang sesungguhnya itu tidak lain hanyalah orang-orang yang beriman kepada Allah dan Rasul-Nya, dan apabila mereka berada bersama-sama dengannya) dengan Rasulullah (dalam sesuatu urusan yang memerlukan pertemuan) seperti khutbah Jumat (mereka tidak meninggalkan) Rasulullah karena hal-hal mendadak yang dialami mereka, dalam hal ini mereka dimaafkan (sebelum meminta izin kepadanya. Sesungguhnya orang-orang yang meminta izin kepadamu, mereka itulah orang-orang yang beriman kepada Allah dan Rasul-Nya, maka apabila mereka meminta izin kepadamu karena sesuatu keperluan mereka) karena mereka mempunyai urusan penting (berilah izin kepada siapa yang kamu kehendaki di antara mereka) untuk pergi (dan mohonkanlah ampunan untuk mereka kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["إِنَّمَا","Only"],["ٱلْمُؤْمِنُونَ","the believers"],["ٱلَّذِينَ","(are) those who"],["ءَامَنُوا۟","believe"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِۦ","and His Messenger"],["وَإِذَا","and when"],["كَانُوا۟","they are"],["مَعَهُۥ","with him"],["عَلَىٰٓ","for"],["أَمْرٍۢ","a matter"],["جَامِعٍۢ","(of) collective action"],["لَّمْ","not"],["يَذْهَبُوا۟","they go"],["حَتَّىٰ","until"],["يَسْتَـْٔذِنُوهُ ۚ","they (have) asked his permission"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَسْتَـْٔذِنُونَكَ","ask your permission"],["أُو۟لَـٰٓئِكَ","those"],["ٱلَّذِينَ","[those who]"],["يُؤْمِنُونَ","believe"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِۦ ۚ","and His Messenger"],["فَإِذَا","So when"],["ٱسْتَـْٔذَنُوكَ","they ask your permission"],["لِبَعْضِ","for some"],["شَأْنِهِمْ","affair of theirs"],["فَأْذَن","then give permission"],["لِّمَن","to whom"],["شِئْتَ","you will"],["مِنْهُمْ","among them"],["وَٱسْتَغْفِرْ","and ask forgiveness"],["لَهُمُ","for them"],["ٱللَّهَ ۚ","(of) Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"2854":["(Janganlah kalian jadikan panggilan Rasul di antara kalian seperti panggilan sebagian kalian kepada sebagian yang lain) umpamanya kalian mengatakan, \"Hai Muhammad!\" Tetapi ucapkanlah, \"Hai Nabi Allah, hai Rasulullah!\" Dengan suara yang lemah lembut dan penuh rendah diri. (Sesungguhnya Allah telah mengetahui orang-orang yang diam-diam pergi di antara kalian dengan sembunyi-sembunyi) mereka keluar dari mesjid pada waktu Nabi mengucapkan khutbahnya tanpa terlebih dahulu meminta izin kepadanya, secara diam-diam sambil menyembunyikan diri di balik sesuatu. Huruf Qad di sini menunjukkan makna Tahqiq yang artinya sesungguhnya (maka hendaklah orang-orang yang menyalahi perintah-Nya merasa takut) menyalahi perintah Allah dan Rasul-Nya (akan ditimpa cobaan) malapetaka (atau ditimpa azab yang pedih) di akhirat kelak.",[["لَّا","(Do) not"],["تَجْعَلُوا۟","make"],["دُعَآءَ","(the) calling"],["ٱلرَّسُولِ","(of) the Messenger"],["بَيْنَكُمْ","among you"],["كَدُعَآءِ","as (the) call"],["بَعْضِكُم","(of) some of you"],["بَعْضًۭا ۚ","(to) others"],["قَدْ","Verily"],["يَعْلَمُ","Allah knows"],["ٱللَّهُ","Allah knows"],["ٱلَّذِينَ","those who"],["يَتَسَلَّلُونَ","slip away"],["مِنكُمْ","among you"],["لِوَاذًۭا ۚ","under shelter"],["فَلْيَحْذَرِ","So let beware"],["ٱلَّذِينَ","those who"],["يُخَالِفُونَ","oppose"],["عَنْ","[from]"],["أَمْرِهِۦٓ","his orders"],["أَن","lest"],["تُصِيبَهُمْ","befalls them"],["فِتْنَةٌ","a trial"],["أَوْ","or"],["يُصِيبَهُمْ","befalls them"],["عَذَابٌ","a punishment"],["أَلِيمٌ","painful"]]],"2855":["(Ketahuilah, sesungguhnya kepunyaan Allahlah apa yang di langit dan di bumi) sebagai milik, makhluk dan hamba-Nya. (Sesungguhnya Dia mengetahui keadaan yang kalian) hai orang-orang Mukallaf (berada di dalamnya) apakah kalian beriman atau munafik. (Dan) Dia mengetahui pula (hari manusia dikembalikan kepada-Nya) di dalam ungkapan ini terdapat iltifat dari mukhatab ke ghaib. Maksudnya, bila hal itu akan terjadi (lalu diterangkan-Nya kepada mereka) pada hari itu (apa yang telah mereka kerjakan) yaitu perbuatan baik dan perbuatan buruk yang telah mereka perbuat (Dan Allah terhadap segala sesuatu) terhadap semua perbuatan kalian dan selainnya (Maha Mengetahui.)",[["أَلَآ","No doubt"],["إِنَّ","Indeed"],["لِلَّهِ","to Allah (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۖ","and the earth"],["قَدْ","Verily"],["يَعْلَمُ","He knows"],["مَآ","what"],["أَنتُمْ","you"],["عَلَيْهِ","(are) on [it]"],["وَيَوْمَ","And (the) Day"],["يُرْجَعُونَ","they will be returned"],["إِلَيْهِ","to Him"],["فَيُنَبِّئُهُم","then He will inform them"],["بِمَا","of what"],["عَمِلُوا۟ ۗ","they did"],["وَٱللَّهُ","And Allah"],["بِكُلِّ","of every"],["شَىْءٍ","thing"],["عَلِيمٌۢ","(is) All-Knower"]]],"2856":["(Maha Suci) Allah swt. (yang telah menurunkan Alfurqan) yakni Alquran, ia dinamakan Alfurqan karena kandungannya membedakan antara perkara yang hak dan perkara yang batil (kepada hamba-Nya) yakni Nabi Muhammad (agar dia menyampaikannya kepada seluruh alam) yaitu kepada bangsa manusia dan bangsa jin, selain bangsa malaikat (sebagai pemberi peringatan) kepada mereka, dengan memperingatkan mereka akan azab Allah.",[["تَبَارَكَ","Blessed is He"],["ٱلَّذِى","Who"],["نَزَّلَ","sent down"],["ٱلْفُرْقَانَ","the Criterion"],["عَلَىٰ","upon"],["عَبْدِهِۦ","His slave"],["لِيَكُونَ","that he may be"],["لِلْعَـٰلَمِينَ","to the worlds"],["نَذِيرًا","a warner "]]],"2857":["(Yang kepunyaan-Nyalah kerajaan langit dan bumi, dan Dia tidak mempunyai anak, dan tidak ada sekutu bagi-Nya dalam kekuasaan-Nya, dan Dia telah menciptakan segala sesuatu) karena hanya Dialah yang mampu menciptakan kesemuanya itu (dan Dia menetapkan ukuran-ukurannya dengan serapi-rapinya) secara tepat dan sempurna.",[["ٱلَّذِى","The One Who "],["لَهُۥ","to Him (belongs)"],["مُلْكُ","(the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَلَمْ","and not"],["يَتَّخِذْ","He has taken"],["وَلَدًۭا","a son"],["وَلَمْ","and not"],["يَكُن","He has"],["لَّهُۥ","for Him"],["شَرِيكٌۭ","a partner"],["فِى","in"],["ٱلْمُلْكِ","the dominion"],["وَخَلَقَ","and He (has) created"],["كُلَّ","every"],["شَىْءٍۢ","thing"],["فَقَدَّرَهُۥ","and determined it"],["تَقْدِيرًۭا","(with) determination"]]],"2858":["(Kemudian mereka mengambil) yang dimaksud adalah orang-orang kafir (selain daripada-Nya) selain Allah swt. (sebagai tuhan-tuhan) berupa berhala-berhala (yang mereka tidak menciptakan apa pun, bahkan mereka sendiri diciptakan dan tidak kuasa untuk menolak sesuatu kemudaratan dari dirinya) tidak akan mampu menolak bahaya yang mengancam dirinya (dan tidak pula untuk mengambil suatu manfaat pun) artinya tidak dapat menghasilkan manfaat bagi dirinya (dan juga tidak kuasa mematikan, menghidupkan) yakni tidak mampu mematikan seseorang dan tidak pula mampu menghidupkannya (dan tidak pula membangkitkan) tidak mampu membangkitkan orang-orang yang mati untuk dapat hidup kembali.",[["وَٱتَّخَذُوا۟","Yet they have taken"],["مِن","besides Him"],["دُونِهِۦٓ","besides Him"],["ءَالِهَةًۭ","gods"],["لَّا","not"],["يَخْلُقُونَ","they create"],["شَيْـًۭٔا","anything"],["وَهُمْ","while they"],["يُخْلَقُونَ","are created"],["وَلَا","and not"],["يَمْلِكُونَ","they possess"],["لِأَنفُسِهِمْ","for themselves"],["ضَرًّۭا","any harm"],["وَلَا","and not"],["نَفْعًۭا","any benefit"],["وَلَا","and not"],["يَمْلِكُونَ","they control"],["مَوْتًۭا","death"],["وَلَا","and not"],["حَيَوٰةًۭ","life"],["وَلَا","and not"],["نُشُورًۭا","resurrection"]]],"2859":["(Dan orang-orang kafir berkata, \"Sesungguhnya ini) Alquran ini (tidak lain hanyalah kebohongan-kebohongan) yakni kedustaan (yang diada-adakan olehnya) oleh Muhammad sendiri (dan dia dibantu oleh kaum yang lain) yakni oleh sebagian dari orang-orang ahli kitab. Allah berfirman: (Maka sesungguhnya mereka telah berbuat suatu kelaliman dan dusta yang besar\") yakni kekafiran dan kedustaan.",[["وَقَالَ","And say"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieve"],["إِنْ","Not"],["هَـٰذَآ","this"],["إِلَّآ","(is) but"],["إِفْكٌ","a lie"],["ٱفْتَرَىٰهُ","he invented it"],["وَأَعَانَهُۥ","and helped him"],["عَلَيْهِ","at it"],["قَوْمٌ","people"],["ءَاخَرُونَ ۖ","other"],["فَقَدْ","But verily"],["جَآءُو","they (have) produced"],["ظُلْمًۭا","an injustice"],["وَزُورًۭا","and a lie"]]],"2860":["(Dan mereka berkata,) pula bahwa Alquran itu (\"Dongengan-dongengan orang-orang dahulu) yakni kedustaan-kedustaan mereka. Lafal Asaathiir adalah bentuk jamak dari lafal Usthuurah (dimintanya supaya dituliskan) telah menukilnya dari kaum tersebut melalui orang lain (maka dibacakanlah dongengan itu kepadanya) supaya ia hafal (setiap pagi dan petang.\") Kemudian Allah berfirman menyanggah ucapan mereka:",[["وَقَالُوٓا۟","And they say"],["أَسَـٰطِيرُ","Tales"],["ٱلْأَوَّلِينَ","(of) the former people"],["ٱكْتَتَبَهَا","which he has had written"],["فَهِىَ","and they"],["تُمْلَىٰ","are dictated"],["عَلَيْهِ","to him"],["بُكْرَةًۭ","morning"],["وَأَصِيلًۭا","and evening"]]],"2861":["(Katakanlah! \"Alquran ini diturunkan oleh Allah yang mengetahui rahasia) hal-hal yang gaib (di langit dan di bumi. Sesungguhnya Dia adalah Maha Pengampun) kepada orang-orang yang beriman (lagi Maha Penyayang\") kepada mereka.",[["قُلْ","Say"],["أَنزَلَهُ","Has sent it down"],["ٱلَّذِى","the One Who"],["يَعْلَمُ","knows"],["ٱلسِّرَّ","the secret"],["فِى","in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["إِنَّهُۥ","Indeed, He"],["كَانَ","is"],["غَفُورًۭا","Oft-Forgiving"],["رَّحِيمًۭا","Most Merciful"]]],"2862":["(Dan mereka berkata, \"Mengapa Rasul ini memakan makanan dan berjalan di pasar-pasar? Mengapa tidak) (diturunkan kepadanya Malaikat, agar Malaikat itu memberikan peringatan bersama dengan dia?) maksudnya yang membenarkan kerasulannya.",[["وَقَالُوا۟","And they say"],["مَالِ","Why does"],["هَـٰذَا","this"],["ٱلرَّسُولِ","Messenger"],["يَأْكُلُ","eat"],["ٱلطَّعَامَ","[the] food"],["وَيَمْشِى","and walk"],["فِى","in"],["ٱلْأَسْوَاقِ ۙ","the markets"],["لَوْلَآ","Why not"],["أُنزِلَ","is sent down"],["إِلَيْهِ","to him"],["مَلَكٌۭ","an Angel"],["فَيَكُونَ","then he be"],["مَعَهُۥ","with him"],["نَذِيرًا","a warner"]]],"2863":["(Atau mengapa tidak diturunkan kepadanya perbendaharaan) dari langit yang kemudian ia membelanjakannya, sehingga ia tidak usah berjalan-jalan di pasar lagi untuk mencari penghidupan (atau mengapa tidak ada kebun baginya) yaitu ladang yang menjadi miliknya (yang dapat dia makan dari hasilnya\") buah-buahannya, sehingga hal itu menjadi kecukupan baginya. Menurut qiraat yang lain dibaca Na'kulu Minhaa, artinya; yang kami dapat ikut makan dari kebunnya. Maksudnya, supaya memiliki kelebihan di atas kami. (Dan orang-orang yang zalim itu berkata:) orang-orang kafir itu kepada orang-orang Mukmin, (\"Tidak lain kamu sekalian hanyalah mengikuti seorang lelaki yang kena sihir\") orang yang akalnya tidak waras karena pengaruh sihir. Maka Allah berfirman pada ayat selanjutnya:",[["أَوْ","Or"],["يُلْقَىٰٓ","is delivered"],["إِلَيْهِ","to him"],["كَنزٌ","a treasure"],["أَوْ","or"],["تَكُونُ","is"],["لَهُۥ","for him"],["جَنَّةٌۭ","a garden"],["يَأْكُلُ","he may eat"],["مِنْهَا ۚ","from it"],["وَقَالَ","And say"],["ٱلظَّـٰلِمُونَ","the wrongdoers"],["إِن","Not"],["تَتَّبِعُونَ","you follow"],["إِلَّا","but"],["رَجُلًۭا","a man"],["مَّسْحُورًا","bewitched"]]],"2864":["(Perhatikanlah, bagaimana mereka membuat perumpamaan-perumpamaan tentang kamu) dengan julukan sebagai orang yang kena pengaruh sihir, orang yang membutuhkan nafkah, orang yang harus ditemani oleh Malaikat yang bersama-sama menyampaikan tugasnya (lalu sesatlah mereka) dari petunjuk disebabkan ucapannya itu (mereka tidak sanggup mendapatkan jalan untuk menentang kerasulannya) maksudnya mereka tidak akan dapat menemukan jalan untuk menentangnya.",[["ٱنظُرْ","See"],["كَيْفَ","how"],["ضَرَبُوا۟","they set forth"],["لَكَ","for you"],["ٱلْأَمْثَـٰلَ","the similitudes"],["فَضَلُّوا۟","but they have gone astray"],["فَلَا","so not"],["يَسْتَطِيعُونَ","they are able (to find)"],["سَبِيلًۭا","a way"]]],"2865":["(Maha Agung Allah) Maha Kaya akan kebaikan (yang jika Dia menghendaki, niscaya dijadikan-Nya bagimu yang lebih baik dari yang demikian) yakni lebih baik daripada perbendaharaan harta dan kebun yang mereka mintakan di dunia ini (yaitu surga-surga yang di bawahnya mengalir sungai-sungai) karena Dia telah menjanjikan akan memberikan kepadanya nanti di akhirat (dan dijadikan-Nya pula) lafal ayat ini dibaca Jazm (untukmu istana-istana) dan menurut qiraat yang lain, lafal Yaj'al dibaca Yaj'alu sehingga kedudukannya menjadi kalimat Isti'naf, atau kalimat baru.",[["تَبَارَكَ","Blessed is He"],["ٱلَّذِىٓ","Who"],["إِن","if"],["شَآءَ","He willed"],["جَعَلَ","(could have) made"],["لَكَ","for you"],["خَيْرًۭا","better"],["مِّن","than"],["ذَٰلِكَ","that "],["جَنَّـٰتٍۢ","gardens "],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath it"],["ٱلْأَنْهَـٰرُ","the rivers"],["وَيَجْعَل","and He (could) make"],["لَّكَ","for you"],["قُصُورًۢا","palaces"]]],"2866":["(Bahkan mereka mendustakan hari kiamat) hari terakhir yang tiada hari lagi sesudahnya. (Dan Kami menyediakan neraka yang menyala-nyala bagi siapa yang mendustakan hari kiamat) neraka yang apinya menyala-nyala dengan nyala yang besar.",[["بَلْ","Nay"],["كَذَّبُوا۟","they deny"],["بِٱلسَّاعَةِ ۖ","the Hour"],["وَأَعْتَدْنَا","and We have prepared"],["لِمَن","for (those) who"],["كَذَّبَ","deny"],["بِٱلسَّاعَةِ","the Hour"],["سَعِيرًا","a Blazing Fire"]]],"2867":["(Apabila neraka itu melihat mereka dari tempat yang jauh, mereka mendengar kegeramannya) yakni suara mendidihnya seperti halnya orang yang sedang marah (dan suara nyalanya) suara yang keras sekali dari nyala apinya. Atau makna yang dimaksud adalah jika orang-orang tersebut melihat neraka sekalipun dari tempat yang jauh, mereka akan mendengar suara gemuruh dan nyala apinya.",[["إِذَا","When"],["رَأَتْهُم","it sees them"],["مِّن","from"],["مَّكَانٍۭ","a place"],["بَعِيدٍۢ","far"],["سَمِعُوا۟","they will hear"],["لَهَا","its"],["تَغَيُّظًۭا","raging"],["وَزَفِيرًۭا","and roaring"]]],"2868":["(Dan apabila mereka dicampakkan ke tempat yang sempit di neraka itu) dapat dibaca Dhayyiqan dengan memakai harakat Tasydid pada huruf Ya, dapat pula dibaca Takhfif atau tanpa Tasydid sehingga bacaannya menjadi Dhayqan, maksudnya neraka itu menghimpit mereka. Lafal Minhaa berkedudukan menjadi Hal dari lafal Makaanan, karena pada asalnya ia adalah kata sifat baginya (dengan dibelenggu) yakni tangan dan leher mereka dibelenggu menjadi satu; harakat Tasydid yang ada pada lafal Muqarraniina menunjukkan makna Taktsir atau banyak (mereka di sana mengharapkan kebinasaan) maksudnya mereka ingin mati saja karena pedihnya siksaan. Dikatakan oleh Allah swt. kepada mereka,",[["وَإِذَآ","And when"],["أُلْقُوا۟","they are thrown"],["مِنْهَا","thereof"],["مَكَانًۭا","(in) a place"],["ضَيِّقًۭا","narrow"],["مُّقَرَّنِينَ","bound in chains"],["دَعَوْا۟","they will call"],["هُنَالِكَ","there"],["ثُبُورًۭا","(for) destruction"]]],"2869":["(\"Janganlah kamu sekalian mengharapkan satu kebinasaan, melainkan harapkanlah kebinasaan yang banyak\") sesuai dengan azab yang menimpa kalian ini.",[["لَّا","(Do) not"],["تَدْعُوا۟","call"],["ٱلْيَوْمَ","this day"],["ثُبُورًۭا","(for) destruction"],["وَٰحِدًۭا","one"],["وَٱدْعُوا۟","but call"],["ثُبُورًۭا","(for) destructions"],["كَثِيرًۭا","many"]]],"2870":["(Katakanlah! \"Apa yang demikian itukah) hal yang telah disebutkan itukah, yaitu ancaman dan gambaran tentang neraka (yang baik, atau surga yang kekal yang telah dijanjikan) (kepada orang-orang yang bertakwa?\" Surga itu untuk mereka) menurut ilmu Allah (sebagai balasan) sebagai pahala (dan tempat kembali) tempat menetap yang abadi.",[["قُلْ","Say"],["أَذَٰلِكَ","Is that"],["خَيْرٌ","better"],["أَمْ","or"],["جَنَّةُ","Garden"],["ٱلْخُلْدِ","(of) Eternity"],["ٱلَّتِى","which"],["وُعِدَ","is promised"],["ٱلْمُتَّقُونَ ۚ","(to) the righteous"],["كَانَتْ","It will be"],["لَهُمْ","for them"],["جَزَآءًۭ","a reward"],["وَمَصِيرًۭا","and destination"]]],"2871":["(Bagi mereka di dalam surga itu apa yang mereka kehendaki, sedangkan mereka kekal) lafal Khaalidiina menjadi Hal yang bersifat Lazimah atau harus (adalah) janji mereka seperti yang telah disebutkan tadi (janji dari Rabbmu yang patut dimohonkan kepada-Nya) artinya orang yang telah dijanjikan kepadanya hal itu patut untuk memohon kepada-Nya, sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Ya Rabb kami! Berilah kami apa yang telah Engkau janjikan kepada kami dengan perantaraan rasul-rasul Engkau.\" (Q.S. Ali Imran, 194) atau hal itu dimintakan oleh para Malaikat buat mereka, sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Ya Rabb kami! Masukkanlah mereka ke dalam surga Adn yang telah Engkau janjikan-kepada mereka.\" (Q.S. Al Mukmin, 8).",[["لَّهُمْ","For them"],["فِيهَا","therein"],["مَا","(is) whatever"],["يَشَآءُونَ","they wish"],["خَـٰلِدِينَ ۚ","they will abide forever"],["كَانَ","It is"],["عَلَىٰ","on"],["رَبِّكَ","your Lord"],["وَعْدًۭا","a promise"],["مَّسْـُٔولًۭا","requested"]]],"2872":["(Dan pada suatu hari ketika Allah menghimpunkan mereka) lafal Yahsyuruhum dapat pula dibaca Nahsyuruhum, sehingga artinya menjadi, Kami menghimpun mereka (beserta apa yang mereka sembah selain Allah) yakni seperti malaikat; Nabi Isa, dan Nabi Uzair, serta jin (lalu Allah berkata:) kepada mereka yang disembah untuk memantapkan hujah-Nya terhadap orang-orang yang menyembah mereka. Lafal Fayaquulu dapat pula dibaca Fanaquulu, artinya, Kami berkata, (\"Apakah kalian) lafal A-antum dapat dibaca secara Tahqiq yaitu dengan menyatakan kedua Hamzahnya, dan dapat pula dibaca Tas-hil yaitu dengan menggantikan Hamzah yang kedua menjadi Alif sehingga bacaan Hamzahnya menjadi panjang, dapat pula dibaca pendek yakni tanpa memakai Alif (yang menyesatkan hamba-hamba-Ku itu) artinya apakah kalian telah menjerumuskan mereka ke dalam kesesatan dengan perintah kalian kepada mereka, supaya mereka menyembah kalian? (atau mereka sendirilah yang sesat dari jalan yang benar?\") yakni atas kehendak mereka sendiri.",[["وَيَوْمَ","And (the) Day"],["يَحْشُرُهُمْ","He will gather them"],["وَمَا","and what"],["يَعْبُدُونَ","they worship"],["مِن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["فَيَقُولُ","and He will say"],["ءَأَنتُمْ","Did you"],["أَضْلَلْتُمْ","[you] mislead"],["عِبَادِى","My slaves"],["هَـٰٓؤُلَآءِ","these"],["أَمْ","or"],["هُمْ","they"],["ضَلُّوا۟","went astray"],["ٱلسَّبِيلَ","(from) the way"]]],"2873":["(Mereka yang disembah itu menjawab, \"Maha Suci Engkau,) dari apa yang tidak layak bagi Engkau (tidaklah patut) tidaklah dibenarkan (bagi kami mengambil selain Engkau) (untuk jadi pelindung) lafal Min Auliyaa berkedudukan menjadi Maf'ul pertama, sedangkan huruf Min adalah Zaidah yang berfungsi mengukuhkan makna Nafi. Lafal sebelumnya berkedudukan menjadi Maf'ul kedua. Maksudnya, mana mungkin kami memerintahkan mereka untuk menyembah kami (akan tetapi Engkau telah memberi mereka dan bapak-bapak mereka kenikmatan hidup) sebelumnya yaitu di dunia, dengan umur yang panjang dan rezeki yang luas. (Sampai mereka lupa akan peringatan) yakni nasihat dan iman kepada Alquran (dan mereka adalah kaum yang binasa.\") Allah berfirman:",[["قَالُوا۟","They say"],["سُبْحَـٰنَكَ","Glory be to You"],["مَا","Not"],["كَانَ","it was proper"],["يَنۢبَغِى","it was proper"],["لَنَآ","for us"],["أَن","that"],["نَّتَّخِذَ","we take"],["مِن","besides You"],["دُونِكَ","besides You"],["مِنْ","any"],["أَوْلِيَآءَ","protectors"],["وَلَـٰكِن","But"],["مَّتَّعْتَهُمْ","You gave them comforts"],["وَءَابَآءَهُمْ","and their forefathers"],["حَتَّىٰ","until"],["نَسُوا۟","they forgot"],["ٱلذِّكْرَ","the Message"],["وَكَانُوا۟","and became"],["قَوْمًۢا","a people"],["بُورًۭا","ruined"]]],"2874":["(\"Maka sesungguhnya mereka yang disembah itu telah mendustakan kalian) yang disembah itu berdusta kepada mereka yang menyembahnya (tentang apa yang kalian katakan) bahwasanya mereka adalah tuhan-tuhan (maka kalian tidak akan dapat) kalau dibaca yastathii'uuna artinya maka mereka tidak akan dapat; maksudnya baik mereka atau pun kalian (menolak) azab dari diri kalian (dan tidak pula menolong) mencegah azab yang menimpa diri kalian (dan barang siapa berbuat zalim) dengan memperbuat kemusyrikan (di antara kalian, niscaya Kami rasakan kepadanya azab yang besar) azab yang keras di akhirat.",[["فَقَدْ","So verily"],["كَذَّبُوكُم","they deny you"],["بِمَا","in what"],["تَقُولُونَ","you say"],["فَمَا","so not"],["تَسْتَطِيعُونَ","you are able"],["صَرْفًۭا","(to) avert"],["وَلَا","and not"],["نَصْرًۭا ۚ","(to) help"],["وَمَن","And whoever"],["يَظْلِم","does wrong"],["مِّنكُمْ","among you"],["نُذِقْهُ","We will make him taste"],["عَذَابًۭا","a punishment"],["كَبِيرًۭا","great"]]],"2875":["(Dan Kami tidak mengutus rasul-rasul sebelum kamu, melainkan mereka sungguh memakan makanan dan berjalan di pasar-pasar) maka kamu adalah sama seperti mereka dalam hal ini. Maksudnya, telah dikatakan pula hal yang serupa terhadap mereka, sebagaimana apa yang dikatakan kepadamu sekarang ini. (Dan Kami jadikan sebagian kalian cobaan bagi sebagian yang lain) yakni orang yang kaya dicoba dengan adanya orang fakir dan orang yang sehat dicoba dengan adanya orang yang sakit, dan orang yang terhormat dicoba dengan adanya orang yang rendah. Maka golongan yang kedua dari orang-orang tadi mengatakan, 'Mengapa aku tidak seperti dia dalam segala hal?' (Maukah kalian bersabar?) di dalam menghadapi perkataan yang kalian dengar dari orang-orang yang kalian mendapat cobaan dari mereka. Istifham atau kata tanya di sini mengandung arti perintah, maksudnya bersabarlah kalian (dan adalah Rabbmu Maha Melihat\") terhadap orang-orang yang sabar dan yang tidak sabar.",[["وَمَآ","And not"],["أَرْسَلْنَا","We sent"],["قَبْلَكَ","before you"],["مِنَ","any"],["ٱلْمُرْسَلِينَ","Messengers"],["إِلَّآ","but"],["إِنَّهُمْ","indeed, they"],["لَيَأْكُلُونَ","[surely] ate"],["ٱلطَّعَامَ","food"],["وَيَمْشُونَ","and walked"],["فِى","in"],["ٱلْأَسْوَاقِ ۗ","the markets"],["وَجَعَلْنَا","And We have made"],["بَعْضَكُمْ","some of you"],["لِبَعْضٍۢ","for others"],["فِتْنَةً","a trial"],["أَتَصْبِرُونَ ۗ","will you have patience"],["وَكَانَ","And is"],["رَبُّكَ","your Lord"],["بَصِيرًۭا","All-Seer"]]]});